export type Section={id:string,title:string,paragraphs:string[],code?:string,language?:string};
export type Guide={slug:string,title:string,category:string,summary:string,goals:string[],sections:Section[],exercise:string[],answer:string,glossary:[string,string][],sources:{title:string,url:string}[]};
export const guides:Guide[]=[];
export function guideWords(g:Guide){return [g.title,g.summary,...g.goals,...g.sections.flatMap(s=>[s.title,...s.paragraphs]),...g.exercise,g.answer,...g.glossary.flat()].join(' ').split(/\s+/).length}
export function readingTime(g:Guide){return Math.ceil(guideWords(g)/180)}
guides.push({slug:'how-websites-work',title:'How websites work: from a click to a complete page',category:'Web foundations',summary:'Follow a browser request, understand the frontend and backend, and build a small page you can explain line by line.',goals:['Explain the browser–server relationship','Separate HTML, CSS, and JavaScript responsibilities','Build and troubleshoot a small interactive page'],sections:[
{id:'big-picture',title:'1. Start with the whole system',paragraphs:[`Imagine a school library website. A student wants to find a book, see whether a copy is available, and reserve it. On screen, this looks like a search field and a few buttons. Behind that interaction are separate responsibilities: showing the interface, receiving requests, applying borrowing rules, and keeping records. Learning web development becomes easier when you can name these responsibilities before choosing a framework.`,`The frontend is the part presented through the browser. The backend handles work on the server, such as deciding whether a reservation is allowed. A database keeps information that needs to survive beyond a single request. These are roles, not necessarily separate computers. A small project might place several roles together. A larger project might distribute them. Ask where each piece of work happens and which component owns each decision.`,`Draw three boxes: browser, application server, and database. Draw an arrow for a search request and another for its result. Label what travels on each arrow. This simple drawing can reveal missing assumptions more quickly than writing another component.`]},
{id:'journey',title:'2. Follow one request',paragraphs:[`When you enter a website address, the browser needs a way to reach the appropriate service. DNS helps resolve a hostname to addressing information. Network connections carry requests and responses; HTTPS adds protection through TLS. The browser requests a resource, and a server sends a response. Some responses contain HTML, while others contain an image, stylesheet, or data. Caches may satisfy some requests without contacting the original server.`,`Separate an address from a resource. In https://example.com/books, the hostname is example.com and the path is /books. The same host can provide many resources. A successful connection does not mean every path exists, and a working homepage does not prove that the search endpoint works. Each request has its own outcome.`,`Open your browser's developer tools and choose Network. Reload a page and observe the requests. Pick one document, one image, and one stylesheet. Compare their types and sizes. Do not worry about memorizing every column. Connect visible content to a real transfer instead of treating the entire page as one mysterious object.`]},
{id:'languages',title:'3. Give each language a clear job',paragraphs:[`HTML describes structure and meaning. A heading communicates hierarchy; a button communicates an action. CSS controls presentation, including spacing, color, layout, and adaptation to available space. JavaScript handles behavior such as reacting to a click or updating a result. The layers work together, but they should not obscure one another.`,`Consider a borrowing form. The label and input belong in HTML, the spacing belongs in CSS, and the response to submission belongs in JavaScript. If the page is unreadable until a script runs, ask whether essential content can be expressed in HTML first. If a clickable element is an action, start with a button so keyboard behavior comes with the correct element.`,`These boundaries help debugging. An item in the wrong position suggests a layout problem. A button that looks right but does nothing suggests an event or logic problem. Missing content suggests a rendering or data problem. This is a starting hypothesis, not a guarantee, but it gives your investigation direction.`]},
{id:'build',title:'4. Build a tiny interactive page',paragraphs:[`Save this example as index.html and open it in a browser. It has one job: update a message when a button is pressed. Keeping the exercise small makes it possible to understand every line. You do not need a database, package manager, or deployment service to learn this interaction.`,`The script appears after the elements it selects, so they exist when it runs. textContent updates plain text rather than interpreting the value as HTML. The status region helps announce the changed message to assistive technology. After clicking, use the Tab key to focus the button and activate it with the keyboard.`,`Modify the message, change the button label, and adjust the maximum width. Make one change at a time and predict its effect before reloading. Prediction turns copying into understanding. If the result differs, inspect the relevant element or read the console rather than randomly changing several lines.`],language:'HTML',code:`<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Library welcome</title>
  <style>
    body { font: 1rem/1.6 system-ui; max-width: 42rem; margin: 3rem auto; padding: 1rem; }
    button { font: inherit; padding: .7rem 1rem; }
  </style>
</head>
<body>
  <h1>Welcome to the library</h1>
  <p id="message" role="status">Ready to find your next book?</p>
  <button id="start" type="button">Start exploring</button>
  <script>
    const button = document.querySelector('#start');
    const message = document.querySelector('#message');
    button.addEventListener('click', () => {
      message.textContent = 'Choose a subject to learn today.';
    });
  </script>
</body>
</html>`},
{id:'state',title:'5. Understand what survives a reload',paragraphs:[`The message is temporary browser state. Refreshing restores its original value. A real reservation needs a durable record. The server should verify the user, check availability, and write a reservation to persistent storage. Showing a success message is not itself proof that a reservation was saved.`,`Imagine two students reserving the last copy at nearly the same time. A browser-only availability check can become outdated between viewing and submitting. The system that owns the record must enforce the rule when the change occurs. Interfaces can offer helpful early validation while the backend remains responsible for authoritative decisions.`,`For each feature, write down what the user sees, what the server must confirm, and what must be stored. Consider how the page behaves if the request fails. A useful error should preserve the student's input and explain a next action.`]},
{id:'debug',title:'6. Debug with evidence',paragraphs:[`Describe the failure precisely. “The page is broken” is difficult to investigate. “The button receives focus but the message never changes after activation” is more useful. Record expected behavior, actual behavior, and reproduction steps. Inspect the smallest relevant part of the system.`,`A misspelled selector can return null, and attaching a listener to that value will fail. A stylesheet can hide the message even when JavaScript updated it correctly. The console and element inspector answer different questions. Change one suspected cause, repeat the same steps, and verify the outcome.`,`Before sharing, try a narrow screen, keyboard navigation, and enlarged text. Look for clipped controls and missing focus indicators. These checks are part of whether the page works for people. A page is ready when its essential activity remains understandable and usable under realistic conditions.`]}],exercise:['Add a second button that restores the original message.','Explain what happens after a refresh and why.','Sketch the request and response needed for a real reservation.'],answer:'The reset button can assign the original string to message.textContent. A refresh loads the initial document because this example stores no persistent state. A real reservation needs a server to check permission and availability before storing the result.',glossary:[['Frontend','The interface and browser-side behavior presented to a user.'],['Backend','Server-side logic that receives requests and applies rules.'],['DNS','A system that resolves names to records, including addressing information.'],['State','Information describing the current condition of an application.']],sources:[{title:'MDN: Learn web development',url:'https://developer.mozilla.org/en-US/docs/Learn_web_development'},{title:'MDN: How the Internet works',url:'https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/How_does_the_Internet_work'}]});
guides.push({slug:'python-problem-solving',title:'Think like a programmer: a practical Python guide',category:'Programming',summary:'Turn a real problem into inputs, rules, functions, and tests using a small study planner.',goals:['Translate requirements into clear rules','Write a function with input validation','Test boundaries and explain the result'],sections:[
{id:'problem',title:'1. Describe the problem before the code',paragraphs:[`Suppose you have several lessons to study and want to spread them across the days before an exam. A first program can calculate a suggested number of lessons per day. Before opening an editor, define the question: given a nonnegative whole number of lessons and a positive whole number of days, what whole-number daily target is sufficient to cover the lessons?`,`There are hidden choices. Are partial lessons allowed? Does the program promise the same workload every day? What happens when there are no lessons or zero days? Our version returns a target rounded upward; it does not produce a complete schedule or estimate lesson difficulty. Those limits help keep the first solution honest.`,`Write three examples by hand: 12 lessons over 4 days gives 3; 13 lessons over 4 days gives 4; zero lessons over 4 days gives 0. These are small enough to check without software. They will become tests once the function exists.`]},
{id:'data',title:'2. Choose data that matches the meaning',paragraphs:[`A variable associates a name with a value. Good names connect a calculation to its requirement. lessons and days are more useful here than x and y. An integer represents a whole-number count. A string represents text, even when its characters look numeric. That distinction matters when accepting input from a person or a file.`,`Keep the boundary between input collection and calculation visible. A text field might contain spaces, an empty string, or a sentence. The calculation should not silently guess what those values mean. A surrounding interface can ask the user to correct input before passing validated values to the function.`,`Think about units as well as types. A variable called time could mean days, minutes, or seconds. Naming it days makes an accidental unit conversion easier to notice. Many bugs arise when two pieces of code agree on a type while disagreeing about what the value represents.`]},
{id:'function',title:'3. Put one rule in one function',paragraphs:[`The function below accepts two values and returns the daily target. Integer arithmetic avoids introducing floating-point rounding for this whole-number problem. Adding days minus one before integer division rounds upward for the nonnegative lesson counts allowed by the validation.`,`The checks deliberately reject booleans as well as fractional numbers. Python treats bool as a subclass of int, so a plain isinstance check would accept True as an integer. This example chooses strict built-in integer inputs to match its specification. That is a local design choice, not a requirement for every Python program.`,`Returning a value and printing it are different actions. A returned value can be reused, tested, or displayed in a graphical interface. Printing writes a representation for a person to see. Keeping calculation separate from display makes a function easier to compose with other parts of a program.`],language:'Python 3',code:`def daily_target(lessons, days):
    if type(lessons) is not int or type(days) is not int:
        raise TypeError("Lessons and days must be whole numbers")
    if lessons < 0:
        raise ValueError("Lessons cannot be negative")
    if days <= 0:
        raise ValueError("Days must be greater than zero")
    return (lessons + days - 1) // days

print(daily_target(13, 4))  # 4`},
{id:'flow',title:'4. Follow execution one step at a time',paragraphs:[`Conditions let a program choose a path. Invalid values cause an exception before this calculation. Valid values reach the return statement. Trace daily_target(13, 4) on paper: both values are integers; thirteen is not negative; four is positive; the expression evaluates to sixteen divided by four using integer division.`,`A loop repeats work. To compare several deadlines, call the same function for each candidate number of days rather than copying the formula. Keeping the rule in one function means every comparison follows the same behavior. Repeated copies of a formula create opportunities for one version to drift away from the others.`,`When tracing becomes difficult, reduce the input. Use two candidate deadlines rather than two hundred. Observe values at the start of each iteration. Build a reliable explanation of the output instead of merely finding a change that makes an error disappear.`],language:'Python 3',code:`for available_days in [3, 4, 7]:
    target = daily_target(13, available_days)
    print(f"{available_days} days: {target} lessons per day")`},
{id:'testing',title:'5. Test the boundaries that define the rule',paragraphs:[`Ordinary cases are useful, but boundaries expose incomplete rules. Zero lessons should work because there is nothing to cover. One day should require all remaining lessons. Zero days should fail because there is no valid study period. A negative count should fail because it does not represent the problem we defined.`,`These assertions are lightweight learning checks. A failed assertion interrupts execution and points to a mismatch. Run them after the function definition in a local Python file. A maintained project can use a test framework to organize more cases and provide clearer reports.`,`Tests should explain meaningful behavior. Checking only that the function returns an integer would miss a target too small to finish the lessons. Check expected results and rejected inputs. When you find a bug, add a case that exposes that mistake so it is less likely to return unnoticed.`],language:'Python 3',code:`assert daily_target(12, 4) == 3
assert daily_target(13, 4) == 4
assert daily_target(0, 4) == 0
assert daily_target(9, 1) == 9

try:
    daily_target(4, 0)
except ValueError:
    pass
else:
    raise AssertionError("Zero days should be rejected")`},
{id:'growth',title:'6. Grow the program without losing its meaning',paragraphs:[`The target is conservative. Thirteen lessons over four days yields four, but doing four each day would exceed thirteen. A complete schedule could distribute workloads as four, three, three, and three. This is a different output with a different promise. Treat it as a new requirement instead of quietly changing the existing function's meaning.`,`Another extension is lesson duration. A short revision topic and a long practical lab should not automatically have the same weight. Represent each lesson with a title and estimated minutes, then allocate time instead of counts. Decide whether a lesson can be split and how to handle an impossible schedule before writing code.`,`Keep calculations separate from presentation and storage. A function receiving and returning plain data is straightforward to test. An interface can collect inputs, display results, and explain errors. You can improve that interface without rewriting the study rule.`,`Practice deliberate decomposition: describe a task, choose meaningful data, isolate a rule, verify examples, and then connect more parts. You do not need every language feature to solve useful problems. You need reliable building blocks and the ability to explain why your solution satisfies its requirement.`]}],exercise:['Predict the result for 17 lessons over 5 days.','Test negative lessons, a fractional day count, and a boolean.','Design a separate function returning exact daily workloads.'],answer:'The target for 17 lessons over 5 days is 4. For an exact schedule, divide lessons into a quotient and remainder. Give one extra lesson to the first remainder days. Verify that the list has the requested length and its sum equals the lesson count.',glossary:[['Function','A named block of code that accepts inputs and can return a result.'],['Exception','A signal that interrupts normal execution when a problem occurs.'],['Boundary case','An input near the edge of allowed behavior.'],['Specification','An explicit description of required program behavior.']],sources:[{title:'Python tutorial',url:'https://docs.python.org/3/tutorial/'},{title:'Python: Control flow and functions',url:'https://docs.python.org/3/tutorial/controlflow.html'}]});
guides.push({slug:'git-team-workflow',title:'Git without guesswork: a workflow for real projects',category:'Developer workflow',summary:'Understand working files, staging, commits, and branches through a focused documentation change.',goals:['Explain what a commit contains','Review a change before recording it','Use a branch and resolve conflicts thoughtfully'],sections:[
{id:'history',title:'1. Treat history as a record of decisions',paragraphs:[`Imagine maintaining a club website with two classmates. One edits the event schedule, another updates joining instructions, and you improve the contact page. A folder of files named final, final2, and final-really-final does not explain which changes belong together. Git records project states and their relationships. Good history makes a change understandable to someone absent when it was made.`,`A useful commit answers what changed and why. “Fix stuff” tells a future reader almost nothing. “Clarify the joining deadline for new members” gives a purpose that can be compared with the actual differences. The message does not replace reviewing the code, but it provides context.`,`Start with a small, complete change. A documentation correction is a better first exercise than simultaneously redesigning a site, updating dependencies, and reorganizing every folder. Smaller changes reduce the possible causes when something later behaves differently.`]},
{id:'areas',title:'2. Distinguish files, staging, and history',paragraphs:[`The working tree contains the files you edit. The staging area describes changes selected for the next commit. A commit records the staged state with metadata and links to parent history. Editing does not automatically stage a file, and staging does not publish it to other people.`,`This separation helps when an editing session produces unrelated changes. Record a corrected deadline first and a separate design improvement later. Before committing, examine both the unstaged and staged differences. They answer different questions: what remains outside the next commit, and what is about to be included?`,`Replace README.md below with the file you changed. These commands assume Git is installed and you are inside a repository. They inspect the current state, select a file, and inspect the selected difference. Pause and read that difference before committing.`],language:'Terminal',code:`git status
git diff
git add README.md
git diff --staged
git commit -m "Clarify the club joining deadline"`},
{id:'branch',title:'3. Name a focused line of work',paragraphs:[`A branch gives a movable name to a line of history. It lets you develop a focused change while keeping the project's main line understandable. Creating a branch does not make an independent disk copy of every file. The working tree reflects the checked-out branch and state, subject to uncommitted changes.`,`Before starting, inspect git status and understand existing edits. Agree on a starting branch and synchronization procedure in shared projects. Not every repository calls its main branch main. Switching branches is not a way to make unrelated edits disappear safely.`,`The example creates a branch for one documentation task. After committing, read the short history and confirm the new commit appears where expected. A branch name should describe the work well enough that a teammate can distinguish it from other ongoing tasks.`],language:'Terminal',code:`git status
git switch -c docs/joining-deadline
# Edit, review, stage, and commit the intended change.
git log --oneline -5`},
{id:'review',title:'4. Review as a future maintainer',paragraphs:[`A review is a structured attempt to understand a change, not just a search for punctuation mistakes. Ask whether the change solves the stated problem, whether adjacent behavior still works, and whether the implementation introduces a new assumption. For a deadline correction, check every place users encounter the date. For code, follow the affected data through its relevant paths.`,`Explain how you verified the result. “Checked the joining page at narrow width and followed the form link” is more useful than an unexplained “tested.” Choose evidence proportional to the change. A paragraph edit usually needs no new automated test; a calculation used throughout an application probably does.`,`Keep generated files, credentials, and unrelated formatting changes out of a review unless they belong to the task. An accidental long diff makes important changes harder to judge. Investigate unexpected files before including them. A clean review lets someone concentrate on the actual decision.`]},
{id:'conflicts',title:'5. Resolve conflicts by preserving intent',paragraphs:[`A conflict means Git could not automatically reconcile competing changes. It does not mean one contributor is wrong. One classmate might correct a meeting time while another rewrites the same sentence. The result may need both the new time and clearer wording. Mechanically choosing an entire side can discard valid work.`,`Read surrounding content and understand each change's purpose. Edit the intended final version, remove conflict markers, and review it. Stage the resolution and follow the instructions displayed by git status for the operation in progress. Merge and rebase continuation workflows differ, so the same final command does not fit every situation.`,`If the intended outcome is unclear, ask about the requirement. For code, run relevant checks after resolving the conflict. A file without conflict markers can still contain a logical mistake. Mechanical completion means Git can record the result; it does not prove the application behaves correctly.`]},
{id:'recovery',title:'6. Recover deliberately and collaborate clearly',paragraphs:[`Before undoing anything, identify the state you want to change: staging, working files, or committed history. To remove a file from staging while keeping its edits, git restore --staged README.md is useful in a repository with a commit to restore from. It changes the proposed commit rather than erasing editing work.`,`Restoring a working file can discard uncommitted edits. Read command documentation and inspect status before recovery. Do not paste a destructive command from an unrelated troubleshooting answer. If uncertain, preserve a copy of affected work and investigate with read-only commands.`,`A remote is a destination for exchanging Git history. Committing locally and pushing are separate actions. Your team may use a pull request or merge request before changes reach the main line. Agree on naming, review expectations, and merge ownership to make collaboration predictable.`,`Git works best as a communication tool. Keep changes focused, explain their purpose, review what you stage, and verify the integrated result. Aim for history that helps someone reason about the project months later, when nobody remembers every detail of the original task.`]}],exercise:['Create a practice repository and commit a short README.','Edit two sentences, stage the file, and compare git diff with git diff --staged.','Unstage the file and confirm that your edits remain.'],answer:'After staging all edits, git diff normally shows no unstaged difference while git diff --staged shows the selected changes. In the practice repository, git restore --staged README.md removes that selection but keeps the working file edited. Verify with status and diff.',glossary:[['Working tree','The checked-out files you edit.'],['Staging area','The proposed content of the next commit.'],['Commit','A recorded project state linked to its parent history.'],['Conflict','A change combination requiring a person to choose the intended result.']],sources:[{title:'Git reference',url:'https://git-scm.com/docs'},{title:'Git: commit',url:'https://git-scm.com/docs/git-commit'},{title:'Git: switch',url:'https://git-scm.com/docs/git-switch'},{title:'Git: restore',url:'https://git-scm.com/docs/git-restore'}]});
guides.push({slug:'apis-and-json',title:'APIs and JSON: build a reliable data conversation',category:'Backend & APIs',summary:'Design a small task API, read responses safely, and handle loading, empty, and failure states.',goals:['Describe an API contract','Distinguish parsing from validation','Handle HTTP errors and unexpected data'],sections:[
{id:'contract',title:'1. Define the conversation',paragraphs:[`An application programming interface defines how software interacts with another component. In a web application, an HTTP API often lets a browser request data or ask a server to perform an operation. A caller works with a documented contract instead of knowing every implementation detail.`,`Consider a student task board. The browser needs tasks with an identifier, title, and completion flag. That shape is only the beginning. The contract should state which requests are allowed, how permission is checked, what happens when no tasks exist, and how errors are represented.`,`Write example requests and responses before implementing both sides. An example may reveal that the frontend expects an array while the backend returns an object containing an array. Finding the mismatch on paper is cheaper than debugging two running applications. The API in this guide is hypothetical; DevShelf does not provide these endpoints.`]},
{id:'json',title:'2. Read JSON as structured data',paragraphs:[`JSON represents objects, arrays, strings, numbers, booleans, and null. An object groups named values; an array represents an ordered collection. Here tasks is an array because several tasks may exist, and each task is an object whose fields describe a record. Property names and string values use double quotes.`,`A parser checks JSON syntax. It does not prove that the result matches application expectations. The text 42 is valid JSON but is not the task-list response below. An object with a tasks property might still contain wrong field types. Keep syntax checking separate from application validation.`,`Use the DevShelf formatter to expand and minify the example. Whitespace changes while the intended data model stays the same. Remove a required quote and observe the error. Then change done from false to the string "false". This remains valid JSON but changes the field's meaning and type.`],language:'JSON',code:`{
  "tasks": [
    { "id": "task-1", "title": "Review networking notes", "done": false },
    { "id": "task-2", "title": "Practice Python functions", "done": true }
  ]
}`},
{id:'http',title:'3. Distinguish response outcomes',paragraphs:[`An HTTP response contains a status and may include headers and a body. A successful request can return an empty collection. A failed request might return structured error data or an HTML page generated by infrastructure. Do not assume every response has the JSON shape expected for success.`,`An empty tasks array is normal for our task board. The interface can explain that no tasks have been added. A permission failure needs a different response, such as asking the user to sign in when appropriate. A server failure should never be presented as an empty list, because that falsely suggests existing tasks disappeared.`,`Sketch loading, populated, empty, and error states separately. Decide whether previous results stay visible during refresh, where retry controls belong, and whether the action is safe to repeat. The user needs to distinguish having no information from waiting for information or failing to retrieve it.`]},
{id:'fetch',title:'4. Request and validate data',paragraphs:[`Browser fetch returns a response for HTTP error statuses such as 404, so check response.ok rather than relying only on promise rejection. Reading with response.json is asynchronous and can fail if the content is not JSON. The function below handles these stages explicitly.`,`After parsing, validate the fields your application needs. Here tasks must be an array, and every item must contain expected primitive fields. A larger application may use a schema library for nested data or shared contracts. The principle is the same: received data is not automatically valid application data.`,`Run this example only in a project with a matching /api/tasks endpoint. It is an integration example, not a live public service. A caller should catch failures and show a useful error rather than leaving an unhandled promise rejection in the console.`],language:'JavaScript',code:`async function loadTasks() {
  const response = await fetch('/api/tasks', {
    headers: { Accept: 'application/json' }
  });
  if (!response.ok) {
    throw new Error('Task request failed: ' + response.status);
  }
  const data = await response.json();
  if (!data || !Array.isArray(data.tasks)) {
    throw new Error('Expected a tasks array');
  }
  const valid = data.tasks.every(task =>
    task !== null && typeof task === 'object' &&
    typeof task.id === 'string' &&
    typeof task.title === 'string' &&
    typeof task.done === 'boolean'
  );
  if (!valid) throw new Error('Unexpected task data');
  return data.tasks;
}`},
{id:'writes',title:'5. Design changes and permissions together',paragraphs:[`Reading and changing tasks have different consequences. Define what a write operation accepts and who may perform it. Hiding a button is not access control: a caller can construct a request outside the interface. The server owning the data must enforce permission for the operation.`,`A completion request also raises timing questions. What if the user clicks twice? What if the request succeeds but its response is lost? What if another device changes the task? Explicitly setting done to true can be easier to reason about than blindly toggling it with every repeated request. The API's documented semantics determine the right approach.`,`Keep private service credentials on the server when required by the design. A value sent to browser JavaScript is available to the browser's user. Renaming it or using Base64 does not make it secret. Base64 is a representation format, not encryption. This distinction matters when a local exercise becomes a shared application.`]},
{id:'diagnose',title:'6. Diagnose failure systematically',paragraphs:[`Inspect the request URL, method, status, and response body in the Network panel. Compare them with the contract. Did the frontend call the wrong path? Did the server return an error object or HTML? Gather observations before changing code. Separate routing problems from parsing and permission problems.`,`Browser cross-origin rules can prevent a page from reading another origin's response unless the server permits the interaction. Switching fetch to no-cors is not a general fix for reading blocked JSON; an opaque response is not normally readable. Use supported server configuration or an appropriate backend integration.`,`Test an empty array, a missing field, a wrong type, an HTTP error, and invalid JSON. Consider overlapping searches: an older response should not unexpectedly replace a newer result. Cancellation or request tracking may be appropriate depending on the interface.`,`Reliable API integration rests on explicit agreements. The caller requests a defined operation, the server verifies and performs it, and the interface communicates the outcome honestly. When these agreements are visible, testing and debugging become systematic instead of a sequence of guesses.`]}],exercise:['Introduce a syntax error in the example JSON and inspect the formatter result.','Change a completion flag into a string and explain why parsing does not reject it.','Write different interface messages for loading, empty data, and failure.'],answer:'Missing quotes should cause a parsing error. A string-valued flag remains valid JSON but violates the expected schema. Use distinct messages such as “Loading tasks,” “No tasks yet,” and “Could not load tasks—try again” so a failed request is never mistaken for an empty account.',glossary:[['API contract','The agreement about requests, responses, and behavior.'],['JSON','A text format for structured data.'],['Validation','Checking whether data satisfies application rules.'],['HTTP status','A code describing an HTTP request outcome.']],sources:[{title:'MDN: HTTP overview',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Overview'},{title:'MDN: Using Fetch',url:'https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch'}]});
guides.push({slug:'networking-troubleshooting',title:'Networking fundamentals: trace a connection before fixing it',category:'IT foundations',summary:'Understand addresses, ports, DNS, and a practical troubleshooting process for local and remote services.',goals:['Distinguish a host from a service','Understand localhost and DNS','Use evidence to narrow connection failures'],sections:[
{id:'layers',title:'1. Separate the pieces of a connection',paragraphs:[`A student reports that a learning portal is unavailable. That description could mean the laptop has no network connection, the hostname cannot be resolved, the server is unreachable, or the application returns an error. These failures live at different parts of the path. Changing application code will not fix every connection problem.`,`Begin with a map: device, local network, router, destination host, and application service. The diagram need not represent every cable or provider. It should identify the boundaries where you can observe a different result. Write down the exact address and error message before trying a fix.`]},
{id:'address',title:'2. An address identifies a destination, a port identifies a service',paragraphs:[`An IP address helps traffic reach a network interface. A transport port distinguishes a service endpoint on that host. One computer can run several services without assigning each one a separate physical network card. A website might listen on one port while a development API uses another.`,`For http://localhost:3000, localhost refers to the device making the request and 3000 identifies the requested port. Opening that address on a phone refers to the phone, not your laptop. A URL that works on the development computer is therefore not automatically a shareable website address.`]},
{id:'names',title:'3. Names add a separate lookup step',paragraphs:[`DNS translates names into records that help clients find services. A human-readable hostname can stay stable while the infrastructure behind it changes. Name resolution and application availability are separate questions: a valid DNS response does not prove a web application is healthy.`,`A browser may reuse cached information, and a service may have several addresses. Record which hostname you tested and when. If one application works while another fails, avoid immediately concluding that the entire internet connection is broken. Compare the specific destinations and symptoms.`]},
{id:'local',title:'4. Start with a service you control',paragraphs:[`For a local web project, first verify that the development server is running and note the exact address it prints. If it moved to another port because the original was occupied, the old browser tab may point at the wrong process. Read the server output instead of assuming the port.`,`An HTTP response, including an error status, tells you that some server answered. A connection refusal often points toward no listener at the selected endpoint or an active rejection. A timeout is less specific and requires more evidence. Treat symptoms as clues rather than definitive diagnoses.`],language:'PowerShell · local read-only check',code:`# Run while your own development server is listening.
Invoke-WebRequest http://localhost:3000/ -SkipHttpErrorCheck
# Inspect StatusCode and the server log together.`},
{id:'method',title:'5. Change one variable at a time',paragraphs:[`Build a short investigation table with test, observation, and implication. “Homepage returns 200 but /api/tasks returns 404” is a much stronger clue than “network broken.” It suggests investigating the route or endpoint configuration before replacing network settings.`,`Test only systems you own or are authorized to troubleshoot. Preserve the failing condition long enough to gather useful evidence. Repeatedly restarting everything may hide the symptom without explaining it, making the next occurrence just as difficult to investigate.`]},
{id:'handoff',title:'6. Write a useful support handoff',paragraphs:[`A useful report includes the affected feature, exact URL with sensitive values removed, time of failure, expected behavior, actual result, and tests already performed. Mention whether the failure affects one device or several. Include relevant status codes without copying private response data unnecessarily.`,`After a fix, repeat the original failing steps and test a nearby successful case. Document what changed and why it addresses the observation. The goal is a repeatable explanation, not a lucky recovery that nobody can reproduce.`]}],exercise:['Explain why localhost on two devices can show different results.','Compare a missing route with a stopped local server.','Write a three-line incident report for a failing task endpoint.'],answer:'Each device resolves localhost to itself. A missing route can return an HTTP 404 from a running server, while a stopped listener cannot serve that request. A useful report names the route, observed status or connection error, and the successful comparison test.',glossary:[['Port','A numbered transport endpoint used to distinguish services.'],['Localhost','A hostname referring to the device making the request.'],['DNS','A distributed naming system that returns records for names.']],sources:[{title:'MDN: Client-server overview',url:'https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Client-Server_overview'},{title:'MDN: HTTP overview',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Overview'}]});
guides.push({slug:'linux-command-line',title:'Linux essentials: files, processes, and a careful terminal workflow',category:'IT foundations',summary:'Navigate a Linux environment, inspect files and running processes, and understand permissions without guessing.',goals:['Read paths confidently','Inspect before changing files','Recognize process and permission problems'],sections:[
{id:'shell',title:'1. Know what the terminal is running',paragraphs:[`A terminal provides an interface to a shell. The shell interprets commands and launches programs. A command may be built into the shell or supplied by a separate executable. The examples in this lesson assume a Linux environment with a Bash-like shell; they are not PowerShell commands.`,`Working in a terminal does not make an action inherently more correct than using a graphical interface. Its advantage is precision and repeatability. That precision also means a wrong path can target the wrong file. Begin every unfamiliar session by establishing where you are.`]},
{id:'paths',title:'2. Orient yourself before editing',paragraphs:[`An absolute path begins at the filesystem root. A relative path is interpreted from your current working directory. The same relative filename can refer to different files after you change directories. This is why a command copied from instructions may behave differently in your current shell.`,`Use the read-only commands below to establish context. Then move into a practice directory you created for learning. Quote filenames containing spaces. Prefer a small directory containing disposable exercises when learning unfamiliar file operations.`],language:'Linux shell',code:`pwd
ls -la
# Read a small text file that exists in the current directory.
cat "notes.txt"
# Inspect running processes.
ps -ef`},
{id:'streams',title:'3. Think of commands as producers and consumers',paragraphs:[`Many command-line tools receive input and produce output. A pipe can connect the output of one command to the input of another. This makes small tools useful in combination. Before composing a long pipeline, run each step separately and inspect the result.`,`Output redirection is different from simply displaying text. Redirecting to a file can replace its contents depending on the operator used. Read the command carefully before running it, especially when an example includes a path that already contains important work. A terminal usually cannot infer what you meant to preserve.`]},
{id:'permissions',title:'4. Treat permission errors as information',paragraphs:[`Linux permissions associate access rights with an owner, group, and other users. A permission failure can mean your current account is not allowed to read, write, or execute the requested item. It can also reveal that the file was created under a different account than expected.`,`Do not respond to every failure by adding elevated privileges. First inspect the path, ownership, and the operation's purpose. Ask whether this account should perform the action at all. Broadly making project files writable may hide one error while introducing a larger maintenance or security problem.`]},
{id:'processes',title:'5. Distinguish files from running programs',paragraphs:[`A process is a running instance of a program. Saving a file does not always cause a running service to reload it. Conversely, deleting or changing a source file may not immediately stop an already-running process. You need to understand how the application loads configuration and code.`,`When a service fails, gather its logs and confirm whether it is still running. Note the user account and launch method. A program started manually in your terminal may not behave like the same program launched as a managed service because its environment and working directory can differ.`]},
{id:'routine',title:'6. Build a repeatable routine',paragraphs:[`Use a short routine: establish the directory, inspect the target, perform one intended action, and verify the result. Keep notes about commands that solve a specific problem, including the assumptions under which they work. A copied command without context is a poor troubleshooting record.`,`For each exercise, explain the before and after state. If you cannot describe which files or processes are affected, pause and read the relevant manual. Competence at the terminal grows from understanding scope and consequences rather than typing long commands quickly.`]}],exercise:['Find your current directory and list its hidden entries.','Explain how a relative path changes meaning after changing directories.','Describe why a permission error does not automatically justify elevated privileges.'],answer:'pwd shows the current directory and ls -la includes hidden entries. Relative paths start from that directory. Before escalating privileges, inspect ownership and confirm that the requested operation belongs to your account and task.',glossary:[['Shell','A command interpreter that launches programs.'],['Process','A running instance of a program.'],['Relative path','A path interpreted from the current directory.']],sources:[{title:'Ubuntu: The Linux command line for beginners',url:'https://ubuntu.com/tutorials/command-line-for-beginners'}]});
guides.push({slug:'sql-data-models',title:'Databases and SQL: model the information before querying it',category:'Data & backend',summary:'Build a small course catalog, write readable queries, and reason about keys, constraints, and transactions.',goals:['Design records with stable identifiers','Read and filter data using SQL','Understand constraints and atomic changes'],sections:[
{id:'model',title:'1. Start with the questions your data must answer',paragraphs:[`A learning platform needs to know which courses exist, who enrolled, and which lessons a learner completed. Putting everything into one text field makes those questions difficult to answer reliably. A data model gives each important concept a defined structure and explains how records relate.`,`Write the questions first: which courses are published, which enrollments belong to one learner, and which lessons remain incomplete? These questions guide the fields and relationships you need. Avoid collecting extra personal information just because a database makes it easy to add another column.`]},
{id:'keys',title:'2. Separate identity from display text',paragraphs:[`A primary key identifies a row. A course title is usually a poor identity because titles can change and two courses can have similar names. A stable course identifier lets other tables refer to the course without duplicating its entire description.`,`An enrollment can connect a learner identifier with a course identifier. A foreign key can require referenced records to exist. Constraints represent rules the database should enforce even when several application paths write to it. Interface validation alone cannot guarantee consistent stored data.`]},
{id:'query',title:'3. Read a result deliberately',paragraphs:[`The example uses a temporary PostgreSQL table in your own practice database. Its name reduces the chance of colliding with a real table. The SELECT statement chooses columns, filters rows, and applies an explicit ordering. Without ORDER BY, do not rely on a particular row order.`,`Run the query, predict the returned titles, then change the filter. Explain which rows were excluded and why. Selecting only the fields needed by a caller can make the result easier to understand than indiscriminately returning every column.`],language:'PostgreSQL · practice session',code:`CREATE TEMP TABLE learning_catalog_demo (
  id integer PRIMARY KEY,
  title text NOT NULL,
  published boolean NOT NULL DEFAULT false
);
INSERT INTO learning_catalog_demo (id, title, published)
VALUES (1, 'Web basics', true), (2, 'SQL practice', false);

SELECT id, title
FROM learning_catalog_demo
WHERE published = true
ORDER BY title;`},
{id:'changes',title:'4. Make related changes together',paragraphs:[`Suppose enrollment consumes the last available seat. Updating the enrollment and seat count as unrelated operations can leave inconsistent data if one step fails. A transaction groups work so the application can commit the intended changes together or roll them back.`,`Concurrency adds another question: what happens when two people request the final seat simultaneously? A successful interface check performed seconds earlier is insufficient. The database operation must enforce the rule at the moment of the change, using an appropriate transaction and concurrency design.`]},
{id:'inputs',title:'5. Keep values separate from query structure',paragraphs:[`When application input becomes part of a query, use the database driver's parameter mechanism. Building SQL by concatenating user text can allow that text to alter query meaning. The exact placeholder syntax depends on the driver; follow its documentation rather than copying a placeholder from another language.`,`Validate inputs according to product rules as well. A parameterized query protects query structure, but it does not decide whether a requested course is available or whether the caller can edit it. These are separate checks with separate purposes.`]},
{id:'operations',title:'6. Plan for changes and recovery',paragraphs:[`A migration records a deliberate schema change. Review how existing data will fit a new constraint before applying it. Adding a required field raises questions about old rows, default values, and the order in which application and database changes are released.`,`An index can help a database locate relevant rows, but it also uses storage and affects writes. Measure an actual query and inspect its plan before adding indexes indiscriminately. Finally, test restoration from backups. A backup that exists but cannot be restored has not demonstrated the recovery your application needs.`]}],exercise:['Predict the sample query result.','Explain why a course title should not be the only identifier.','Describe what must happen if a two-step enrollment transaction fails halfway.'],answer:'The query returns Web basics, because SQL practice is unpublished. A stable identifier survives title changes. If the intended changes are in one transaction and the operation fails, roll it back so a partial enrollment does not remain.',glossary:[['Primary key','A column or set of columns uniquely identifying a row.'],['Constraint','A database-enforced rule on stored data.'],['Transaction','A unit of work that can be committed or rolled back.']],sources:[{title:'PostgreSQL: SQL tutorial',url:'https://www.postgresql.org/docs/current/tutorial-sql.html'}]});
guides.push({slug:'security-by-design',title:'Security basics: protect a feature from the first design',category:'Security',summary:'Reason about identity, permissions, untrusted input, secrets, and recovery using a student portal.',goals:['Separate authentication from authorization','Locate trust boundaries','Plan concrete security checks for one feature'],sections:[
{id:'assets',title:'1. Decide what you are protecting',paragraphs:[`Security begins with understanding the feature and the people affected. A student portal might store profile details, coursework, and teacher feedback. A public course title has different handling requirements from a private submission. List the information involved and who should be able to read or change it.`,`Consider mistakes as well as deliberate abuse. An incorrectly configured link can expose a document without anyone exploiting complicated code. A design review should ask what happens when the wrong person receives a URL, an account is compromised, or a support operator chooses the wrong record.`]},
{id:'identity',title:'2. Verify identity and permission separately',paragraphs:[`Authentication establishes an identity. Authorization decides whether that identity may perform a particular action on a particular resource. Being signed in does not mean a learner may read another learner's submissions. A role label in the interface does not enforce the rule.`,`For a submission endpoint, the server should connect the caller to the requested record and check the relevant policy. Test two ordinary accounts with separate records. A request that succeeds for its owner should fail for an unrelated learner unless sharing was intentionally granted.`]},
{id:'boundaries',title:'3. Treat received values as untrusted',paragraphs:[`Browser forms are only one way to send data. A caller can bypass them or modify a request. Validate expected structure, types, ranges, and allowed operations at the boundary that owns the decision. Render user text using safe text handling instead of interpreting it as executable markup.`,`A filename supplied by a user should not automatically become a filesystem path. An identifier should not automatically grant access to the matching row. Look for places where received data is transformed into an instruction, location, or privileged operation. These boundaries deserve explicit design.`]},
{id:'secrets',title:'4. Give secrets a controlled lifecycle',paragraphs:[`A private API credential included in frontend JavaScript is available to the user running that JavaScript. Encoding it or using an obscure variable name does not make it private. Keep credentials in an appropriate server-side secret mechanism and restrict their scope to the work they need to perform.`,`Plan what happens if a credential is exposed: revoke or rotate it, identify where it was used, and check affected systems. Removing a key from the latest source file is not enough if it remains valid or appears in old history. Prevention and recovery should both have an owner.`]},
{id:'verification',title:'5. Turn rules into checks',paragraphs:[`Write a small permission matrix for the submission feature. An owner may read their submission, a designated reviewer may evaluate it, and an unrelated learner may do neither. Test those outcomes through the actual server interface, not merely by inspecting which buttons are visible.`,`Use meaningful negative cases. Try an unknown record, a record owned by someone else, and a malformed request. Confirm that errors do not reveal unnecessary private details. Keep test accounts and data separate from real sensitive material.`],language:'Example permission matrix',code:`Action: read a private submission
Owner                 → allowed
Assigned reviewer     → allowed by review policy
Unrelated learner     → denied
Unauthenticated caller → denied`},
{id:'maintenance',title:'6. Keep protection working over time',paragraphs:[`Security changes as a product gains features and dependencies. Review new data flows, apply supported updates, and monitor events that help identify failures. Logs should support investigation without becoming a second uncontrolled store of passwords, credentials, or private content.`,`Use a risk reference such as OWASP to guide questions, not as proof that a feature is secure because a checklist was ticked. A useful final review ties each important rule to evidence: where it is enforced, how it was tested, and how the team would detect and recover from a failure.`]}],exercise:['Write a permission matrix for a private assignment.','Explain why hiding an edit button is insufficient.','List the actions needed after a private API key is exposed.'],answer:'The server must enforce the matrix for each requested record. Hidden buttons do not stop direct requests. An exposed key needs revocation or rotation, investigation of its usage and scope, and removal from places where it was unintentionally distributed.',glossary:[['Authentication','Establishing the identity of a caller.'],['Authorization','Deciding whether a caller may perform an operation.'],['Trust boundary','A point where data crosses between different levels of trust.']],sources:[{title:'OWASP: Web application security risk reference',url:'https://owasp.org/www-project-top-ten/'}]});
guides.push({slug:'containers-and-delivery',title:'Containers and cloud delivery: understand what runs where',category:'Cloud & operations',summary:'Separate an image from a running container, plan persistent data, and design a basic release workflow.',goals:['Explain images and containers','Separate configuration from an artifact','Plan health checks and recovery'],sections:[
{id:'environment',title:'1. Make the runtime explicit',paragraphs:[`An application that works on one laptop can fail elsewhere because a runtime, library, environment variable, or system dependency differs. The first step toward repeatability is identifying these assumptions. Write down how the program starts, what it depends on, and which resources it expects to reach.`,`A container image packages a filesystem and runtime configuration used to launch a container. A container is a running instance based on that image. This can reduce differences between environments, but it does not make an application independent of architecture, host capabilities, network configuration, or external services.`]},
{id:'artifact',title:'2. Separate the release artifact from its settings',paragraphs:[`Treat a release artifact as something you can identify precisely. If development and production each rebuild different dependencies, the two environments may not be running the same program. A repeatable pipeline should make it clear which source and dependencies produced the deployed artifact.`,`Configuration often differs by environment. A development database address should not be baked into an artifact intended for production. Supply configuration through supported runtime mechanisms, keep private values out of client bundles, and validate required settings at startup so a missing value creates an understandable failure.`]},
{id:'data',title:'3. Decide which data must survive',paragraphs:[`A running container may have writable state, but replacing the container can remove data stored only there. Application logs, uploads, and database records have different storage requirements. Classify each one before selecting a persistence mechanism.`,`A volume or external data service can preserve information beyond one container lifecycle, but persistence is not the same as backup. Ask how accidental changes are recovered, who controls access, and how restoration is tested. A containerized application still needs a data-management plan.`]},
{id:'network',title:'4. Trace the service boundary',paragraphs:[`A program can listen inside a container without being reachable at the host address a browser uses. Published ports and network configuration determine how traffic reaches the service. Trace the request from the user's URL through each boundary rather than assuming that starting a process makes it publicly accessible.`,`Containers provide isolation mechanisms, not a guarantee that arbitrary code is harmless. Run only the privileges and capabilities the application needs. If an exercise requires a container engine, follow the vendor's setup guidance in your own development environment before attempting to launch workloads.`]},
{id:'release',title:'5. Build a release checklist around behavior',paragraphs:[`A basic pipeline can install defined dependencies, run relevant checks, build an artifact, and release that artifact to a chosen environment. Each step should fail clearly when its prerequisite is missing. A successful build proves something narrower than a successful user journey.`,`After a release, verify a meaningful operation such as loading the catalog or submitting a test form. Health checks should reflect the purpose of the service rather than merely the existence of a process. Record the release identifier so an observed failure can be connected to the code that is running.`],language:'Conceptual release flow',code:`Source revision
  → dependency installation
  → relevant tests
  → build artifact
  → release to selected environment
  → verify health and a user journey`},
{id:'recovery',title:'6. Plan a way back before you need it',paragraphs:[`A rollback should have a clearly identified target, such as the previous known-good artifact. Database changes can complicate reversal: older code may not understand a new schema. Favor compatible transitions when appropriate and document the sequence needed for recovery.`,`Collect logs and measurements that answer operational questions: did the service start, are requests failing, and is latency changing? Avoid collecting data without a plan to use it. A useful operations routine makes the deployed system understandable to the next person responsible for it.`]}],exercise:['Explain image versus container in one sentence each.','List which data a learning portal must preserve across a release.','Define a post-release check more useful than “the process is running.”'],answer:'An image is a launchable artifact; a container is an instance running from it. Enrollment and completion records need durable storage and a recovery plan. Loading a known course and verifying a test enrollment checks meaningful behavior after release.',glossary:[['Image','A packaged artifact used to create containers.'],['Container','An isolated process environment launched from an image.'],['Artifact','An identified output of the build process.']],sources:[{title:'Docker: What is a container?',url:'https://docs.docker.com/get-started/docker-concepts/the-basics/what-is-a-container/'}]});
guides.push({slug:'testing-and-debugging',title:'Testing and debugging: turn uncertainty into evidence',category:'Developer workflow',summary:'Choose useful test cases, write a small automated check, and investigate a failure systematically.',goals:['Choose tests from behavior','Recognize useful boundary cases','Build a reproducible debugging report'],sections:[
{id:'purpose',title:'1. Describe the behavior you need confidence in',paragraphs:[`Testing is most useful when it answers a concrete question. Does a calculation reject an impossible input? Can one learner access another learner's work? Does the interface preserve a draft when a request fails? The answer determines which level of test provides useful evidence.`,`A unit test focuses on a small piece of logic. An integration test checks cooperating parts, such as an application and its storage interface. A user-journey test follows a visible workflow. These categories can overlap; their names matter less than knowing what a passing test actually demonstrates.`]},
{id:'cases',title:'2. Derive cases from the requirement',paragraphs:[`Suppose a lesson progress display accepts completed and total counts. A simple rule might return a rounded percentage, reject negative values, and reject completed counts greater than total. Decide how zero total is represented before writing the function. Otherwise two implementations can disagree while both seem reasonable.`,`List ordinary, boundary, and invalid examples. For each one, write an expected result or expected failure. Do not generate expected values using the exact same formula under test, because the test could repeat the implementation's mistake instead of detecting it.`]},
{id:'example',title:'3. Write a small, executable test',paragraphs:[`Save this example as progress.test.mjs and run it with node --test progress.test.mjs in a Node.js environment supporting the built-in test runner. It defines a deliberately limited rule for valid integer counts. A production implementation should document the allowed domain just as clearly.`,`The invalid-case assertion checks that an impossible count is rejected. The other assertion checks an expected result. Add a zero-total test and an exact-completion test yourself. Test names should explain the behavior to someone reading a failure report.`],language:'JavaScript · Node.js',code:`import test from 'node:test';
import assert from 'node:assert/strict';

function progress(done, total) {
  if (!Number.isInteger(done) || !Number.isInteger(total) ||
      done < 0 || total < 0 || done > total) {
    throw new RangeError('Invalid lesson counts');
  }
  return total === 0 ? 0 : Math.round(done / total * 100);
}

test('one of four lessons is 25 percent', () => {
  assert.equal(progress(1, 4), 25);
});
test('completed count cannot exceed total', () => {
  assert.throws(() => progress(5, 4), RangeError);
});`},
{id:'investigate',title:'4. Debug from a repeatable observation',paragraphs:[`When a defect appears, record the smallest sequence that reproduces it. Include the relevant input and environment. “Progress shows 125% after completing an imported course” is more actionable than “the dashboard is wrong.” The first statement points toward a violated count relationship.`,`Form one hypothesis and gather evidence. Inspect the values entering the calculation and compare them with the data source. If the inputs are already inconsistent, changing a rounding rule will not address the real cause. Work backward until you locate the boundary where the requirement stopped being enforced.`]},
{id:'doubles',title:'5. Understand what isolation leaves out',paragraphs:[`Replacing a network call with a test double can make a test fast and predictable. It also means that test does not prove the real network integration works. Use isolation deliberately and add an appropriate integration check when the interaction itself matters.`,`A large number of passing assertions is not a guarantee of useful coverage. Tests that merely confirm implementation details can make refactoring painful without protecting user behavior. Prefer observable results and explicit rules, then add narrower implementation checks only where they address a real risk.`]},
{id:'fix',title:'6. Verify the fix and nearby behavior',paragraphs:[`After fixing the cause, repeat the original reproduction steps. Add a regression test when it meaningfully protects the behavior. Check a nearby valid case to make sure the fix did not solve the failure by rejecting legitimate input.`,`A useful completion note states what failed, what changed, and what evidence now supports the result. It should also name any important limit, such as a test that used simulated network responses. Clear evidence lets a reviewer judge confidence without assuming that every possible environment was tested.`]}],exercise:['Add zero-total and exact-completion tests.','Write a failing case for a fractional completed count.','Explain which integration risks the small function tests do not cover.'],answer:'progress(0,0) returns 0 and progress(4,4) returns 100. A fractional count should throw. These tests do not verify database records, real HTTP responses, or browser rendering; those need checks at the relevant integration boundary.',glossary:[['Regression test','A check intended to catch a previously identified failure.'],['Test double','A controlled replacement for a dependency during a test.'],['Reproduction','A repeatable sequence that demonstrates an issue.']],sources:[{title:'Node.js: Test runner',url:'https://nodejs.org/api/test.html'}]});
guides.push({slug:'react-interface-state',title:'React foundations: build interfaces around data and state',category:'Web foundations',summary:'Break a course catalog into components and keep filtering behavior understandable.',goals:['Separate component responsibilities','Distinguish props from state','Avoid duplicated derived values'],sections:[
{id:'structure',title:'1. Begin with a static interface',paragraphs:[`Imagine a course catalog with a search field and several course cards. Before adding interactions, identify the visible parts and the data each part needs. A catalog contains a toolbar and a list; a card displays one course. This gives the interface a structure that can be understood without following every event handler.`,`Build the static presentation with representative data first. Check long titles, missing optional descriptions, and a narrow viewport. These cases reveal layout problems before interactive state complicates the investigation. A component should have a useful responsibility rather than exist solely because a file became long.`]},
{id:'inputs',title:'2. Use props to communicate inputs',paragraphs:[`Props supply information to a component from its parent. A course card can receive a title and summary without knowing how the catalog loaded them. That separation makes the card easier to reuse and inspect. Keep the direction of information clear so a reader can trace where a displayed value originates.`,`Use stable identifiers for list keys. The identity of a course should not change when the user filters the list or changes its order. A position in an array describes where something appears now, not necessarily which item it is.`]},
{id:'state',title:'3. Store only what changes independently',paragraphs:[`State represents information the component needs to remember between renders. The search query is state because user input changes it. The filtered list can be calculated from the query and course data; storing another copy in state creates a synchronization problem.`,`Ask whether a value can be computed from existing props or state. If it can, calculate it during rendering unless there is a measured reason to choose a different approach. Avoid adding an effect merely to keep two copies of the same information aligned.`]},
{id:'example',title:'4. Connect a controlled input',paragraphs:[`This example belongs inside a React application. It renders a labeled search field and derives the visible courses from its current query. The input's value and change handler make the relationship between user input and component state explicit.`,`Try searching for SQL, then clear the field. Add a query that matches nothing and observe the empty state. A real catalog should also distinguish data that is still loading from a successful result containing no courses.`],language:'React JSX',code:`import { useState } from 'react';
const courses = [
  { id: 'web', title: 'Web foundations' },
  { id: 'sql', title: 'SQL essentials' }
];
export default function Catalog() {
  const [query, setQuery] = useState('');
  const visible = courses.filter(course =>
    course.title.toLowerCase().includes(query.toLowerCase())
  );
  return <section>
    <label htmlFor="course-search">Find a course</label>
    <input id="course-search" value={query}
      onChange={event => setQuery(event.target.value)} />
    <ul>{visible.map(course =>
      <li key={course.id}>{course.title}</li>
    )}</ul>
    {visible.length === 0 && <p>No matching courses.</p>}
  </section>;
}`},
{id:'ownership',title:'5. Give shared state a clear owner',paragraphs:[`When two components need the same selected course, choose a common owner for that information and pass the relevant value and actions downward. Two independent selections can drift apart and produce contradictory interfaces. The simplest appropriate owner is often their nearest shared parent.`,`Do not move every temporary value into global state by default. A draft visible only in one small form can often stay local. Choose ownership based on which parts need coordination, not on a belief that one storage location suits every interaction.`]},
{id:'quality',title:'6. Verify the interface as a person uses it',paragraphs:[`Test keyboard focus, long labels, empty results, and narrow screens. Check that clearing a filter restores the expected content. If a request can fail, preserve the user's choices while showing an actionable message. Framework correctness does not automatically create a useful interaction.`,`As the application grows, keep components focused on meaningful tasks and data flows. Read a feature from input to state to rendered output. If the relationship is hard to explain, simplify ownership and remove redundant state before adding another abstraction.`]}],exercise:['Add a third course with a stable identifier.','Explain why visible is calculated rather than stored separately.','Design a category filter that combines with the text query.'],answer:'Add a record with a unique id. The visible list derives from courses and query, so storing it would duplicate information. A category filter can be another state value; calculate results using both the category condition and text match.',glossary:[['Props','Inputs passed from a parent to a component.'],['State','Information remembered between renders.'],['Derived value','A result calculated from information already available.']],sources:[{title:'React: Thinking in React',url:'https://react.dev/learn/thinking-in-react'},{title:'React: Quick start',url:'https://react.dev/learn'}]});
guides.push({slug:'typescript-data-contracts',title:'TypeScript essentials: describe data without trusting it blindly',category:'Programming',summary:'Model course records, narrow optional values, and understand where compile-time checking ends.',goals:['Describe an object with a type','Use unions to represent alternatives','Validate data received at runtime'],sections:[
{id:'role',title:'1. Know what TypeScript checks',paragraphs:[`TypeScript adds a type-checking layer to JavaScript development. It helps identify mismatches before the program runs, such as passing a number where a title string is expected. The emitted JavaScript does not automatically validate every value arriving from a network, file, or user.`,`This distinction is essential when integrating an API. A declared type is a claim made by your program. An external response must still be checked at the boundary. Using a type assertion to silence an error does not transform an invalid response into the promised data.`]},
{id:'shape',title:'2. Model one record clearly',paragraphs:[`A course record needs a stable id, a title, and a publication status. An optional summary means a caller must consider that the field might be absent. A union can describe a limited set of allowed alternatives more accurately than an unrestricted string.`,`Choose names that reflect the product rather than implementation convenience. If a field means estimated reading minutes, name it accordingly. A numeric type alone cannot tell a teammate whether a value represents seconds, minutes, or a progress percentage.`],language:'TypeScript',code:`type Course = {
  id: string;
  title: string;
  status: 'draft' | 'published';
  summary?: string;
};

function courseLabel(course: Course): string {
  return course.status === 'published'
    ? course.title
    : course.title + ' (draft)';
}`},
{id:'narrow',title:'3. Narrow values before using them',paragraphs:[`A value that might be missing needs a decision before being used as a definite string. A default summary can be appropriate for display, while a required enrollment identifier should probably cause validation to fail. Optionality is a product question as well as a syntax feature.`,`Branching on a value can narrow its possible types. For example, checking whether a value is a string lets subsequent code use string operations in that branch. Prefer this evidence-based narrowing to broad assertions that tell the checker to assume your conclusion.`]},
{id:'boundary',title:'4. Keep unknown data unknown until checked',paragraphs:[`The unknown type requires you to inspect a value before using it as a particular shape. This is useful at external boundaries. The guard below checks a small subset of the course contract and can be extended when additional fields become necessary.`,`A validator should match what downstream code relies on. If a later operation expects a nonempty identifier, checking only typeof value.id is insufficient. Separate basic type shape from additional domain rules and test both deliberately.`],language:'TypeScript',code:`function isCourse(value: unknown): value is Course {
  if (typeof value !== 'object' || value === null) return false;
  const item = value as Record<string, unknown>;
  return typeof item.id === 'string' &&
    typeof item.title === 'string' &&
    (item.status === 'draft' || item.status === 'published') &&
    (item.summary === undefined || typeof item.summary === 'string');
}`},
{id:'errors',title:'5. Read type errors as design feedback',paragraphs:[`A type error sometimes reveals a real disagreement between components. One function may return an optional result while its caller assumes success. Instead of immediately adding an assertion, decide what should happen when the result is absent. A useful type model makes that choice visible.`,`Avoid using any as a universal escape hatch. It can remove the very checks you added TypeScript to obtain. When a library's type is difficult, inspect the relevant API and narrow the uncertainty to a small boundary rather than weakening the whole application.`]},
{id:'routine',title:'6. Pair type checking with runtime tests',paragraphs:[`A program can pass type checking and still calculate the wrong total, enforce the wrong permission, or render an inaccessible interface. Use types to improve consistency, then verify behavior with appropriate tests and real examples. Different checks answer different questions.`,`As a learning routine, model a record, write a function that consumes it, and intentionally supply a mismatched value. Observe the checker. Then pass malformed external data through a validator and observe the runtime outcome. Understanding both paths prevents overconfidence in either one.`]}],exercise:['Add an estimatedMinutes field and explain its unit.','Decide whether an empty title satisfies your product rules.','Explain why an API response asserted as Course can still be invalid.'],answer:'Use a numeric estimatedMinutes field and validate the allowed range at runtime. A string check permits an empty title, so add a separate nonempty rule if required. A type assertion does not inspect or modify received data; only actual runtime validation can establish its shape.',glossary:[['Union','A type representing one of several alternatives.'],['Narrowing','Reducing possible types based on checks or control flow.'],['Type assertion','A developer instruction to the checker, not runtime validation.']],sources:[{title:'TypeScript: Everyday types',url:'https://www.typescriptlang.org/docs/handbook/2/everyday-types.html'}]});
guides.push({slug:'free-domains-and-dns',title:'Free domains and DNS: what "free" really means online',category:'Deployment & free resources',summary:'Understand domains, DNS records, and which free or low-cost naming options are actually safe to depend on.',goals:['Explain what a domain and DNS record actually do','Compare real free naming options without falling for scams','Point a domain at a deployed project using DNS records'],sections:[
{id:'what-is-a-domain',title:'1. A domain is a rented name, not a place',paragraphs:[`A domain name such as example.com is a human-readable label that DNS resolves into the technical details needed to reach a service, most commonly an IP address or another hostname. You never truly "own" a domain outright; you rent it from a registrar for a period, usually one year, and must renew it or lose it. Understanding this rental relationship early avoids a common surprise: a project that suddenly disappears because a renewal was missed.`,`A registrar (Namecheap, Cloudflare Registrar, Google Domains' successor Squarespace, GoDaddy, and others) sells and manages the registration. A separate DNS host stores the actual records that say where traffic should go; many registrars also act as the DNS host by default, which is convenient for a first project. The registrar and the hosting provider for your website are usually different companies, and connecting them is exactly what DNS records are for.`,`Before spending or signing up anywhere, write down what you actually need: a name for a class project, a portfolio, or a long-term brand. A free subdomain is enough for the first two. A brand you plan to keep for years is worth a small yearly cost on a real top-level domain (TLD) such as .com, .dev, or .app.`]},
{id:'real-free-options',title:'2. Real free options in 2026, and the ones to avoid',paragraphs:[`The most reliable "free domain" is actually a free subdomain handed out by a platform you already use to host your project: yourname.vercel.app, yourname.netlify.app, yourname.pages.dev (Cloudflare Pages), and yourname.github.io (GitHub Pages) are issued automatically when you deploy, need no separate signup, and carry free HTTPS. For a student project, portfolio draft, or class demo, this is usually the right choice and the fastest to set up.`,`Community-run free subdomain services also exist for specific niches: is-a.dev (for personal/dev projects, requires a pull request to a public GitHub repo), js.org (JavaScript project sites), and eu.org (general purpose, manual approval). These are legitimate but run by volunteers, come with usage rules you must follow, and are not a service-level guarantee — treat them as a nice-to-have, not infrastructure for something that must never go down.`,`Be skeptical of sites advertising totally free real TLDs (.com, .xyz, .site "for life"). Freenom, which used to give away .tk/.ml/.ga/.cf/.gq domains, was shut down in 2023 after widespread abuse, and many previously "free" domains from that program have since been seized or gone offline — a real lesson in why free-forever domain offers deserve scrutiny. If an offer looks like Freenom's old model, assume it is unreliable or a phishing front, and avoid pointing any real project at it.`]},
{id:'cheap-real-domains',title:'3. Getting a real TLD for cheap or free as a student',paragraphs:[`If you have a school email address, the GitHub Student Developer Pack (education.github.com/pack) is the most legitimate path to a real domain at no cost: it currently includes a free .me domain for one year through Namecheap, plus discounts from other partners. Sign up with your school email, wait for verification, then redeem the domain offer from your GitHub education dashboard.`,`Domain registrars also run first-year promotional pricing on new TLDs like .dev, .app, or .xyz, sometimes under a dollar. Read the renewal price before buying — a $2 first year that renews at $20 is a fine deal for a one-year project but a bad surprise for something you plan to keep. Always check whether WHOIS privacy (hiding your name/address from the public WHOIS lookup) is included free or costs extra; reputable registrars like Cloudflare Registrar include it at no markup.`,`Whichever path you take, keep the registrar account email and payment method up to date, and turn on auto-renew only if you're comfortable being charged automatically — otherwise set a calendar reminder a month before expiry.`]},
{id:'dns-records',title:'4. Point your domain at your site with DNS records',paragraphs:[`Once you have a domain (free subdomain or a real one) and a deployed site, connecting them means adding DNS records at wherever your domain's DNS is managed. The two records you will use almost every time: an A record maps a name directly to an IPv4 address; a CNAME record maps a name to another hostname and lets it inherit that hostname's address. Most static hosts (Vercel, Netlify, GitHub Pages, Cloudflare Pages) tell you exactly which record to add once you type your custom domain into their dashboard.`,`A typical setup for a root domain (example.com) uses an A record pointing at the host's IP addresses, while a subdomain like www.example.com or app.example.com uses a CNAME pointing at something like cname.vercel-dns.com. Some hosts also ask for a TXT record purely to prove you control the domain — it carries no traffic, it just answers "can you edit this domain's DNS?"`,`DNS changes are not instant. Propagation can take anywhere from a few minutes to 24-48 hours as caches around the internet expire and refresh. Use a tool like whatsmydns.net to check whether your new record has reached different regions before assuming a setup is broken.`],language:'Example DNS records',code:`Type   Name   Value                          Purpose
A      @      76.76.21.21                    Root domain -> host IP
CNAME  www    cname.vercel-dns.com            www subdomain -> host
TXT    @      vercel-domain-verify=abc123     Ownership proof (no traffic)`},
{id:'exercise-setup',title:'5. Practice: connect a free subdomain end to end',paragraphs:[`Deploy any static page to GitHub Pages or Vercel using their default free subdomain first — do not buy anything yet. Confirm the site loads over HTTPS at that free address. This isolates deployment problems from domain problems, so if something breaks later you know which half to investigate.`,`Next, if you want practice with real DNS without spending money, request a free subdomain from is-a.dev by following its repository's contribution instructions, and point it at your already-working deployment using the CNAME value your host provided. Wait for propagation and verify with an external DNS checker rather than only your own browser, which may cache the old result.`,`Write down, in your own words, the difference between "my site is broken" and "my DNS hasn't propagated yet" — the troubleshooting steps for each are completely different, and confusing them wastes time.`]},
{id:'pitfalls',title:'6. Common pitfalls that catch beginners',paragraphs:[`Missed renewals are the most common way a working project quietly disappears; some registrars sell an expired domain to someone else within days. Domain-transfer and "expiring soon" emails can also be phishing attempts imitating your registrar — always log in to the registrar's site directly rather than clicking an email link.`,`A domain pointing at the wrong record after switching hosting providers is another frequent issue: if you move from Netlify to Vercel, the old CNAME value must be updated, or visitors will keep hitting the previous (possibly now-unclaimed) host. Finally, remember that a domain having correct DNS does not guarantee your certificate (HTTPS) is valid yet — most modern hosts issue this automatically, but it can lag a few minutes behind the DNS change itself.`]}],exercise:['Explain the difference between a registrar and a DNS host in your own words.','List two legitimate free subdomain options and one red flag that identifies an untrustworthy "free domain" offer.','Write the DNS record type and value you would add to point www.example.com at cname.vercel-dns.com.'],answer:'A registrar sells and manages the registration; a DNS host stores the records saying where traffic should go — often the same company, but not always. Legitimate free options include platform subdomains (vercel.app, github.io) and community services like is-a.dev; a red flag is any offer promising a real TLD "free forever" resembling the discontinued Freenom model. The record is CNAME, name www, value cname.vercel-dns.com.',glossary:[['Registrar','A company that sells and manages domain name registrations.'],['DNS record','An entry telling DNS how to resolve a name (A, CNAME, TXT, etc).'],['Propagation','The delay before a DNS change is visible everywhere.'],['TLD','Top-level domain — the suffix such as .com, .dev, or .app.']],sources:[{title:'MDN: What is a domain name?',url:'https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/What_is_a_domain_name'},{title:'GitHub Education: Student Developer Pack',url:'https://education.github.com/pack'},{title:'is-a.dev: free subdomains for developers',url:'https://www.is-a.dev/'}]});
guides.push({slug:'free-website-hosting',title:'Free website hosting: choosing where your project actually lives',category:'Deployment & free resources',summary:'Compare real free hosting platforms for static sites, frontend apps, and small backends, and know their limits.',goals:['Match a project type to an appropriate free host','Understand the real limits behind "free tier"','Avoid the surprises that break a free-tier project in production'],sections:[
{id:'why-it-matters',title:'1. "Hosting" means different things for different projects',paragraphs:[`A plain HTML/CSS/JS page, a React or Next.js frontend, and a backend API with a database all have different hosting needs, and a single "best free host" does not exist independent of that. Static hosting serves files as-is with no server-side code running per request. A frontend framework often needs a build step before it becomes static files. A backend needs a long-running or on-demand process plus somewhere to keep data.`,`Before comparing providers, classify your project: does it have a build step? Does it need a database? Does it need to run custom server code (not just serve files)? These three questions eliminate most wrong choices quickly, before you spend time configuring a platform that was never a fit.`]},
{id:'static-hosts',title:'2. Free hosts for static sites and frontend frameworks',paragraphs:[`GitHub Pages hosts static files directly from a repository, is completely free with no bandwidth billing surprises for reasonable personal use, and is a natural fit once you're already using Git. Cloudflare Pages and Netlify both offer generous free tiers with automatic builds from a connected GitHub repo, free HTTPS, and a global CDN; Netlify's free tier includes 100GB bandwidth and 300 build minutes per month, Cloudflare Pages is more generous on bandwidth (effectively unmetered for typical use) but caps builds per month too.`,`Vercel is the most common home for Next.js projects specifically (it's built by the same company), with a free "Hobby" tier that covers personal, non-commercial projects — read its terms before using it for anything that becomes a paid product. Firebase Hosting (Google) is another solid free static option, particularly if you're already using other Firebase services like Firestore or Authentication in the same project.`]},
{id:'dynamic-hosts',title:'3. Free hosts for small backends and databases',paragraphs:[`Backend hosting free tiers are stingier because a server that runs continuously costs the provider real money even when idle. Render's free web service tier spins your service down after a period of inactivity and takes 30-60 seconds to "wake up" on the next request — fine for a demo, frustrating for something you want to feel instant. Railway and Fly.io offer small usage-based free allowances rather than an unlimited free tier; read current limits before relying on them, since these change more often than static-host limits.`,`For a database, Supabase and Neon both offer a genuinely useful free PostgreSQL tier (with pausing after inactivity on the free plan), MongoDB Atlas has a small free shared cluster, and Firebase Firestore's free tier is usable for a class project's data needs. Pick the database that matches the backend framework you're already comfortable with rather than chasing whichever has the biggest free quota this month.`]},
{id:'matching',title:'4. A quick decision guide',paragraphs:[`Plain HTML/CSS/JS, no build step, no server code: GitHub Pages or Cloudflare Pages. React/Vue/Svelte with a build step, no backend: Netlify, Cloudflare Pages, or Vercel. Next.js specifically: Vercel gets first-class support, though Netlify and Cloudflare also support it. Need a custom backend (Express, Django, Flask): Render or Railway for the server, paired with Supabase/Neon/MongoDB Atlas for the database.`,`When in doubt, pick whichever option has documentation matching your exact framework version — the time saved not fighting a mismatched build configuration usually outweighs a marginal difference in free-tier limits.`]},
{id:'limits',title:'5. Read the free-tier fine print before you depend on it',paragraphs:[`"Free" always comes with limits: bandwidth caps, build-minute caps, a maximum number of projects, or an inactivity sleep timer that makes a backend feel broken to a first-time visitor. None of this is hidden — it is published on each provider's pricing page — but it is easy to skip reading until a class demo fails because a database paused itself after a week of no traffic.`,`Free tiers also change terms over time as companies adjust their business model; a limit that was generous a year ago may be tighter now. Before submitting a project that depends on a free host staying available during a grading window, check the current published limits rather than trusting older tutorials or this guide's specific numbers, which will drift.`]},
{id:'exercise-choose',title:'6. Practice: choose a host for three scenarios',paragraphs:[`Scenario A: a static portfolio page with no backend, meant to stay up indefinitely. Scenario B: a Next.js app with a contact form that emails you (needs a small serverless function, no database). Scenario C: a group project with user accounts, posts, and comments stored in a database.`,`Write your choice and one sentence of reasoning for each before checking the answer below. The goal is recognizing which single question (build step? server code? database?) drove each decision, not memorizing a fixed provider list that will eventually be outdated.`]}],exercise:['Classify your own current or planned project by the three questions in section 1.','Choose a host for scenarios A, B, and C in section 6 and justify each in one sentence.','Name one real limit (not hypothetical) of the free tier you chose for scenario C\'s database.'],answer:'Scenario A fits GitHub Pages or Cloudflare Pages — pure static, no build dependency on server code. Scenario B fits Vercel or Netlify, since both support serverless functions alongside a Next.js/static build. Scenario C needs a backend host (Render/Railway) plus a managed free-tier database (Supabase/Neon/MongoDB Atlas) — a common real limit is the database pausing after a period of inactivity on the free plan.',glossary:[['Static hosting','Serving pre-built files with no per-request server code.'],['Build step','A process that compiles/bundles source files into deployable static output.'],['Cold start','The delay when a paused or sleeping free-tier service wakes up for a new request.'],['CDN','Content delivery network — servers spread globally that cache and serve your files closer to visitors.']],sources:[{title:'GitHub Pages documentation',url:'https://docs.github.com/en/pages'},{title:'Cloudflare Pages documentation',url:'https://developers.cloudflare.com/pages/'},{title:'Netlify pricing and limits',url:'https://www.netlify.com/pricing/'},{title:'Vercel Hobby plan documentation',url:'https://vercel.com/docs/plans/hobby'}]});
guides.push({slug:'deploy-your-first-website',title:'How to deploy a website: from a local folder to a live URL',category:'Deployment & free resources',summary:'Walk through pushing a project to GitHub and deploying it live, including environment variables and a custom domain.',goals:['Explain what "deploying" actually changes','Deploy a project from GitHub to a host with automatic redeploys','Diagnose a failed deploy from its build log'],sections:[
{id:'what-is-deploy',title:'1. Deploying means making your build reachable, on purpose',paragraphs:[`Running a project on your own laptop proves it works in one specific environment: your operating system, your installed tools, your local files. Deploying means producing a build from your source code and making that exact build reachable at a public URL, on infrastructure you don't have to keep your own computer running for. "It works on my machine" is exactly the gap deployment is meant to close.`,`Modern static and frontend hosts use Git-based deployment: you connect a GitHub (or GitLab/Bitbucket) repository to the host, and every push to a chosen branch triggers a new build and release automatically. This means your deployment history is your commit history — a useful property when something breaks and you need to know exactly which change caused it.`]},
{id:'first-deploy',title:'2. A first deploy, step by step',paragraphs:[`Push your project to a GitHub repository if it isn't already there. On the hosting platform (Vercel, Netlify, and Cloudflare Pages all follow this same basic flow), sign in with GitHub, choose "Import project" or "New site", and select your repository. The platform inspects your project (often auto-detecting a framework like Next.js, Vite, or plain static files) and proposes a build command and output directory — confirm or correct these before deploying.`,`Click deploy. The platform clones your repository, installs dependencies, runs the build command, and if it succeeds, publishes the output directory to its CDN and gives you a live URL immediately, usually on the platform's free subdomain (yourproject.vercel.app, for example). From this point forward, every push to your connected branch automatically triggers a new deploy — you generally never need to manually re-upload files again.`],language:'Typical build settings',code:`Framework preset:   Next.js (auto-detected)
Build command:      npm run build
Output directory:   .next   (or "dist" / "build" for many other frameworks)
Install command:    npm install`},
{id:'env-vars',title:'3. Environment variables and secrets during deploy',paragraphs:[`A project often needs values that differ between your machine and production: an API key, a database connection string, a feature flag. These are set as environment variables in the hosting platform's dashboard, not committed into your repository — a committed .env file with a real API key is a leaked secret the moment it's pushed, even if you delete it in a later commit, since it remains in Git history.`,`Most frameworks distinguish between server-only variables and ones exposed to the browser; in Next.js, for instance, only variables prefixed NEXT_PUBLIC_ are bundled into client-side JavaScript, while unprefixed ones stay server-only. Get this distinction right before adding a secret — a prefixed "public" variable is visible to anyone who opens your site's JavaScript, so real secrets (database passwords, private API keys) must never carry that prefix.`,`After adding or changing an environment variable in the dashboard, most platforms require a fresh deploy for it to take effect — the currently-live build was already compiled without it.`]},
{id:'custom-domain-deploy',title:'4. Adding a custom domain and HTTPS',paragraphs:[`Once your project is live on the platform's free subdomain, adding your own domain (see the free-domains-and-dns module for how to get one) is usually a matter of typing it into the host's "Domains" settings and adding the DNS record it shows you at your registrar. The platform then automatically issues a free TLS certificate (commonly via Let's Encrypt) once it verifies you control the domain — you do not need to buy or manually configure a certificate yourself on any of these modern hosts.`,`Give DNS a little time to propagate before assuming the domain setup failed; the platform's dashboard will usually show a clear "pending" versus "active" status for the domain so you're not guessing.`]},
{id:'debug-deploy',title:'5. Reading a failed build log',paragraphs:[`A failed deploy almost always tells you why, in the build log the platform shows you — resist the urge to guess and instead read the last error near the bottom of the log first. Common causes: a dependency listed in your local node_modules but missing from package.json (works locally, fails in a clean build environment); a missing environment variable the build itself needs; a case-sensitivity mismatch in an import path (your Windows or Mac filesystem is case-insensitive, but the Linux build server is not, so import from './Button' when the file is button.tsx can fail only in deployment).`,`Reproduce the failure locally when possible: delete node_modules, run a clean install, and run the exact build command the platform uses. If it fails the same way locally, you can iterate much faster than waiting on remote deploys for every attempt.`]},
{id:'exercise-deploy',title:'6. Practice: deploy something today',paragraphs:[`Take any small project (even a single static HTML page) and push it to a new GitHub repository. Connect it to Vercel, Netlify, or Cloudflare Pages, and get it live on the free subdomain. Make one visible content change, push it, and confirm the change appears automatically without any manual redeploy step. Then intentionally introduce one build-breaking typo, push it, and read the resulting failed build log before fixing it — recognizing what a real failure looks like is more useful than only ever seeing successful deploys.`]}],exercise:['Explain why a committed .env file with a secret is still a leak even after you delete it in a later commit.','Describe the difference between a public and a server-only environment variable in a framework of your choice.','List two likely causes of "works locally, fails in the build" and how you would confirm each.'],answer:'Git preserves history, so the secret remains recoverable from an earlier commit even after deletion — the credential should be revoked and rotated, not just removed. A public variable (e.g. NEXT_PUBLIC_ prefixed) ships into browser JavaScript and is visible to anyone; a server-only one stays on the server. Likely causes include a dependency missing from package.json and a case-sensitive import path mismatch — confirm by deleting node_modules and running a clean install and build locally.',glossary:[['Build command','The command that compiles source files into a deployable output.'],['Environment variable','A configuration value supplied at runtime, kept out of source code.'],['TLS certificate','The credential that enables HTTPS for a domain.'],['CI/CD','Continuous integration/deployment — automatically building and releasing on each push.']],sources:[{title:'Vercel: Deploying a project',url:'https://vercel.com/docs/deployments/overview'},{title:'Netlify: Get started with deploys',url:'https://docs.netlify.com/site-deploys/overview/'},{title:'Next.js: Environment variables',url:'https://nextjs.org/docs/app/building-your-application/configuring/environment-variables'}]});
guides.push({slug:'free-ui-and-design-resources',title:'Free UI kits, icons, and widgets: stop building every pixel from scratch',category:'Deployment & free resources',summary:'Find and responsibly use free component libraries, icons, illustrations, and embeddable widgets for a project.',goals:['Choose a component library that fits a project\'s stack','Find free icons and illustrations with clear licenses','Add a third-party widget without silently harming privacy or performance'],sections:[
{id:'why-reuse',title:'1. Reusing good components is a skill, not cheating',paragraphs:[`A beginner project's roughest edges are usually visual: inconsistent spacing, mismatched buttons, no real icon set. Building every one of those from a blank canvas is a legitimate exercise once, for learning — but for an actual project, reaching for a maintained, accessible, free component library gets you a more polished and more accessible result faster, which is exactly why professional teams do the same thing.`,`The skill worth building is choosing and adapting a library, not memorizing one forever. Read a component's props and how to customize it before dropping it in — copying without understanding leaves you unable to fix it later.`]},
{id:'component-libraries',title:'2. Free component libraries by stack',paragraphs:[`For React projects (like this one), shadcn/ui is a widely used approach: instead of installing a package, you copy accessible, Tailwind-styled component source directly into your project, so you fully own and can edit the code — no version lock-in, no bundle bloat from unused components. Radix UI and Base UI provide the unstyled, accessible primitives many of these copy-in libraries are built on.`,`Tailwind CSS itself ships a large set of free open-source community components (via resources like Tailwind UI's free samples and the wider community). DaisyUI is a free Tailwind plugin that adds ready-made component classes (buttons, cards, modals) if you want less custom styling work. For non-React or simpler projects, Bootstrap remains a free, thoroughly documented option with broad browser support and a huge base of examples.`]},
{id:'icons-illustrations',title:'3. Icons, illustrations, and fonts',paragraphs:[`Lucide (used in many modern React/shadcn projects) and Heroicons are free, MIT-licensed icon sets with consistent stroke weight and sizing — good defaults unless you have a strong reason otherwise. Font Awesome's free tier covers a huge range of common icons, though its full library requires a paid plan; check which icons are marked "free" before depending on one that isn't.`,`unDraw provides free, customizable-color SVG illustrations under a license that permits commercial use without attribution (verify current terms on the site, since illustration licenses can be more restrictive than icon licenses). Google Fonts remains the simplest source of free, open-license web fonts with a straightforward embed snippet and no attribution requirement for most fonts.`]},
{id:'widgets',title:'4. Embeddable widgets: convenience with a privacy cost',paragraphs:[`A live-chat widget (Tawk.to has a genuinely free tier), a comment system (Giscus, which stores comments as GitHub Discussions and is free and open-source, is a lighter-weight alternative to Disqus), a contact form (EmailJS free tier sends a limited number of emails per month directly from client-side JavaScript, no backend required), and an embedded map (Google Maps' embed API works without a key for basic embeds; the full JavaScript API needs a key and has a free monthly usage quota) cover most of what a small project needs.`,`Every third-party widget is also third-party JavaScript running on your page with its own network requests, cookies, and sometimes tracking behavior — Disqus in particular has drawn long-standing privacy criticism for the trackers it loads. Before adding one, check what data it collects and whether that's appropriate for your users, especially if the site is aimed at students or minors; prefer lighter, privacy-respecting alternatives (like Giscus over Disqus) when the functionality is equivalent.`]},
{id:'licensing',title:'5. Licenses and attribution actually matter',paragraphs:[`"Free" is not one license — MIT and Apache 2.0 (common for component libraries and icon sets) allow commercial use, modification, and redistribution with minimal conditions. Creative Commons licenses on illustrations or fonts vary widely: some require attribution, some forbid commercial use, some forbid modification. Read the specific license attached to the specific asset you're using rather than assuming every "free" resource behaves the same way.`,`Keep a simple running list (even a CREDITS.md file) of which external assets and libraries your project uses and under what license, especially once a project grows past a solo class exercise — untangling attribution requirements after the fact, once you can't remember where an image came from, is far more painful than noting it at the time.`]},
{id:'exercise-widget',title:'6. Practice: add one library and one widget',paragraphs:[`Pick a small existing project and replace one hand-built UI element (a button, a card, a modal) with an equivalent from a free component library, reading its documentation for customization options rather than only copying the first example verbatim. Then add exactly one embeddable widget (a contact form or a comment system) and write down, in one sentence, what data it collects about your visitors — check its own privacy documentation to answer this rather than guessing.`]}],exercise:['Name one MIT-licensed icon set and one illustration resource, and state a difference in what their licenses typically require.','Explain why copying a component without reading its documentation is a weaker approach than adapting it deliberately.','Describe one privacy trade-off of adding a third-party comment widget, and one lighter-weight alternative.'],answer:'Lucide (MIT, generally no attribution required) versus unDraw (a distinct license permitting commercial use but worth verifying current terms) illustrates that "free" licenses differ in their requirements. Copying without reading documentation means you cannot customize or debug the component later and may miss accessibility props it expects you to set. Disqus loads third-party trackers; Giscus (GitHub Discussions-based) is a lighter, more privacy-respecting alternative for comments.',glossary:[['MIT license','A permissive open-source license allowing reuse, modification, and commercial use with attribution kept in the source.'],['Creative Commons','A family of licenses for creative works with varying restrictions (attribution, commercial use, modification).'],['Widget','A small embeddable third-party feature (chat, comments, forms, maps) added to a page via a script or embed code.']],sources:[{title:'shadcn/ui documentation',url:'https://ui.shadcn.com/docs'},{title:'Lucide icons',url:'https://lucide.dev/'},{title:'unDraw open-source illustrations',url:'https://undraw.co/'},{title:'Google Fonts',url:'https://fonts.google.com/'}]});
guides.push({slug:'free-apis-for-projects',title:'Free and public APIs: fuel your project with real data',category:'Deployment & free resources',summary:'Find trustworthy free/public APIs, read their limits and auth requirements, and use API keys without leaking them.',goals:['Find a free public API that fits a project idea','Read API documentation for rate limits, auth, and terms of use','Call an API safely without exposing a private key in the browser'],sections:[
{id:'why-apis',title:'1. Real data makes a practice project feel real',paragraphs:[`A to-do list with three hardcoded items teaches you the basics, but a project that displays real weather, real books, or real space launch schedules is far more motivating and closer to what production software actually does: talk to other systems over a network. Public and free-tier APIs let you build that experience without needing your own backend or dataset.`,`Before searching for an API, write the exact question your project needs answered: "current weather for a city name," "search results for a book title," "a random programming joke." A precise question makes it much faster to judge whether a given API's documentation actually covers your use case, instead of skimming several and guessing.`]},
{id:'finding-apis',title:'2. Where to find trustworthy free APIs',paragraphs:[`public-apis (a large, actively maintained community-curated GitHub list at github.com/public-apis/public-apis) categorizes hundreds of free and freemium APIs by topic — weather, books, games, finance, and more — and notes which require a key and which support CORS for direct browser calls. RapidAPI's marketplace aggregates many third-party APIs (many with a free tier) behind one account and one key format, which is convenient but means trusting RapidAPI as a middle layer.`,`Some reliable, genuinely free starting points by category: OpenWeatherMap (weather, free tier with a key), Open Library and Google Books API (books, no key needed for basic Open Library lookups), PokeAPI (Pokémon data, fully free and keyless), JSONPlaceholder (fake REST data for practicing CRUD calls, no key), and the Star Wars API (SWAPI, keyless). Government open-data portals (data.gov, and most countries have an equivalent) are also free and often keyless for public datasets.`]},
{id:'reading-docs',title:'3. Read the documentation for these four things',paragraphs:[`Before writing any code, check an API's docs for: whether it requires an API key or account signup; its rate limit (calls allowed per minute/day on the free tier); whether it supports CORS (needed if you're calling it directly from browser JavaScript rather than through your own backend); and its terms of use (some free APIs forbid commercial use, require attribution, or forbid caching/redistributing the data).`,`A rate limit that seems generous for manual testing can be exceeded quickly by a bug — for example, an API call accidentally placed inside a render loop or a retry with no backoff. Check what the API returns when you exceed the limit (usually an HTTP 429 status) and handle that case deliberately rather than only handling success.`]},
{id:'safe-keys',title:'4. Using an API key without leaking it',paragraphs:[`Many free-tier APIs require a key mainly to enforce their rate limit per user, not because the data itself is sensitive — but the handling rule is the same either way: a key placed directly in client-side JavaScript is visible to anyone who opens the browser's developer tools, no matter how it's obfuscated. For a key you'd rather not expose (or one attached to a paid quota you don't want abused), call the API from a small server-side function and have your frontend call that function instead.`,`In a Next.js project like this one, an API route or server action can hold the real key as a server-only environment variable and proxy the request, returning only the data your frontend needs. For genuinely public, rate-limited-only keys on a low-stakes hobby project, exposing the key directly can be an acceptable trade-off — but make that choice deliberately, and never do it for a key tied to billing.`],language:'Next.js server-side proxy (route.ts)',code:`// app/api/weather/route.ts — key stays on the server
export async function GET(request: Request) {
  const city = new URL(request.url).searchParams.get('city');
  const key = process.env.OPENWEATHER_API_KEY; // server-only, no NEXT_PUBLIC_ prefix
  const res = await fetch(
    \`https://api.openweathermap.org/data/2.5/weather?q=\${city}&appid=\${key}\`
  );
  if (!res.ok) return Response.json({ error: 'Weather lookup failed' }, { status: 502 });
  const data = await res.json();
  return Response.json({ description: data.weather?.[0]?.description ?? 'unknown' });
}`},
{id:'handling-failure',title:'5. Handle a slow or failing API gracefully',paragraphs:[`A free public API can be slower or less reliable than a paid production service — some are maintained by volunteers with no uptime guarantee. Always design for the request failing: show a clear loading state, a clear error message distinct from "no results," and consider a short client-side cache or fallback for data that doesn't need to be second-by-second fresh.`,`Test this deliberately: temporarily point your fetch at a nonexistent path or an invalid key and confirm your interface shows a sensible message rather than a blank screen or an unhandled console error. This is the same discipline covered in this site's APIs and JSON module — a free API doesn't remove the need to validate what comes back.`]},
{id:'exercise-api',title:'6. Practice: wire up one free API',paragraphs:[`Pick one question from a project idea, find a matching API from the sources above, and read its docs for the four things in section 3 before writing any code. Make one successful call and display the result. Then deliberately trigger a failure (wrong parameter, exceeded rate limit, or no network) and confirm your interface handles it without crashing. If the API requires a key you'd rather not expose, add a minimal server-side proxy route following the pattern in section 4.`]}],exercise:['Find one free API relevant to a project you want to build and note whether it requires a key, its rate limit, and whether it supports CORS.','Explain why a paid or rate-limited API key should not be placed directly in client-side JavaScript.','Describe what your interface should show when an API call returns an HTTP 429 status.'],answer:'Answers vary by chosen API, but should name a specific rate limit and key requirement from the actual documentation. A client-side key is visible to any visitor via developer tools, so anyone could copy and reuse it against your quota or, for paid tiers, your bill. On a 429 status, the interface should show a clear "too many requests, try again shortly" message rather than treating it as a generic or empty-result failure.',glossary:[['Rate limit','The maximum number of API calls allowed in a given time window.'],['CORS','A browser security mechanism controlling whether a page can call an API from a different origin directly.'],['API key','A token identifying a caller to an API, often used for rate limiting or billing.'],['Proxy route','A server-side endpoint you control that forwards a request to a third-party API, hiding a private key.']],sources:[{title:'public-apis: a collective list of free APIs',url:'https://github.com/public-apis/public-apis'},{title:'MDN: Using Fetch',url:'https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch'},{title:'OpenWeatherMap API documentation',url:'https://openweathermap.org/api'}]});

guides.push({slug:'free-custom-ui-widgets',title:'Custom UI & widgets: build interactive buttons, cards, and loaders',category:'Deployment & free resources',summary:'Learn how to create high-craft interactive UI widgets, shimmer effects, frosted obsidian glass, and micro-animations with pure CSS and React.',goals:['Build reusable interactive widgets without heavy UI bundle weight','Implement glassmorphism, glowing borders, and shimmer animations with pure CSS','Structure accessible interactive widget states (hover, active, focus-visible)'],sections:[
{id:'modern-widget-anatomy',title:'1. What makes modern UI widgets feel premium',paragraphs:[`Look closely at top-tier developer platforms like Linear, Raycast, and Vercel: their interfaces do not feel premium because of heavy 3D frameworks or complex canvas animations. They feel premium because of disciplined craft: high-contrast dark backdrops, subtle 1px borders with localized radial glows, purposeful micro-animations, and instant feedback.`,`When building custom widgets for your own projects, prioritize lightweight CSS variables over bloated UI dependencies. A single button or card with subtle box-shadows, backdrop-filter, and smooth cubic-bezier transitions will load instantly on mobile, look state-of-the-art, and remain easy to maintain and customize.`]},
{id:'glassmorphism-and-borders',title:'2. Glassmorphism and glowing border recipes',paragraphs:[`Glassmorphism requires three CSS properties working together: a semi-transparent dark background (e.g. rgba(18, 20, 26, 0.85)), a backdrop blur (backdrop-filter: blur(12px)), and a subtle border with an accent color at 20-30% opacity (such as rgba(199, 248, 108, 0.25)). Without the border, the card looks muddy; without the blur, text behind the card creates visual noise.`,`To create glowing borders that react to hover, combine an outer box-shadow with a gentle radial gradient background. On hover, increase the opacity and spread slightly, and add a subtle translateY(-2px) to give the component physical weight and lift.`]},
{id:'pulse-and-shimmer',title:'3. Animated status pulses and shimmer buttons',paragraphs:[`Live status pills (showing API uptime or database connection) are one of the most popular widgets in developer tools. A pulsing dot is created with two layered elements: a solid inner dot and an outer ping circle that scales outward from 1 to 2.4 while fading opacity to 0 using an infinite CSS animation.`,`For shimmer buttons, an animated gradient or pseudo-element creates a sweeping ray of light across the button. Because CSS animations run on the GPU composite layer (transform and opacity), they do not trigger expensive browser reflows and remain buttery-smooth even on low-end devices.`]},
{id:'copy-paste-workflow',title:'4. Organizing widgets in your codebase',paragraphs:[`The best approach for side projects and portfolios is the copy-paste component model popularized by shadcn/ui: keep your widget files directly in your components/ directory rather than installing an un-editable npm package. This gives you 100% control to adjust colors, spacing, and accessibility attributes as your project evolves.`,`Always provide accessible labels and focus-visible rings for keyboard users. A widget that looks stunning but cannot be tabbed to with a keyboard is fundamentally broken.`]},
{id:'practice-widget',title:'5. Practice: build your own custom widget',paragraphs:[`Pick one widget from this site's Free Arsenal hub: customize its colors to match your personal brand, add an icon from Lucide, and verify that it renders correctly in dark mode. Test both keyboard navigation (Tab and Enter) and responsive scaling on small screens.`]}],exercise:['Name the three CSS properties required to achieve a clean glassmorphic effect.','Why are transform and opacity preferred over animating width or margin in micro-animations?','What is the advantage of keeping widget source code directly in your project versus using an opaque npm UI library?'],answer:'Glassmorphism requires a semi-transparent background, backdrop-filter blur, and a subtle border. Transform and opacity animate on the GPU composite layer without causing browser layout reflows, ensuring 60fps smoothness. Owning the source directly allows immediate customization, avoids version conflicts, and keeps bundle sizes minimal.',glossary:[['Glassmorphism','A UI design style featuring frosted-glass translucency, background blur, and crisp borders.'],['Composite layer','GPU-accelerated rendering phase for transform and opacity changes.'],['Focus-visible','CSS pseudo-class applying focus styles only when keyboard navigation is detected.']],sources:[{title:'MDN: backdrop-filter',url:'https://developer.mozilla.org/en-US/docs/Web/CSS/backdrop-filter'},{title:'shadcn/ui philosophy',url:'https://ui.shadcn.com/docs'},{title:'CSS-Tricks: The complete guide to CSS gradients',url:'https://css-tricks.com/a-complete-guide-to-css-gradients/'}]});

guides.push({slug:'next-app-router-rendering',title:'Next.js routing and rendering: choose SSR, SSG, or ISR on purpose',category:'Advanced web & frontend',summary:'Read the App Router file conventions, separate server and client components, and pick a rendering strategy for a course catalog page instead of accepting whatever a template happened to use.',goals:['Read App Router file conventions with confidence','Separate server components from client components deliberately','Choose SSG, SSR, or ISR for a given page and justify it'],sections:[
{id:'conventions',title:'1. Learn the file conventions before the framework magic',paragraphs:[`The App Router in Next.js assigns meaning to specific file names inside a folder that represents a URL segment. A page.tsx file inside app/courses makes /courses a route. A layout.tsx file wraps that route and any nested routes with shared structure such as a header or sidebar, and it persists across navigations within its segment instead of remounting. A loading.tsx file supplies a fallback while the segment is being prepared, and an error.tsx file catches rendering errors for that segment specifically.`,`This is different from a single-page application where one router configuration file lists every path. Here, the folder structure on disk is the routing table. A route group such as app/(marketing)/about lets you organize files into folders without adding /(marketing) to the actual URL, which is useful for separating a public marketing section from an authenticated dashboard section that otherwise share little layout.`,`Before changing rendering behavior, read the existing folder tree of a project and name what each file does. A course catalog page usually lives at app/courses/page.tsx, with app/courses/[slug]/page.tsx handling one course detail page through a dynamic segment. Confusing a layout for a page, or forgetting that loading.tsx only fires on navigation into that segment, causes more debugging time than the rendering strategy itself.`]},
{id:'server-client',title:'2. Decide what runs on the server and what runs in the browser',paragraphs:[`Every component in the App Router is a server component by default. It renders on the server, can read from a database or file system directly, and never ships its own JavaScript to the browser. This matters for a course catalog: the component that fetches the list of courses and maps them into cards can do that fetch directly, with no client-side loading spinner needed for the initial view.`,`A component needs the 'use client' directive at the top of its file only when it needs browser-only behavior: state, effects, event handlers, or browser APIs. A search box that filters courses as the user types needs onChange and useState, so it must be a client component. The common mistake is marking an entire page 'use client' because one small interactive piece lives inside it, which drags the whole subtree into the browser bundle and gives up the server-rendering advantage for everything else.`,`The better pattern keeps the page itself as a server component that fetches data, and passes that data down as props into a small client component that only owns the interactive part. For the catalog, CourseList stays a server component; SearchBox and a client-side filtered view become their own small client component that receives the full course array as a prop. This keeps the JavaScript sent to the browser proportional to what actually needs to run there.`],language:'TypeScript',code:`// app/courses/page.tsx (server component, default)
export default async function CoursesPage() {
  const courses = await getCourses(); // runs on the server
  return <CourseBrowser courses={courses} />;
}

// app/courses/course-browser.tsx
'use client';
import { useState } from 'react';
export default function CourseBrowser({ courses }: { courses: Course[] }) {
  const [query, setQuery] = useState('');
  const visible = courses.filter(c => c.title.toLowerCase().includes(query.toLowerCase()));
  return (
    <div>
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search courses" />
      <ul>{visible.map(c => <li key={c.id}>{c.title}</li>)}</ul>
    </div>
  );
}`},
{id:'static',title:'3. Choose static generation when content is the same for everyone',paragraphs:[`Static site generation renders a page to HTML at build time, once, and serves that same HTML to every visitor until the next deploy. It is the right choice when the content does not depend on who is asking: a course catalog page that lists published courses looks identical whether a visitor is signed in or not, so there is no reason to regenerate it on every request. Static pages are also the cheapest to serve, since a CDN can hand out the same file without running any server code per visit.`,`In the App Router, a page becomes static by default when it does not read request-specific data such as cookies, headers, or search params, and when any fetch calls inside it are cacheable. A course catalog fetched from a database at build time and rendered into app/courses/page.tsx will be static automatically unless something in the component opts out of caching. This is a subtle but important point: static generation in the App Router is a consequence of what a page does, not a separate mode you must remember to turn on.`,`The tradeoff is staleness. If an instructor publishes a new course, a purely static catalog page will not show it until the next build and deploy. For a catalog that changes rarely, rebuilding on every content update through a webhook is reasonable. For a catalog that changes daily, a purely static approach means someone has to remember to trigger a rebuild, which is exactly the kind of manual step that gets forgotten.`]},
{id:'server-render',title:'4. Choose server-side rendering when the response depends on the request',paragraphs:[`Server-side rendering computes HTML for every single request instead of once at build time. It is necessary when the page content genuinely differs per visitor: a dashboard showing a specific instructor their own draft courses, or a catalog page that must reflect a signed-in student's enrollment status inline with each course card. If the answer to "would this look the same for two different visitors right now" is no, SSR (or something request-aware) is required, not optional.`,`In the App Router, a page opts into per-request rendering by reading things that are only known at request time, such as cookies() or headers(), or by fetching data with cache set to no-store. Reading a session cookie to show "Enrolled" next to a course the student already joined forces that page to render per request, because the framework cannot safely reuse one HTML output for every visitor once it depends on that cookie.`,`SSR costs more than static generation because a server has to do real work on every visit: read the cookie, query enrollment status, and render before responding. For the course catalog, a common and much cheaper alternative is to keep the catalog itself static, and load enrollment status client-side after the page has already painted, so only the personalized sliver of the page pays the per-request cost.`]},
{id:'isr',title:'5. Choose incremental static regeneration for the middle ground',paragraphs:[`Incremental static regeneration serves a static page like SSG, but lets that cached page expire and be regenerated in the background after a set number of seconds, without forcing a full rebuild and redeploy. It fits content that changes, but not so often that every visitor needs the absolute latest version: a course catalog updated by instructors a few times a day is a textbook case. A visitor gets a fast, cached response; the framework regenerates the page behind the scenes once it goes stale, and the next visitor gets the fresh version.`,`In the App Router, this is configured with a revalidate value, either as an exported constant on the page or as an option on a specific fetch call. Setting export const revalidate = 300 on app/courses/page.tsx tells Next.js this page can be served from cache for up to five minutes before the next request triggers a regeneration. The first visitor after that window still gets the previously cached page instantly; the regeneration happens without blocking them.`,`ISR is not free of tradeoffs either. A newly published course can still be invisible for up to the revalidate window, and debugging "why does the catalog show stale data" becomes a question of checking the revalidate value rather than assuming the database itself is wrong. For genuinely time-sensitive changes, such as removing a course because of an urgent legal issue, pair a short revalidate window with an on-demand revalidation call triggered from the action that made the change, rather than waiting out the timer.`],language:'TypeScript',code:`// app/courses/page.tsx
export const revalidate = 300; // regenerate at most every 5 minutes

export default async function CoursesPage() {
  const courses = await fetch('https://api.example.com/courses', {
    next: { revalidate: 300 }
  }).then(r => r.json());
  return <CourseList courses={courses} />;
}`},
{id:'decide',title:'6. Walk through the decision for one real page',paragraphs:[`Return to the course catalog and make the decision explicit instead of picking a strategy out of habit. Ask three questions in order: does the content differ per visitor right now, how often does the underlying data change, and how costly is staleness if it happens. A public catalog listing published courses answers "no" to the first question, which already rules out SSR for the catalog itself.`,`If the catalog changes rarely, such as once per semester, static generation with a rebuild triggered by the content system is the simplest and cheapest answer. If it changes throughout the day as instructors publish or unpublish courses, ISR with a revalidate window matched to how urgently a change needs to appear, perhaps 60 to 300 seconds, gives freshness without paying the per-request cost of full SSR. Only the small, genuinely personalized pieces, like "you are enrolled in this one," should force per-request rendering, and even then only for that piece rather than the whole page.`,`Write this reasoning down for any page you build, not just this example. A team that can say "this page is ISR with a five-minute window because instructors publish a few times a day, and staleness beyond five minutes is acceptable" has a decision that can be revisited when requirements change. A team that cannot explain why a page renders the way it does will tend to reach for SSR everywhere out of caution, quietly making every page slower and more expensive than it needs to be.`]}
],exercise:['List which of the three questions (per-visitor difference, change frequency, staleness cost) rule out static generation for a live leaderboard page.','Rewrite the course catalog page to use a 60-second revalidate window and explain what changes for a visitor.','Identify one piece of the catalog page that should stay a client component and explain why the rest should not follow it into the browser bundle.'],answer:'A live leaderboard differs by nothing per visitor but changes constantly, so it fails the change-frequency question and needs a short revalidate window or SSR rather than plain SSG. Lowering revalidate to 60 means a stale page can be served for up to a minute before the next request triggers a background regeneration. The search box that filters courses client-side is the piece that must be a client component; the data-fetching page around it should stay a server component so only that small piece ships interactive JavaScript.',glossary:[['Server component','A component that renders on the server and ships no JavaScript for its own logic to the browser.'],['Client component','A component marked with the use client directive that can use state, effects, and browser APIs.'],['Revalidate','The interval after which a cached page or fetch result is eligible to be regenerated.'],['Static generation','Rendering a page once at build time and reusing that output for every visitor.']],sources:[{title:'Next.js: Rendering fundamentals',url:'https://nextjs.org/docs/app/building-your-application/rendering'},{title:'Next.js: Server and Client Components',url:'https://nextjs.org/docs/app/building-your-application/rendering/composition-patterns'}]});
guides.push({slug:'state-management-patterns',title:'State management patterns: when Context is enough and when it is not',category:'Advanced web & frontend',summary:'Classify state by scope and lifetime, notice when Context re-renders become a real problem, and decide when a dedicated store or server-state library actually earns its complexity.',goals:['Classify a given piece of state by scope and lifetime','Recognize when Context re-renders become a performance problem','Choose between local state, Context, a store, and a server-state library'],sections:[
{id:'classify',title:'1. Classify state before choosing a tool',paragraphs:[`Every piece of state in an interface has a scope, meaning how many components need to read it, and a lifetime, meaning how long it should exist. A search query typed into one filter box is local: only that box and its immediate list need it, and it can disappear the moment the component unmounts. Confusing local state for something that needs wider scope is how a small filter box ends up wired into a global store for no reason.`,`Lifted state is local state moved up to a shared ancestor because two sibling components need to coordinate through it, such as a course list and a preview panel that both need to know which course is currently selected. Shared state is state that many unrelated parts of the application need, such as the signed-in user or the current theme. Server-cached state is different from all three: it is a local copy of data that actually lives on a server, such as the list of courses themselves, and its correctness depends on staying in sync with that server, not just with other components.`,`Naming which of these four categories a piece of state falls into is not academic. Local and lifted state are almost always fine as plain useState and prop passing. Shared state is where Context starts to look attractive. Server-cached state is where Context and plain stores both tend to struggle, because they were not built to handle staleness, refetching, or background updates.`]},
{id:'context-purpose',title:'2. Understand what Context actually solves',paragraphs:[`Context exists to avoid prop drilling: passing a value through five layers of components that do not use it themselves, just to hand it to a deeply nested consumer. A theme value or the current signed-in user are classic Context candidates, because nearly every part of the tree might need to read them, but no single layer in between has any business owning that value.`,`Context is a distribution mechanism, not a state management system. It does not compute derived values, does not batch complex updates, and does not know anything about caching. It simply lets a Provider higher in the tree make a value available to any descendant that calls useContext, without every component in between needing to accept and forward a prop.`,`For a course platform, a natural Context is an AuthContext holding the signed-in user and a signOut function. It is read in a header component, a settings page, and a protected-route wrapper, none of which are directly related to each other in the component tree. That is the shape Context was designed for: a small number of values, read widely, changing relatively rarely.`],language:'TypeScript',code:`const AuthContext = createContext<{ user: User | null; signOut: () => void } | null>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const signOut = () => setUser(null);
  return <AuthContext.Provider value={{ user, signOut }}>{children}</AuthContext.Provider>;
}`},
{id:'rerender-problem',title:'3. Notice when Context re-renders become a real problem',paragraphs:[`Every component that calls useContext for a given Context re-renders whenever the value passed to that Provider changes, regardless of which specific field inside that value the component actually reads. If a single AppContext bundles the current user, the current theme, and a rapidly changing notification count into one object, updating the notification count re-renders every consumer of AppContext, including the ones that only cared about the theme.`,`This becomes visible in a course platform when a live "3 new comments" counter is stored in the same Context as the signed-in user. Every keystroke in a comment box that increments that counter re-renders the header, the sidebar, and any other component reading AppContext, even though most of those components render nothing different. In a small app this is invisible; in a larger tree with expensive child renders, it shows up as visible jank tied directly to how fast the counter updates.`,`The fix is not always to abandon Context. Splitting one large Context into several smaller ones, so the notification count lives in its own Provider separate from the user, contains the re-render to only the components that actually read the count. Memoizing the value passed to a Provider with useMemo also prevents an unrelated re-render of the parent from creating a new object reference and cascading through every consumer even when nothing meaningful changed.`]},
{id:'server-state',title:'4. Recognize server-cached state as its own category',paragraphs:[`The list of courses in a catalog is not really client state in the way a search query is. It lives on a server, can change from other clients or a background process, and the browser only ever holds a copy that can go stale. Modeling it with useState and a manual useEffect fetch means reimplementing loading states, error states, retries, caching, and refetch-on-focus by hand, for every piece of server data in the app.`,`This is the specific gap that libraries such as TanStack Query or SWR fill. They treat a query as identified by a key, such as ['courses'], cache the result, deduplicate simultaneous requests for the same key, and can automatically refetch when the window regains focus or when a mutation elsewhere invalidates that key. None of this is about component-to-component communication, which is what Context and stores are for; it is about keeping a client-side copy of server truth reasonably fresh.`,`A useful rule of thumb: if a piece of state's real answer lives in a database and could be changed by someone else, treat it as server state and reach for a query library rather than modeling it with useState and Context. If it only ever exists in the browser and nothing external can change it behind the interface's back, such as whether a dropdown is open, plain component state remains the simplest correct choice.`]},
{id:'store',title:'5. Reach for a dedicated store only when Context genuinely strains',paragraphs:[`A dedicated client state store, such as Zustand or Redux, solves problems Context does not: selective subscriptions where a component only re-renders when the specific slice it reads changes, middleware for logging or persistence, and patterns for complex update logic that would be awkward spread across nested Providers. These are real advantages, but they come with more concepts to learn and more indirection between an action and the state it changes.`,`The signal that a project has outgrown Context is usually concrete, not aesthetic: multiple unrelated Context re-render problems that splitting Providers has not fixed, state logic that has grown branchy enough that useReducer inside a single component is no longer enough, or many components across distant parts of the tree needing fine-grained, independent slices of shared client state. A course platform with a single shared cart or a complex multi-step course-builder wizard with dozens of interdependent fields are believable candidates.`,`Reaching for a store before any of that pressure exists usually just adds a second thing to learn without solving a problem the team actually has. Context plus a couple of well-scoped Providers plus a query library for server data covers a large share of real applications; a dedicated store is worth its cost when a specific, named pain point shows up, not by default at project setup.`]},
{id:'decide',title:'6. Match the four patterns to one interface',paragraphs:[`Take a course platform end to end. The signed-in user is shared state with a small, slow-changing shape, so AuthContext fits well. The list of published courses is server-cached state, so a query library handles its fetching, caching, and refetching rather than useState and a manual effect. Whether a particular course card is expanded is local state, owned entirely by that card.`,`A shopping cart shared between a course list and a checkout summary is lifted or shared state depending on how many distant components need it; if only two nearby siblings need it, lift it to their common parent instead of reaching for Context at all. If a live notification badge updates on every keystroke elsewhere in a Context that also holds the user, split it into its own Context so an unrelated re-render does not ripple through the header.`,`The discipline that keeps all of this manageable is asking, for every new piece of state, who needs it and where does its true value live, before picking a tool. A team that defaults to "put it in Context" or "put it in Redux" for everything will eventually hit exactly the re-render or staleness problems this guide describes, and will have to retrofit the classification they skipped at the start.`]}
],exercise:['Classify the following as local, lifted, shared, or server-cached: a collapsed/expanded flag on one FAQ item, the current course catalog data, and a signed-in user available app-wide.','Explain why bundling a fast-changing notification count into the same Context as the signed-in user causes unrelated components to re-render.','Decide whether a course platform needs a dedicated store just because it uses Context for auth, and justify the answer.'],answer:'The FAQ flag is local state; the course catalog is server-cached state best handled by a query library; the signed-in user is shared state, a reasonable fit for Context. Bundling the notification count with the user means every consumer of that Context re-renders on every count update, since Context re-renders all consumers on any change to the Provider value regardless of which field they read. Using Context for auth alone does not require a store; a store is worth adding only when a specific, named re-render or complexity problem appears that splitting Context and adding a query library has not solved.',glossary:[['Prop drilling','Passing a value through intermediate components that do not use it, just to reach a descendant that does.'],['Server-cached state','A client-side copy of data whose true source of truth lives on a server and can change independently.'],['Selective subscription','A pattern where a component only re-renders when the specific slice of state it reads changes.'],['Context Provider','The component that supplies a value to every descendant calling useContext for that Context.']],sources:[{title:'React: Passing Data Deeply with Context',url:'https://react.dev/learn/passing-data-deeply-with-context'},{title:'TanStack Query: Overview',url:'https://tanstack.com/query/latest/docs/framework/react/overview'}]});
guides.push({slug:'web-performance-core-vitals',title:'Web performance: measure and improve Core Web Vitals',category:'Advanced web & frontend',summary:'Treat LCP, CLS, and INP as concrete measurements with findable causes, then fix a course page using DevTools evidence instead of vague speed intuition.',goals:['Explain what LCP, CLS, and INP each actually measure','Find the specific cause of a poor score in DevTools','Apply targeted fixes instead of generic speed advice'],sections:[
{id:'metrics',title:'1. Replace "make it faster" with three specific measurements',paragraphs:[`"The site feels slow" is not a diagnosis, because it does not say which moment felt slow or why. Core Web Vitals break that vague feeling into three specific, measurable moments. Largest Contentful Paint (LCP) measures how long it takes the largest visible element, often a hero image or heading, to render. Cumulative Layout Shift (CLS) measures how much visible content unexpectedly moves after it has already rendered. Interaction to Next Paint (INP) measures how long the page takes to visually respond after a user clicks, taps, or types.`,`Each metric has a defined good threshold: LCP under 2.5 seconds, CLS under 0.1, and INP under 200 milliseconds, all measured at the 75th percentile of real visits. These thresholds matter because they turn "is this page fast enough" from an opinion into a comparison against a number you can actually track over time and across deploys.`,`A course detail page makes the distinction concrete. If the course title and hero image take four seconds to appear, that is an LCP problem. If the page jumps down half a screen once an ad or late-loading enrollment banner appears, that is a CLS problem. If clicking "Enroll" leaves the button looking unresponsive for a second before anything visibly changes, that is an INP problem. Three different symptoms, three different fixes; treating them as one undifferentiated "slowness" wastes effort on the wrong one.`]},
{id:'lcp',title:'2. Find and fix a slow Largest Contentful Paint',paragraphs:[`In Chrome DevTools, the Performance panel and the Lighthouse panel both identify the LCP element directly, showing which element was measured and a breakdown of the time before it rendered: time to first byte, resource load delay, resource load time, and render delay. For a course page where the hero image is the LCP element, this breakdown tells you whether the problem is a slow server response, a late-discovered image request, a large image file, or a slow render step, which are four different problems with four different fixes.`,`A common cause is an image the browser cannot discover until late, because it is set as a CSS background-image or is injected by client-side JavaScript after the initial HTML loads. Using a plain img tag with the real image in the initial HTML lets the browser discover and start fetching it immediately during document parsing. Adding fetchpriority="high" to that image tells the browser to prioritize it over other resources competing for bandwidth, and preloading fonts used in the LCP text avoids an invisible-text delay while a webfont downloads.`,`The actual size of the image file matters as much as when it is requested. Serving a hero image at its rendered display size, in a modern format such as WebP or AVIF, through next/image or an equivalent, typically cuts the transferred bytes far more than any priority hint can compensate for. Diagnose before fixing: check the DevTools breakdown to see whether the slow phase is server response time, discovery delay, or transfer size, and apply the fix that addresses that specific phase rather than every fix at once.`],language:'HTML',code:`<!-- Before: hidden from the preload scanner, no size hint -->
<div style="background-image:url(/hero.jpg)"></div>

<!-- After: discoverable immediately, prioritized, sized to avoid CLS -->
<img src="/hero.webp" width="1200" height="600"
     fetchpriority="high" alt="Featured course illustration">`},
{id:'cls',title:'3. Find and fix unexpected layout shift',paragraphs:[`Chrome DevTools' Performance panel records individual layout shift entries with a score and, when you expand one, highlights the exact elements that moved. This turns "the page jumps around" into a specific list of elements and the moments they shifted, which is the only way to fix the actual cause rather than guessing at the whole page.`,`Images and embeds without explicit width and height attributes are a frequent cause: the browser cannot reserve space for them before the file finishes downloading, so surrounding content reflows once it arrives. Setting explicit width and height (or an aspect-ratio in CSS) lets the browser reserve the correct box immediately, even before the image loads, so nothing needs to move once it does.`,`Web fonts cause a related but distinct shift called flash of invisible or unstyled text, where the page first renders with a fallback font at a different size than the eventual webfont, shifting text and everything below it once the real font swaps in. Using font-display: swap or optional along with size-adjust tuned to match the fallback font's metrics reduces how much text reflows at the swap. Content injected above existing elements, such as a cookie banner or a late-arriving promotional strip, is the other common source; reserving its space in advance, or inserting it below the fold instead of pushing existing content down, avoids the shift entirely.`]},
{id:'inp',title:'4. Find and fix a sluggish Interaction to Next Paint',paragraphs:[`INP is measured from the moment of a user interaction (a click, tap, or key press) to the next time the browser paints a visual update in response. A poor INP almost always traces back to the main thread being busy with a long task at the moment the user interacted, which delays the browser from getting to painting the response at all, even if the eventual work is simple.`,`The Performance panel's flame chart shows long tasks as wide bars on the main thread track; clicking one reveals what function was running. On a course page, clicking "Enroll" that feels sluggish often traces to a large synchronous computation, such as re-filtering or re-sorting an entire course list, running on the main thread inside the same click handler that should have just shown a loading state.`,`The fix is to shrink or move that work rather than accept it as unavoidable. Breaking a long synchronous task into smaller chunks, deferring non-essential work with setTimeout or scheduler.postTask so the browser can paint in between, and moving pure computation off the main thread with a Web Worker are all valid options depending on the task. For interactions gated by third-party or analytics scripts loaded eagerly, deferring those scripts so they load after the page is interactive keeps the main thread free for the user-visible response instead of competing with it.`],language:'JavaScript',code:`// Before: filtering large data synchronously inside the click handler
button.addEventListener('click', () => {
  const results = allCourses.filter(matchesFilters); // long task, blocks paint
  renderList(results);
});

// After: let the browser paint a pending state first, then do the work
button.addEventListener('click', () => {
  showLoadingState();
  setTimeout(() => {
    const results = allCourses.filter(matchesFilters);
    renderList(results);
  }, 0);
});`},
{id:'field-vs-lab',title:'5. Separate lab measurements from real field data',paragraphs:[`Lighthouse and a local Performance panel recording are lab data: a single run, on one machine, under conditions you control, which is excellent for reproducing and debugging one specific issue. Field data, gathered from the Chrome User Experience Report or a real-user monitoring script running in production, reflects what actual visitors experienced across a mix of devices, networks, and locations, which is what Core Web Vitals scoring is actually based on.`,`A page can look fine in a lab run on a fast development laptop while failing its field LCP threshold for real visitors on slower phones or congested networks. Treat a lab score as a hypothesis about a specific fix, and confirm the fix actually helped by watching the field data change after it ships, rather than declaring victory the moment a local Lighthouse run improves.`,`Field tools also reveal which specific pages and segments are underperforming, which lab testing on one page cannot show. If the course catalog scores well but individual course detail pages score poorly, that difference only becomes visible by comparing field data across the two page types, and it points the LCP or CLS investigation at the actual page that needs it.`]},
{id:'routine',title:'6. Build a small, repeatable performance routine',paragraphs:[`Treat Core Web Vitals as a budget rather than a one-time cleanup. Pick thresholds for LCP, CLS, and INP that match the "good" ranges, check them for key pages before merging a change that touches images, fonts, or heavy client-side logic, and track field data over time so a regression is caught within days rather than discovered months later as a vague complaint.`,`When a metric regresses, follow the same order every time: identify which of the three metrics moved, find the specific element or long task responsible using DevTools, and apply the fix that matches that specific cause. Skipping straight to a generic fix, such as adding image compression everywhere when the real problem was a layout shift from an unsized ad slot, wastes effort and can leave the actual regression untouched.`,`This discipline turns performance work from an occasional emergency into routine engineering. A course platform that tracks its LCP, CLS, and INP the same way it tracks error rates will notice a slow image creep into a page long before a user complains, and will have the DevTools evidence ready to fix the actual cause instead of starting the investigation from zero.`]}
],exercise:['A course page hero image loads late because it is set via CSS background-image. Identify which metric this affects and describe the fix.','A cookie banner appears two seconds after page load and pushes the course list down. Name the metric this causes and one way to prevent it.','Explain why a good Lighthouse score on your laptop does not guarantee a good field CLS or INP score for real users.'],answer:'A late-discovered background image mainly hurts LCP; replacing it with a real img tag in the initial HTML, sized correctly and given fetchpriority="high", lets the browser discover and prioritize it earlier. The late cookie banner causes a CLS shift; reserving its space in advance or avoiding late insertion above existing content prevents the layout jump. Lighthouse is a single lab run on one machine and network condition, while field CLS and INP scores aggregate real visits across many devices and networks, so a fast laptop run can hide problems that show up for slower real-world users.',glossary:[['LCP','Largest Contentful Paint: the time until the largest visible element renders.'],['CLS','Cumulative Layout Shift: a score for how much visible content moves unexpectedly after rendering.'],['INP','Interaction to Next Paint: the time from a user interaction to the next visual update in response.'],['Long task','A block of main-thread JavaScript execution long enough to delay rendering or input response.']],sources:[{title:'web.dev: Core Web Vitals',url:'https://web.dev/articles/vitals'},{title:'web.dev: Optimize INP',url:'https://web.dev/articles/optimize-inp'}]});
guides.push({slug:'accessible-interfaces',title:'Accessible interfaces: build for keyboard, screen reader, and contrast from day one',category:'Advanced web & frontend',summary:'Prefer semantic HTML over ARIA patches, keep focus order and visible focus states intact, label every form control, and verify a course enrollment flow with a keyboard and a screen reader instead of eyeballing it.',goals:['Choose semantic HTML before reaching for ARIA','Keep a visible, logical focus order through an interface','Test an interface with a keyboard and a screen reader, not just by looking at it'],sections:[
{id:'semantics-vs-aria',title:'1. Reach for semantic HTML before ARIA',paragraphs:[`A native button element already announces itself as a button to assistive technology, receives keyboard focus, and responds to both Enter and Space without any extra code. A div with an onClick handler styled to look like a button has none of that built in; it needs role="button", tabindex="0", and manually written keydown handling to reach the same baseline, and it is easy to miss one of those and ship something that looks right but is not operable.`,`ARIA attributes exist to describe behavior the native element vocabulary cannot express on its own, not to patch over the choice of the wrong element. The first rule of ARIA use, stated directly in the ARIA Authoring Practices, is: if a native HTML element or attribute has the semantics and behavior you need, use it instead of repurposing an element and adding ARIA. A course enrollment "Enroll" action should be a real button element; a link to a course detail page should be a real anchor with an href, not a div with a click handler, because a real anchor supports opening in a new tab and shows a URL on hover, which a fake link silently breaks.`,`ARIA is genuinely necessary for patterns HTML has no native equivalent for, such as a custom combobox for filtering courses or a tab panel switching between "Overview" and "Syllabus." In those cases, follow an established pattern such as the ones in the ARIA Authoring Practices Guide rather than inventing role and state attributes from scratch, since a slightly wrong combination of roles and states can be worse than no ARIA at all, actively misleading a screen reader user about what is on screen.`]},
{id:'focus-order',title:'2. Keep focus order logical and always visible',paragraphs:[`Tab order should follow the same order a sighted user would naturally read the page in, which for most layouts is the order elements appear in the HTML source. Using CSS to visually reposition an element, for example moving a "Continue" button above a set of course options with flexbox order or absolute positioning, can leave the tab order still matching the original source order, so a keyboard user tabs through the page in an order that no longer matches what they see on screen.`,`Avoid positive tabindex values such as tabindex="2" to manually force an order; they create a separate ordering pass that runs before all tabindex="0" and naturally focusable elements, and one forgotten value on a later page can produce a confusing, hard-to-predict sequence. If an element genuinely needs to be reachable but is not naturally focusable, tabindex="0" adds it into the natural document-order sequence rather than pulling it out of it.`,`Never remove the focus outline with a blanket outline: none rule and stop there; doing so removes the only visual signal a sighted keyboard user has for where they currently are on the page. If the default outline does not fit the visual design, replace it with a custom but clearly visible focus style using the :focus-visible pseudo-class, which shows the custom outline for keyboard focus while not showing it for a mouse click, matching how most users actually expect focus indication to behave.`],language:'CSS',code:`/* Do not do this: removes the indicator entirely */
button:focus { outline: none; }

/* Do this: replace it with an equally visible custom style,
   shown for keyboard focus without appearing on mouse clicks */
button:focus-visible {
  outline: 3px solid #1a56db;
  outline-offset: 2px;
}`},
{id:'labeling',title:'3. Give every form control a real, connected label',paragraphs:[`A label element connected to its input through a matching for and id attribute, or by wrapping the input inside the label, gives the control an accessible name that a screen reader announces when the field receives focus. Placeholder text is not a substitute for a label: it disappears the moment the user starts typing, often fails contrast requirements because it is styled to look muted, and many screen readers either do not announce it at all or announce it differently from a real label.`,`For a course enrollment form asking for an email address and a promo code, each input needs its own label element, and the label's text should describe the field in a way that makes sense read on its own, since that is exactly how a screen reader user will hear it: "Email address," not "Enter your details below" attached vaguely to an entire section. Grouping related controls, such as a set of radio buttons for choosing a payment plan, inside a fieldset with a legend gives that whole group an announced heading, which a series of individually labeled radios without a fieldset does not provide.`,`Validation messages need the same deliberate connection. An error shown only as red text near a field, with no programmatic link to that field, is invisible to a screen reader user unless they happen to read every element on the page. Associating the error text with the input through aria-describedby, and setting aria-invalid="true" on the input while the error is present, makes the screen reader announce the problem at the moment the user reaches that field, not silently rely on color that a sighted user notices but others cannot.`]},
{id:'contrast',title:'4. Do not rely on color alone, and check contrast for real',paragraphs:[`Color contrast between text and its background needs to meet a measurable ratio, not just look readable to one person on one monitor. WCAG 2.1 AA requires a contrast ratio of at least 4.5:1 for normal text and 3:1 for large text (roughly 18-point or 14-point bold and above) against its background, and this is a ratio you can and should check with a tool rather than judge by eye, since perceived contrast varies with screen brightness and individual vision.`,`A course status shown only as a colored dot, green for "available" and red for "full," fails for anyone with color vision deficiency and for anyone using a grayscale or high-contrast display mode. Pairing the color with a text label or icon, "Available" or "Full" spelled out next to the dot, communicates the same status through a channel that does not depend on distinguishing red from green.`,`Chrome DevTools' color picker shows the contrast ratio for a selected text and background pair directly, along with whether it passes AA and AAA thresholds, when you inspect an element and open its color swatch. Running this check on the actual rendered colors, including any overlay or gradient behind text, catches cases where a design that looks fine in a static mockup fails once real content and real backgrounds are in place.`]},
{id:'keyboard-test',title:'5. Test the whole flow using only a keyboard',paragraphs:[`Unplug the mouse, or simply stop touching it, and complete the entire course enrollment flow using only Tab, Shift+Tab, Enter, Space, and arrow keys where relevant. Every interactive element needs to be reachable in a sensible order, every button needs to activate with Enter or Space, and at no point should focus become invisible or seem to disappear, such as inside a modal that traps focus incorrectly or a dropdown that closes without returning focus anywhere.`,`Pay particular attention to custom components: a modal dialog opened by clicking "Enroll" should move focus into itself when it opens, trap Tab and Shift+Tab within its own contents while open so focus cannot silently escape to page content hidden behind it, and return focus to the element that opened it once it closes. A dropdown or combobox should be operable with arrow keys to move between options and Enter to select one, matching the behavior a mouse user gets by clicking.`,`This test alone catches a large share of accessibility problems, because keyboard operability is close to a prerequisite for most assistive technology to work at all; a screen reader user navigating by keyboard hits the exact same broken focus trap a sighted keyboard-only user does. Running it regularly, on new components before they ship rather than as an occasional audit, catches regressions while they are still a small, easy fix.`]},
{id:'screen-reader-test',title:'6. Test with an actual screen reader, not just visual inspection',paragraphs:[`Turn on a real screen reader, such as NVDA on Windows (free) or VoiceOver on macOS (built in, enabled with Cmd+F5), and navigate the same enrollment flow by listening rather than looking. This surfaces problems invisible to visual inspection: an image with no alt text announced only as "image," a button whose accessible name is just "click here" because it wraps an icon with no label, or a custom dropdown that visually looks fine but is announced as a plain, unlabeled group of text.`,`Listen specifically for whether each control's announced name matches its visible purpose. An icon-only "Enroll" button using an SVG with no accompanying text needs an aria-label, such as aria-label="Enroll in this course," or it will be announced only as "button," giving no indication of what it does. Compare what you hear against what a sighted user sees; any gap between the two is something a sighted-only review would never catch.`,`Do not treat one screen reader test as sufficient proof of correctness, since different screen reader and browser combinations sometimes behave differently for the same markup, but treat it as a meaningfully different and necessary check from keyboard-only testing and visual review. Combined, semantic HTML as the foundation, a logical and visible focus order, real labels, checked contrast, a keyboard-only pass, and a screen reader pass form a routine that catches most real accessibility problems before a user ever has to report one.`]}
],exercise:['Rewrite a clickable div styled as a button into the correct native element, and explain what keyboard behavior you get for free.','Explain why placeholder text is not an adequate substitute for a label element on an email input.','Describe what a keyboard-only test of a modal dialog should check for focus, and what should happen when the modal closes.'],answer:'A div with an onClick handler should become a real button element, which gains keyboard focusability and both Enter and Space activation without any extra ARIA or keydown code. Placeholder text disappears once typing starts, often fails contrast requirements, and is not reliably announced the same way a connected label element is, so it cannot replace a real label. A keyboard-only test of a modal should confirm that opening it moves focus inside, that Tab and Shift+Tab stay trapped within its contents while it is open, and that closing it returns focus to the element that originally opened it.',glossary:[['ARIA','A set of attributes that describe roles, states, and properties for assistive technology when native HTML semantics are not enough.'],['Focus order','The sequence in which interactive elements receive keyboard focus when pressing Tab.'],['Accessible name','The text a screen reader announces for a control, derived from its label, aria-label, or visible text.'],['Focus trap','A pattern that keeps keyboard focus contained within an open dialog until it is closed.']],sources:[{title:'MDN: ARIA basics',url:'https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA'},{title:'W3C: ARIA Authoring Practices Guide',url:'https://www.w3.org/WAI/ARIA/apg/'}]});
guides.push({slug:'frontend-testing-strategy',title:'Frontend testing: unit, integration, and end-to-end done deliberately',category:'Advanced web & frontend',summary:'Apply the testing pyramid to a real frontend app, decide what belongs in a unit test versus a Testing-Library integration test versus a Playwright end-to-end test, and keep the resulting suite fast and non-flaky.',goals:['Apply the testing pyramid shape to a frontend codebase','Choose the right test level for a given piece of behavior','Keep a growing test suite fast and free of flaky failures'],sections:[
{id:'pyramid',title:'1. Understand what shape a healthy frontend suite has',paragraphs:[`The testing pyramid describes a healthy ratio, not a rigid rule: many fast, narrow unit tests at the base, a smaller number of integration tests checking components working together in the middle, and a small number of slow, broad end-to-end tests at the top that exercise a real browser against a running application. The shape exists because each level trades speed and isolation for realism: a unit test runs in milliseconds and pinpoints exactly what broke, while an end-to-end test takes seconds and can fail for reasons entirely unrelated to the behavior it was meant to check, such as a flaky network condition.`,`A course platform with an inverted pyramid, mostly end-to-end tests and few unit tests, tends to have a slow, unreliable suite where a single broken CSS selector or a five-second timeout failure blocks the whole team, and where finding which of forty steps in a long end-to-end test actually failed takes real investigation. The pyramid shape keeps most failures fast, specific, and cheap to diagnose, reserving the expensive broad tests for the handful of flows that genuinely need real-browser confidence.`,`This does not mean end-to-end tests are lesser or unimportant; a passing suite of unit tests proves individual pieces work in isolation but says nothing about whether they are wired together correctly in the real application, which only an integration or end-to-end test can confirm. The pyramid is a guide for allocating a limited testing budget across the levels that each answer a different question, not a ranking of which level matters most.`]},
{id:'unit',title:'2. Decide what belongs in a unit test',paragraphs:[`A unit test isolates one function or one small piece of logic and checks its behavior against specific inputs, without rendering a component tree or touching the network. A function that calculates a course discount price given a base price, a percentage, and a minimum floor is a strong unit test candidate: it takes plain inputs, returns a plain output, and its correctness does not depend on anything about how it is displayed.`,`Unit tests are the right place for edge cases and boundary conditions precisely because they are cheap to write and fast to run: a negative discount, a discount larger than one hundred percent, a price of zero, and a floor that would produce a negative final price are all worth a dedicated assertion each. Writing five unit tests for five boundary conditions of a pricing function costs a fraction of a second combined to run; writing five end-to-end tests to cover the same boundaries would cost minutes and depend on far more of the application working correctly than the pricing logic alone.`,`A common mistake is writing a unit test that just re-executes the same formula the implementation uses, which passes trivially and catches nothing when the formula itself is wrong. A useful unit test encodes the actual requirement independently, such as asserting discountedPrice(100, 20, 10) equals 80 because a known example was worked out by hand, rather than asserting that the function returns whatever the function happens to compute.`],language:'JavaScript',code:`function discountedPrice(base, percentOff, minimumPrice) {
  const discounted = base * (1 - percentOff / 100);
  return Math.max(discounted, minimumPrice);
}

test('20 percent off a 100 course is 80', () => {
  expect(discountedPrice(100, 20, 10)).toBe(80);
});
test('never returns less than the minimum price', () => {
  expect(discountedPrice(100, 95, 10)).toBe(10);
});`},
{id:'integration',title:'3. Decide what belongs in a Testing-Library integration test',paragraphs:[`Testing Library renders real components into a simulated DOM and lets a test interact with them the way a user would, by finding elements through their visible text or accessible role and firing real events, rather than reaching into component internals or state. This is the right level for checking that a component and its immediate children cooperate correctly: that typing into a search box actually filters the rendered course list, or that clicking "Enroll" shows a confirmation message and disables the button while the request is pending.`,`The guiding principle behind Testing Library, stated directly in its own documentation, is that tests should resemble how users actually use software: querying by role and label text rather than by CSS class or component internals means a test keeps passing through a visual redesign that does not change behavior, and correctly starts failing if an accessible label disappears, which is itself a meaningful regression worth catching.`,`Mock the network layer at this level rather than hitting a real backend: a test that renders CourseBrowser with a mocked fetch response for the course list checks the component's actual rendering and filtering logic without depending on a real server being up, keeping the test both fast and deterministic. What this level does not verify is whether the real backend, real routing, and real deployed build actually work together, which is exactly the gap end-to-end tests are meant to fill.`],language:'TypeScript',code:`test('typing a query filters the visible courses', async () => {
  render(<CourseBrowser courses={[{ id: 'a', title: 'SQL basics' }, { id: 'b', title: 'CSS layout' }]} />);
  await userEvent.type(screen.getByLabelText(/find a course/i), 'sql');
  expect(screen.getByText('SQL basics')).toBeInTheDocument();
  expect(screen.queryByText('CSS layout')).not.toBeInTheDocument();
});`},
{id:'e2e',title:'4. Decide what belongs in a Playwright end-to-end test',paragraphs:[`Playwright drives a real browser against a running instance of the actual application, following real navigation, real network requests, and real rendering, which is the only level that can catch a whole class of bugs the levels below cannot: a broken production build, a misconfigured redirect, a real backend contract mismatch, or a third-party script that breaks the page. This realism is exactly why end-to-end tests belong at the narrow top of the pyramid rather than the base: each one is meaningfully slower and has more moving parts that can fail for reasons unrelated to the feature under test.`,`Reserve this level for complete, business-critical user journeys rather than exhaustive coverage of every branch: signing up, browsing the catalog, enrolling in a course, and completing payment is a strong candidate for one true end-to-end test, because it is the flow that, if broken, stops revenue and would otherwise only be caught by a user complaint. Testing every possible discount edge case end-to-end, when the discount calculation already has thorough unit test coverage, adds test time without adding real confidence.`,`Because Playwright tests exercise a running application, they need a genuinely running environment, whether a local dev server, a staging deployment, or a containerized build, and should generally run against realistic seeded data rather than depending on whatever happens to already be in a shared database. Running them in continuous integration on every change, but keeping their count deliberately small, is what keeps their cost proportional to the confidence they provide.`],language:'TypeScript',code:`test('a student can enroll in a course end to end', async ({ page }) => {
  await page.goto('/courses/sql-essentials');
  await page.getByRole('button', { name: 'Enroll' }).click();
  await expect(page.getByText('You are enrolled')).toBeVisible();
});`},
{id:'speed',title:'5. Keep the suite fast as it grows',paragraphs:[`Speed is a design constraint on a test suite, not an afterthought to fix later, because a suite that takes twenty minutes to run gets skipped locally and only checked after a slow CI run, which defeats much of the point of having fast feedback in the first place. Running unit and integration tests in parallel across multiple worker processes, which most modern test runners support out of the box, is usually the single largest speed gain available without changing a single test.`,`Mocking the network at the unit and integration level, rather than letting every test hit a real (even local) backend, removes a large source of both slowness and unpredictability; a component test that mocks fetch runs in milliseconds regardless of the real backend's speed. At the end-to-end level, reusing an authenticated browser session across tests that all need a signed-in user, instead of repeating a full login flow through the UI in every single test, can meaningfully cut the total time of an end-to-end suite.`,`Periodically auditing the suite for tests that no longer earn their runtime, such as an end-to-end test covering a scenario that a faster integration test now covers just as well, keeps the pyramid shape intact as a codebase grows. Suites tend to drift toward more end-to-end tests over time simply because they feel more reassuring to write; deliberately pushing new coverage down to the fastest level that can actually verify it counteracts that drift.`]},
{id:'flaky',title:'6. Eliminate flakiness instead of tolerating it',paragraphs:[`A flaky test is one that fails intermittently without a real change in the code under test, and it is more damaging than an outright missing test, because a team that has learned to re-run a failing test and expect it to pass will eventually re-run a genuine failure the same way and ship a real regression. The most common cause in frontend tests is a race condition: asserting on something before an asynchronous update, such as a fetch response or a state update, has actually completed.`,`Testing Library's async utilities, such as findByText or waitFor, exist specifically to wait for an expected change to appear rather than asserting immediately after a user action and hoping the update has already happened. Playwright's built-in auto-waiting for elements to become visible and actionable removes a similar class of race conditions at the end-to-end level, but arbitrary fixed waits such as page.waitForTimeout(2000) reintroduce flakiness by either waiting too long, wasting time, or too little, still racing the real condition.`,`Shared, mutable test data is another common source: two end-to-end tests that both enroll the same seeded student in the same seeded course can interfere with each other depending on run order, producing failures that vanish when a test is run alone. Giving each test its own isolated data, whether through a fresh database transaction, a uniquely named fixture, or a reset between runs, removes an entire category of failures that have nothing to do with the behavior actually being tested.`]}
],exercise:['Decide which test level (unit, integration, or end-to-end) is the right place to check a discount-calculation boundary case, and justify it.','Identify the likely cause of a Testing-Library test that sometimes fails asserting text appears immediately after a button click.','Explain why re-running a flaky failing test until it passes is worse than having no test for that behavior at all.'],answer:'A discount-calculation boundary case belongs in a unit test, since it is pure logic with plain inputs and outputs that does not require rendering or a browser to verify, and a unit test checks it in milliseconds. A test asserting immediately after a click likely has a race condition against an asynchronous update; using an async query such as findByText or wrapping the assertion in waitFor lets the test wait for the real update instead of racing it. Re-running a flaky test until it passes trains the team to treat a failure as noise, so a future genuine regression is likely to be re-run and dismissed the same way instead of being investigated and fixed.',glossary:[['Testing pyramid','A guideline for the relative proportion of unit, integration, and end-to-end tests in a healthy suite.'],['Flaky test','A test that fails intermittently without a real change in the behavior it checks.'],['Auto-waiting','A test tool automatically waiting for an element or condition before acting or asserting, instead of a fixed delay.'],['Test double','A controlled stand-in for a real dependency, such as a mocked network response, used to isolate a test.']],sources:[{title:'Testing Library: Guiding Principles',url:'https://testing-library.com/docs/guiding-principles/'},{title:'Playwright: Best Practices',url:'https://playwright.dev/docs/best-practices'}]});
guides.push({slug:'auth-and-oauth-flows',title:'Authentication and OAuth: understand the flow before wiring a library',category:'Backend & systems',summary:'Trace an OAuth 2.0 redirect step by step and learn why tokens must never sit where page scripts can read them.',goals:['Separate authentication from session management','Trace an authorization code redirect through three parties','Explain why token storage location is a security decision'],sections:[
{id:'identity',title:'1. Authentication proves identity, sessions remember it',paragraphs:[`Consider CourseVault, a study platform where a student signs in with an email and password. The moment the server checks that password against a stored hash and confirms a match is authentication: a single act of proving who the caller is. Everything that happens on the next fifty page views is a different problem, because HTTP requests do not carry memory between them on their own.`,`Session management is the mechanism that lets the server recognize the same student on the next request without repeating the password check. After a successful login, the server issues a session identifier, usually inside a cookie, and the browser resends that cookie automatically. The server looks up the identifier and treats the request as coming from the already-authenticated student, until the session expires or is revoked.`,`A common mistake is trusting a frontend flag such as isLoggedIn stored in memory or local storage as if it were proof of anything. That flag can be set by a script for cosmetic reasons, such as hiding a sign-in button, but it enforces nothing. Every request that needs to know who the caller is must be checked against the real session on the server, not against a value the browser is simply displaying back to itself.`]},
{id:'delegation',title:'2. OAuth solves a different problem than login',paragraphs:[`Suppose CourseVault wants to place assignment deadlines directly onto a student calendar hosted by a separate provider. Handing the student password for that provider to CourseVault would be a disaster: CourseVault would gain full control of the account, forever, with no way for the student to limit or later revoke just that one permission. OAuth exists to answer a narrower question: how can one application do a specific, limited thing on a resource owned by another provider, without ever seeing the password for that account.`,`The answer is delegated, scoped access. The student authorizes CourseVault to perform one narrow action, such as reading calendar availability, and the provider hands CourseVault a token that proves exactly that grant and nothing more. The student can revoke that grant later from the provider settings without changing any password, and CourseVault never learns the password at all.`,`It is worth naming a related but distinct idea: using this same machinery so a student can sign in to CourseVault using an existing account from another provider is usually built as OpenID Connect on top of OAuth, answering the authentication question rather than the delegated-access question. The flow traced in this guide is the delegated-access case, which is the one most developers reach for first and most often misunderstand.`]},
{id:'flow',title:'3. Trace the authorization code redirect step by step',paragraphs:[`The exchange starts when the student clicks Connect Calendar inside CourseVault. CourseVault, acting as the client, redirects the browser to the authorization server, the calendar provider, at its /authorize endpoint, attaching its client_id, the scope it wants, a redirect_uri it controls, and a random state value it will check later. The browser is now talking directly to the provider, not to CourseVault.`,`The provider authenticates the student if needed and shows a consent screen naming exactly what CourseVault is requesting. If the student approves, the provider redirects the browser back to the registered redirect_uri, attaching a short-lived authorization code and the same state value CourseVault sent. This code is not the access token; by itself it proves only that a specific consent just happened.`,`CourseVault backend now exchanges that code for real tokens by calling the provider token endpoint directly, server to server, including its client secret. This request never happens inside the browser, because the secret must never be exposed to it. The provider responds with an access token, and often a refresh token, which CourseVault can now use to call the calendar API on the student behalf.`],language:'HTTP',code:`GET https://provider.example/authorize
  ?client_id=coursevault-web
  &redirect_uri=https://coursevault.app/oauth/callback
  &response_type=code
  &scope=calendar.read
  &state=8f3c1a9d0e

# after consent, provider redirects the browser to:
GET https://coursevault.app/oauth/callback?code=abc123&state=8f3c1a9d0e

# CourseVault's server then exchanges the code, server to server:
POST https://provider.example/token
Content-Type: application/x-www-form-urlencoded

grant_type=authorization_code&code=abc123
&redirect_uri=https://coursevault.app/oauth/callback
&client_id=coursevault-web&client_secret=***`},
{id:'roles',title:'4. Three parties, three separate trust boundaries',paragraphs:[`The client is CourseVault: it wants access but does not own the data or the identity check. The authorization server is the calendar provider login and consent system: it owns the password check and the decision to grant or deny a scope. The resource server is the calendar API itself: it owns the actual events and only cares whether a presented token is valid for the requested scope.`,`When CourseVault later fetches calendar events, it sends the access token in an Authorization: Bearer header directly to the resource server. The resource server validates that token independently; it does not need to know anything about how the token was issued or what the consent screen looked like, only that the token is currently valid and covers the requested scope.`,`This separation is the entire point of the design. CourseVault never sees the student password. The authorization server never sees the calendar events themselves. The resource server never participates in the code exchange. Each party trusts only the narrow slice of the flow it actually needs to, which limits how much damage a single compromised party can do.`]},
{id:'storage',title:'5. Tokens must live where page scripts cannot read them',paragraphs:[`An access token is a bearer credential: whoever holds it can act as the student for as long as it remains valid, with no further proof required. If CourseVault stores that token in localStorage or in a plain, script-readable cookie, then any script that manages to run on that page, including one smuggled in through a compromised dependency or an injected script tag, can read document.cookie or call localStorage.getItem and send the token straight to an attacker.`,`The standard defense is to keep the token somewhere JavaScript running on the page structurally cannot reach. A cookie marked HttpOnly is invisible to document.cookie and to any script, while the browser still attaches it automatically on requests to the issuing domain. Combined with Secure, so it is only sent over HTTPS, and an appropriate SameSite setting, this removes an entire category of token-theft attacks without requiring the application code to be perfect.`,`Where an access token genuinely must be available to frontend JavaScript, for example to attach it to a fetch call made directly from the browser, keep it only in memory for the life of that page and never persist it to localStorage or sessionStorage, and keep its lifetime short. The refresh token, which can mint new access tokens, is even more sensitive than the access token and belongs server-side, never in the browser at all.`],language:'HTTP',code:`# what CourseVault should send back after login:
Set-Cookie: session=9f2e...; HttpOnly; Secure; SameSite=Lax

# what a page-readable token looks like, and why it is dangerous:
localStorage.setItem('access_token', token);
// any script that runs on this page, injected or not, can now read
// localStorage.getItem('access_token') and exfiltrate it`},
{id:'defense',title:'6. Design the parts that stop a stolen code or link',paragraphs:[`The state parameter sent at the start of the flow exists to stop cross-site request forgery against the callback. CourseVault generates a random value, stores it tied to the current browser session, and checks on return that the state coming back from the provider matches. Without this check, an attacker could trick a victim browser into completing an authorization flow initiated by the attacker, linking the attacker calendar to the victim CourseVault account.`,`The redirect_uri is not a free-form value either. The provider only redirects the authorization code to a URI that CourseVault registered in advance, exactly. This stops an attacker from registering a look-alike client and redirecting a leaked code to a server they control, because the provider will simply refuse to send the code anywhere outside the registered list.`,`Finally, plan for token lifetime deliberately: short-lived access tokens limit the damage window if one leaks, while a longer-lived refresh token lets CourseVault silently renew access without asking the student to consent again. Because the refresh token can produce new access tokens indefinitely, treat it with at least as much care as a password, including revocation support when a student disconnects the integration.`]}],exercise:['Sketch the three redirects in the authorization code flow, labeling which party initiates each one.','Explain why the token exchange step must happen server to server rather than in browser JavaScript.','List two concrete consequences of storing an access token in localStorage instead of an HttpOnly cookie.'],answer:'The browser is redirected to the authorization server, then back to the client callback with a code, and the client server separately calls the token endpoint. The exchange needs a client secret, which must never reach the browser, so it happens server to server. A token in localStorage can be read and exfiltrated by any script that runs on the page, including one injected through a compromised dependency.',glossary:[['Authorization code','A short-lived value proving a consent just happened, exchanged once for tokens.'],['Access token','A bearer credential that grants API access for as long as it remains valid.'],['Refresh token','A longer-lived credential used to obtain new access tokens without repeating consent.'],['State parameter','A random value that ties the callback back to the request that started it, preventing forgery.']],sources:[{title:'RFC 6749: The OAuth 2.0 Authorization Framework',url:'https://datatracker.ietf.org/doc/html/rfc6749'},{title:'MDN: Using HTTP cookies',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Cookies'}]});
guides.push({slug:'caching-strategies',title:'Caching strategies: serve fast without serving stale',category:'Backend & systems',summary:'Layer browser, CDN, and server-side caching deliberately, and choose invalidation before flipping caching on.',goals:['Distinguish browser, CDN, and server-side caching','Read and set Cache-Control and ETag correctly','Choose between TTL and explicit purge for a given feature'],sections:[
{id:'tradeoffs',title:'1. Caching trades freshness for speed, on purpose',paragraphs:[`CourseVault recomputes its featured courses list from the database on every request, even though the underlying data changes a few times a day at most. Caching stores that computed result so a later request can be answered without redoing the work, reducing both latency for the student and load on the database. The saving is real, but it is not free.`,`Every cache introduces a lag between what is true right now at the source of truth and what the cache is currently serving. The central design question for any cache is not whether to cache, but how wrong an answer is tolerable, and for how long, before that staleness actually matters to someone. A five-minute-old featured courses list is harmless; a five-minute-old account balance is not.`,`Caching also happens in layers with different owners: the browser cache on the student device, a CDN edge cache in front of the server, and a server-side data cache such as Redis in front of the database. Treating caching as one single setting is the most common mistake here, because each layer has its own lifetime, its own invalidation mechanism, and its own failure modes.`]},
{id:'browser',title:'2. Browser caching: Cache-Control and ETag',paragraphs:[`Cache-Control is a response header telling the browser whether, and for how long, it may reuse a previously fetched response for the same URL without contacting the server again. A course logo image that rarely changes can carry Cache-Control: max-age=86400, letting the browser skip the network entirely for a full day for that exact URL.`,`ETag takes a different approach for content that might change. The server computes a stable identifier for a specific response body and returns it as an ETag header. On a later request, the browser sends that value back in If-None-Match, and the server can answer with a bare 304 Not Modified when the content has not actually changed, saving the bandwidth of resending the body while still checking freshness on every request.`,`These two mechanisms save different things. A long max-age saves an entire round trip, since the browser does not even ask again until it expires. An ETag still asks every time but saves the body transfer when nothing changed. A page showing one student private grade should instead carry Cache-Control: no-store, so it is never kept anywhere, by any layer, past the single response that served it.`],language:'HTTP',code:`# a rarely-changing static asset:
Cache-Control: public, max-age=86400

# a resource that changes sometimes, checked every time:
ETag: "a1b2c3"
# next request from the browser:
If-None-Match: "a1b2c3"
# server replies, if unchanged:
HTTP/1.1 304 Not Modified

# a private, per-student response that must never be cached:
Cache-Control: private, no-store`},
{id:'cdn',title:'3. CDN edge caching moves the copy closer to the reader',paragraphs:[`A CDN keeps copies of a response at edge nodes distributed geographically, so a request for the CourseVault public catalog page from a student in Manila can be answered from a nearby edge node rather than crossing the network to the origin server. The cache key is usually the full URL plus a chosen set of headers, and a hit never reaches the origin at all.`,`This changes how you debug a caching problem. If curling the origin server directly shows the updated page but the site still shows the old one to real visitors, the most likely explanation is that an edge node is still holding a cached copy, not that the deployed code is wrong. Checking the response headers, such as a vendor-specific cache status header reporting HIT or MISS, before assuming the application is broken saves a lot of wasted investigation.`,`A CDN cannot safely cache a personalized or authenticated response under a shared cache key unless the origin is careful about it, for example by marking such responses private or no-store, or by varying the cache key on something that identifies the student. Accidentally letting an edge node serve one student data to a different student is a data leak, not merely a staleness bug, and deserves the same seriousness as any other access-control failure.`]},
{id:'server',title:'4. Server-side caching keeps expensive work out of the request path',paragraphs:[`CourseVault also computes an expensive per-cohort completion report from the database on demand. Server-side caching, using a fast store such as Redis, keeps the result of that expensive computation so a repeat request for the same report can skip straight to the cached value instead of recomputing it from scratch.`,`The common pattern is cache-aside: on a request, check the cache first; on a miss, compute the value from the real source of truth, the database, and then store that result in the cache with an expiration before returning it; on a hit, return the cached value directly without touching the database at all.`,`A server-side cache can go stale exactly like a browser or CDN cache, and it introduces a second failure mode: unbounded growth if nothing ever expires or gets evicted. A time-to-live and an eviction policy, such as least-recently-used, are part of the design from the start, not an afterthought added once memory usage becomes a problem in production.`],language:'TypeScript',code:`async function getCohortReport(cohortId: string) {
  const cacheKey = 'cohort-report:' + cohortId;
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);

  const report = await computeCohortReportFromDatabase(cohortId);
  await redis.set(cacheKey, JSON.stringify(report), { EX: 300 }); // 5 minute TTL
  return report;
}`},
{id:'invalidation',title:'5. Choose TTL, explicit purge, or both, before turning caching on',paragraphs:[`A time-to-live expires an entry automatically after a fixed duration. It is simple, requires no coordination with the write path, and bounds staleness to a known window, but it also means a student can see stale data for up to that whole window even immediately after a real change was saved.`,`Explicit invalidation acts the moment the underlying data changes: when a teacher edits a course description, the write path actively deletes or updates the relevant cache entry and any CDN path that served it. This is more accurate, but only as good as the write path coverage; a code path that changes the data without knowing which caches to purge leaves a stale copy behind indefinitely.`,`Many production systems combine both deliberately: a short TTL as a safety net, plus explicit purge on the writes that matter most. If a purge is ever missed by a bug or an unanticipated code path, the short TTL still self-heals the cache within a bounded time instead of leaving the wrong answer in place forever.`]},
{id:'debug',title:'6. Diagnose a stale-data report layer by layer',paragraphs:[`When a student reports seeing old data, check from the layer closest to them backward: what the browser devtools show was actually used, disk cache, memory cache, a 304, or a fresh 200; then what the CDN reports for that request, a hit or a miss; then whether the server-side cache or the database itself actually holds the updated value.`,`Stale-data bugs are notoriously confusing precisely because the same symptom, an old value showing up, can be produced by any of the three layers independently, and they can compound. Fixing the database value while an edge node still serves a cached page will look, to the student, exactly like the fix never happened.`,`The closing principle is to decide the caching layer and the invalidation strategy for a given piece of data before enabling caching on it, driven by how wrong an answer would be tolerable for that specific feature, rather than by copying whatever default settings were used somewhere else in the codebase.`]}],exercise:['Write the Cache-Control header you would use for a student private dashboard page.','Explain the difference between what max-age saves and what an ETag saves.','Design a TTL plus explicit-purge strategy for the CourseVault featured courses list.'],answer:'The private dashboard should send Cache-Control: private, no-store so it is never kept by any shared layer. max-age avoids a round trip entirely until it expires, while an ETag still makes a request every time but can avoid resending the body via a 304. The featured list can use a five-minute TTL as a safety net plus an explicit cache purge whenever an editor changes which courses are featured.',glossary:[['Cache-Control','A response header that controls whether and how long a response may be reused.'],['ETag','A stable identifier for a specific response body used to check freshness without resending it.'],['TTL','Time to live: the fixed duration after which a cached entry expires automatically.'],['Cache-aside','A pattern that checks a cache first and only computes from the source of truth on a miss.']],sources:[{title:'MDN: Cache-Control',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control'},{title:'MDN: HTTP caching',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching'}]});
guides.push({slug:'message-queues-async-work',title:'Message queues: move slow work off the request path',category:'Backend & systems',summary:'Build the producer, queue, and consumer vocabulary and design retries, idempotency, and dead-letter handling from the start.',goals:['Explain why slow work should leave the request path','Trace a message from producer to consumer','Design for retries, idempotency, and dead-letter handling'],sections:[
{id:'blocking',title:'1. A slow step inside a request punishes every request',paragraphs:[`When a CourseVault student finishes enrolling in a course, the request handler currently sends a welcome email and generates a PDF certificate before it responds. If the email provider is slow that day, the student waits for it needlessly. If the email provider is briefly down, the whole enrollment request can fail even though the enrollment itself was recorded successfully.`,`The general principle is that an HTTP request and response cycle is meant to be answered quickly, and work whose duration is unpredictable, or whose failure should not doom an otherwise-successful action, belongs off that path. Sending an email, resizing an image, and generating a report are common examples: useful, but not something the student should have to wait on or be blocked by.`,`A message queue is the mechanism for moving that work off the path. Instead of doing the slow step inline, the request handler places a small description of the work, such as send welcome email to user 42, onto a queue and returns immediately. A separate process picks that description up later and performs the actual work, on its own schedule.`]},
{id:'vocabulary',title:'2. Producer, consumer, and queue are the core vocabulary',paragraphs:[`A producer is the part of the system that creates a message describing work to be done; in this example, it is the enrollment request handler. A consumer, sometimes called a worker, is a separate process that reads messages and performs the described work; here, it is the process that actually sends the email. The queue, or broker, sits between them, holding messages until a consumer is ready for them.`,`A message is deliberately small: a description of work, such as an identifier and an action, not the entire application state. This is a different shape of call than a normal function call, where the caller passes real objects directly and gets a return value back immediately.`,`The benefit of this separation is that the producer does not need a consumer to be running at that exact moment, and several consumers can read from the same queue in parallel for more throughput. The cost is that the producer also gives up the immediate return value and the immediate exception that a direct function call would have given it; success or failure of the actual work is now known later, not right away.`]},
{id:'produce',title:'3. Keep the message small, explicit, and self-contained',paragraphs:[`When CourseVault enqueues the welcome-email job, it should send a small, explicit payload describing the work: a message type and the identifiers needed to look everything else up, such as the user id and course id, not a full copy of the user record. The message may be picked up seconds or hours later, possibly by a process running on a different machine, so it needs to be safely serializable on its own.`,`Sending only identifiers rather than full objects also avoids a subtler bug: if the message carried a copy of the student profile at enqueue time, and that profile changed before the message was processed, the consumer would act on stale data without knowing it. Looking the record up fresh at consumption time keeps the work correct relative to current state.`,`This also keeps the queue itself lightweight, since it is storing small descriptions of work rather than large payloads, which matters once the queue is handling a high volume of messages across many kinds of jobs.`],language:'TypeScript',code:`await queue.publish('send_welcome_email', {
  userId: enrollment.userId,
  courseId: enrollment.courseId,
});
// the request handler returns to the student immediately after this call,
// without waiting for the email to actually be sent`},
{id:'consume',title:'4. Consumers must acknowledge only after real success',paragraphs:[`A consumer runs a loop: pull the next available message, process it, and then explicitly acknowledge it once processing genuinely succeeded. While a message is being processed it is typically kept invisible or locked so another consumer instance does not also pick it up at the same time.`,`If a consumer crashes partway through, before it acknowledges, the broker eventually redelivers that same message to another consumer instance, on the assumption that unacknowledged work may not have completed. This redelivery is a safety feature, but it directly implies that the same message can, and eventually will, be delivered more than once.`,`Running several consumer instances against the same queue increases throughput, since messages can be processed in parallel, but both the per-message processing time and the number of running consumers determine how quickly a backlog actually drains.`],language:'JavaScript',code:`while (true) {
  const message = await queue.receive('send_welcome_email');
  if (!message) continue;
  try {
    await sendWelcomeEmail(message.body.userId, message.body.courseId);
    await queue.acknowledge(message);
  } catch (err) {
    await queue.nack(message); // let the broker retry or redeliver
  }
}`},
{id:'idempotent',title:'5. Design every handler to survive being run twice',paragraphs:[`Because redelivery after a crash means the same message can be processed more than once, a job handler must be idempotent: running it twice must not double the effect. Sending the welcome email twice is a bad outcome, so a careful handler checks whether a welcome email was already recorded as sent for this enrollment before sending another.`,`Retries with backoff make sense for transient failures, such as an email provider being briefly unreachable, where waiting and trying again is likely to succeed. They do not make sense for permanent failures, such as an invalid email address, which will fail identically no matter how many times it is retried, and should be treated differently from the start.`,`A concrete idempotency technique is to derive a stable key from the message content, such as enrollment id plus job type, and record in a database or Redis that this exact unit of work already completed. On any retry or redelivery, the handler checks that key first and skips the work entirely if it is already marked done.`]},
{id:'deadletter',title:'6. Plan for permanent failure and do not assume ordering',paragraphs:[`After a fixed number of failed attempts, a message should move to a dead-letter queue rather than being retried forever or silently discarded. A dead-letter queue is simply a separate place to hold messages that consistently failed, so a person can inspect what went wrong, such as a malformed payload or a permanently invalid email address, instead of the failure disappearing without a trace.`,`Ordering guarantees vary a great deal by broker and configuration. Some systems guarantee strict order only within a single partition or a single key, and most give no guarantee at all about the order messages are processed in across multiple consumers. Designing as if messages will always be processed in the order they were sent, when the chosen queue does not actually promise that, is a common source of subtle bugs.`,`A message queue trades the certainty of an immediate synchronous result for resilience and scalability, but none of retries, idempotency, or dead-letter handling comes for free. Each is a decision the developer has to make explicitly for the job at hand, based on what that specific job can tolerate.`]}],exercise:['Rewrite the welcome-email flow so the enrollment request never waits on the email provider.','Explain what redelivery means for how a job handler must be written.','Design a dead-letter policy for a job that keeps failing due to a malformed payload.'],answer:'The enrollment handler should enqueue a small message with the user and course ids and return immediately, leaving a separate consumer to send the email later. Because a crashed consumer causes redelivery, the handler must check whether the email was already sent before sending it again. A malformed-payload job should retry a small fixed number of times, then move to a dead-letter queue for manual inspection rather than retrying forever.',glossary:[['Producer','The part of a system that creates a message describing work to be done.'],['Consumer','A process that reads messages from a queue and performs the described work.'],['Idempotency','A property where running the same operation more than once has the same effect as running it once.'],['Dead-letter queue','A separate queue holding messages that failed repeatedly, for later inspection.']],sources:[{title:'AWS: What is a message queue?',url:'https://aws.amazon.com/message-queue/'},{title:'RabbitMQ: Reliability guide',url:'https://www.rabbitmq.com/docs/reliability'}]});
guides.push({slug:'graphql-fundamentals',title:'GraphQL fundamentals: one endpoint, precise queries',category:'Backend & systems',summary:'Write a schema, a query, and a resolver, then confront the N+1 problem and compare fairly against REST.',goals:['Read a GraphQL schema and write a matching query','Explain how a resolver produces one field of a response','Recognize the N+1 problem and when REST stays simpler'],sections:[
{id:'motivation',title:'1. One endpoint, exactly the fields requested',paragraphs:[`A REST endpoint such as /courses/1 on CourseVault returns a full course object shaped by the server. If a screen also needs the instructor name and a live enrollment count, the client either makes several requests in sequence, a waterfall, or the server bundles everything the object could ever need into one large response, most of which this particular screen will never use.`,`GraphQL answers this by exposing one endpoint, typically /graphql, where the client sends a query describing exactly which fields it wants, nested however it needs them, and the server returns a response shaped to match that query and nothing more. The overfetching and underfetching problem is addressed by construction, because the client states its own shape instead of accepting whatever shape the server chose for everyone.`,`This precision is not free, and it is worth saying so before going further: it moves complexity from designing many small endpoints to designing one shared schema and the resolvers behind it. Whether that trade is worthwhile depends on the situation, which this guide returns to directly later.`]},
{id:'schema',title:'2. The schema is a contract, checked before any resolver runs',paragraphs:[`A GraphQL schema declares types and their fields explicitly. A Course type might declare id, title, and instructor, where instructor is itself an Instructor type rather than a raw string, letting a query follow that relationship directly. An exclamation mark after a type means that field is guaranteed non-null.`,`Because the schema is a contract, a client request is validated against it before any resolver function ever runs. Asking for a field that does not exist on Course fails immediately with a clear, specific error naming the problem field, which is a sharper failure than a REST client silently receiving undefined for a field the server never included.`,`Every schema needs an entry point, conventionally a Query type, listing the top-level fields a client may ask for, such as course(id: ID!): Course and courses: [Course!]!. Everything a client can ever request starts from one of these root fields.`],language:'GraphQL',code:`type Instructor {
  id: ID!
  name: String!
}

type Course {
  id: ID!
  title: String!
  instructor: Instructor!
}

type Query {
  course(id: ID!): Course
  courses: [Course!]!
}`},
{id:'resolver',title:'3. A resolver produces one field at a time',paragraphs:[`A client query for CourseVault might ask for a single course id, its title, and its instructor name, all in one request, in exactly that shape. The server does not need a bespoke endpoint written in advance for this particular combination of fields; it only needs its existing schema and resolvers.`,`A resolver is a function responsible for producing the value of one specific field. Course.instructor is typically resolved by taking the parent course object, reading its instructorId, and looking up the matching instructor record, often from a database. The resolver for Course.title, by contrast, might just return a property already present on the parent object with no extra lookup at all.`,`The schema does not care where a resolver gets its data, whether from a database, another internal service, or a value already sitting on the parent object, only that the value it returns matches the declared type. This gives a lot of freedom in how the underlying data is actually fetched and assembled.`],language:'TypeScript',code:`const resolvers = {
  Query: {
    course: (_parent, args) => db.courses.findById(args.id),
  },
  Course: {
    instructor: (course) => db.instructors.findById(course.instructorId),
  },
};`},
{id:'nplusone',title:'4. The N+1 problem hides inside independent field resolvers',paragraphs:[`Now ask for a list of many courses, each with its instructor name. The Query.courses resolver runs once and fetches every course row in a single call. But then, by default, the Course.instructor resolver runs once per course in that list, issuing one more database lookup for each course individually.`,`For a hundred courses, that is one query to fetch the courses plus one hundred more queries, one per instructor, a total of one hundred and one database calls to answer a single GraphQL request. This is the N+1 problem: it arises because GraphQL resolves each field somewhat independently, unlike a hand-written SQL join that would fetch everything in one statement, and the cost is invisible just from reading the query text.`,`The standard fix is batching, often through a pattern called a dataloader: instead of each Course.instructor resolver firing its own database call immediately, all of the instructor ids requested within one execution are collected together, a single WHERE id IN (...) query fetches them all at once, and the results are then handed back to each individual resolver that asked for one.`]},
{id:'comparison',title:'5. REST still wins when the shape is stable and simple',paragraphs:[`REST tends to be simpler when a client needs a fixed, predictable shape of data, such as a mobile app screen that always wants exactly the same course fields. A tailored endpoint for that one screen is straightforward to cache using ordinary HTTP mechanisms, URLs, ETags, and standard status codes, in a way a single generic /graphql endpoint answering many different shapes with POST requests generally is not.`,`REST tooling is also often simpler to operate day to day. Curling an endpoint, reading its status code, and inspecting browser devtools network requests map cleanly onto REST, whereas GraphQL frequently needs its own dedicated tooling to get the same visibility into what a particular query actually did on the server.`,`GraphQL earns its added complexity specifically when several different clients, a web app, a mobile app, and a partner integration, all need meaningfully different shapes of the same underlying data. Maintaining a separate hand-tailored REST endpoint for every one of those shapes would likely cost more, in the long run, than the schema and resolver overhead GraphQL introduces up front.`]},
{id:'practice',title:'6. Watch query cost, not just query correctness',paragraphs:[`When diagnosing a slow GraphQL request, check how many database queries a single request actually produced relative to how many items it returned; a request returning fifty courses that produced fifty-one database calls is a strong signal of an unbatched N+1 pattern hiding behind a perfectly correct-looking query.`,`Because a client can request deeply nested or expensive fields, a schema also needs guardrails, such as pagination on list fields and limits on query depth or computed cost, so that one overly ambitious client query cannot accidentally demand an unreasonable amount of server work.`,`GraphQL and REST are answering slightly different questions: one optimizes for letting the client shape the response precisely, the other optimizes for simple, cacheable, predictable endpoints. Choosing between them is a real design decision based on how many different shapes of the same data need to be served, not a default to reach for automatically.`]}],exercise:['Write a GraphQL query requesting a course title and its instructor name.','Explain why a list of one hundred courses with instructor names can trigger one hundred and one database calls.','Describe when a tailored REST endpoint would be simpler than adding this to a GraphQL schema.'],answer:'A query can request course(id: "1") { title instructor { name } } in one round trip. Each course independent instructor resolver fires its own lookup by default, so one hundred courses produce one hundred extra calls on top of the initial courses query, unless batched. A single mobile screen needing one fixed, stable shape is usually simpler and more cacheable as a dedicated REST endpoint than as a new GraphQL query.',glossary:[['Schema','The declared types and fields a GraphQL server accepts and can return.'],['Resolver','A function responsible for producing the value of one specific field.'],['N+1 problem','A pattern where one query to fetch a list triggers one further query per item.'],['Dataloader','A batching pattern that collects requested ids and fetches them in one call.']],sources:[{title:'GraphQL: Introduction',url:'https://graphql.org/learn/'},{title:'GraphQL: Schemas and Types',url:'https://graphql.org/learn/schema/'}]});
guides.push({slug:'websockets-realtime',title:'WebSockets and real-time updates: beyond request and response',category:'Backend & systems',summary:'Trace the upgrade handshake, design reconnection and ordering for a live chat feature, and know when a simpler tool is enough.',goals:['Explain how a WebSocket connection begins as an HTTP upgrade','Design a reconnection strategy with backoff','Reason about ordering and delivery guarantees for live messages'],sections:[
{id:'handshake',title:'1. A WebSocket begins life as an HTTP request',paragraphs:[`CourseVault wants a live chat feature for study groups, where a message typed by one student appears for everyone else immediately. Repeatedly polling an endpoint such as /messages every second would work, but each poll is a brand new request and response even when nothing changed, adding latency and wasted load for every idle student in the room.`,`A WebSocket connection instead begins as an ordinary HTTP request carrying an Upgrade: websocket header and a Connection: Upgrade header, along with a Sec-WebSocket-Key value. If the server agrees, it responds with status 101 Switching Protocols, and from that point the same underlying TCP connection is reused for a different message framing, no longer HTTP at all.`,`Because the handshake itself is an HTTP exchange, a WebSocket connection can be established over the same port and scheme conventions as a normal web request, commonly wss:// over port 443. After that single upgrade, though, messages flow freely in both directions without a new request having to be issued for either side to send something.`]},
{id:'persistent',title:'2. The connection stays open, and either side can speak first',paragraphs:[`Once open, the connection stays alive as long as both sides keep it that way, in contrast to an ordinary HTTP exchange where each logical request completes and is done. Either party, browser or server, can send a message at any moment without waiting to be asked, which is exactly what lets the server push a new chat message the instant it arrives rather than waiting for the next poll.`,`On the browser side, a WebSocket object stays open for as long as the page needs it and fires an onmessage event for each incoming message. On the server side, the application has to actively track which open socket belongs to which student, since there is no request object to read that information from fresh each time the way there would be with a normal HTTP handler.`,`This convenience has a real resource cost: an open connection consumes memory, and typically an entry in an event loop or a dedicated thread, for its entire lifetime rather than only for the brief duration of a single request. A server built to serve short HTTP requests efficiently is not automatically ready to hold thousands of long-lived chat connections open at once; that is a different capacity planning problem.`]},
{id:'reconnect',title:'3. Reconnection needs backoff, not a tight retry loop',paragraphs:[`Connections drop for ordinary reasons: a phone goes to sleep, a wifi network hiccups, or the server itself restarts during a deploy. The client has to detect the close or error event and decide whether, and how, to try reconnecting rather than simply leaving the student silently disconnected from the chat.`,`Reconnecting immediately in a tight loop can make a struggling server worse by hammering it with new connection attempts from every disconnected client at once. Exponential backoff with jitter is the standard fix: wait a little longer between each successive attempt, and add a small random amount to that wait so that many clients disconnected at the same moment do not all retry in lockstep.`,`After a successful reconnect, the client has almost certainly missed some messages that were sent while it was offline. Simply picking up new messages from the fresh connection and assuming nothing was missed is not safe; the client needs to resynchronize explicitly, for example by fetching recent history or the messages after the last sequence number it saw.`],language:'JavaScript',code:`let attempt = 0;
function connect() {
  const socket = new WebSocket('wss://coursevault.app/chat');
  socket.onopen = () => { attempt = 0; };
  socket.onclose = () => {
    const delay = Math.min(30000, 1000 * 2 ** attempt) + Math.random() * 500;
    attempt++;
    setTimeout(connect, delay);
  };
}
connect();`},
{id:'ordering',title:'4. Ordering and delivery are not guaranteed by the socket alone',paragraphs:[`Within a single open connection, the underlying transport generally delivers bytes, and so messages, in the order they were sent. That guarantee holds only for that one connection; it disappears entirely across a reconnect, and it never existed across multiple separate connections or multiple servers in the first place.`,`WebSockets themselves make no application-level promise about delivery. If the server sends a chat message at the exact moment a connection drops, there is no built-in confirmation telling either side whether the client actually received it. Whether the application needs at-least-once, at-most-once, or exactly-once delivery for a given message is a decision the developer has to make and build on top of the raw socket.`,`A practical approach for CourseVault chat is to give every message a sequence number or timestamp assigned by the server. After reconnecting, the client can compare the last sequence number it saw against what the server reports as current and explicitly request any messages in between, rather than trusting the socket connection alone to be a complete and reliable record of the conversation.`]},
{id:'broadcast',title:'5. A server tracks room membership, not just individual sockets',paragraphs:[`A simple chat server keeps a set of open connections per study-group room. When a message arrives from one student in that room, the server iterates the set of connections for that room and sends the message to each one, including the sender if it wants to confirm delivery back to them.`,`That membership set must be cleaned up the moment a connection closes, or the server ends up holding references to dead sockets and slowly leaking memory, along with wasting effort trying to send to connections that are no longer there. Removing a socket from every room it belonged to on disconnect is not optional bookkeeping; it is required for the server to keep working correctly over time.`,`If chat runs across more than one server process for scale, a message from a student connected to server A has to reach a student connected to server B somehow, since neither process can see the other in-memory set directly. This typically requires a shared layer between the server instances, such as Redis pub/sub, to fan a message out to every process that might be holding a relevant connection.`],language:'JavaScript',code:`const rooms = new Map(); // roomId -> Set<WebSocket>

function joinRoom(roomId, socket) {
  if (!rooms.has(roomId)) rooms.set(roomId, new Set());
  rooms.get(roomId).add(socket);
  socket.on('close', () => rooms.get(roomId)?.delete(socket));
}

function broadcast(roomId, message) {
  for (const socket of rooms.get(roomId) ?? []) socket.send(message);
}`},
{id:'practice',title:'6. Choose the tool that matches how one-directional the need is',paragraphs:[`Not every feature that feels real-time needs a full, bidirectional WebSocket connection. When the client never needs to send frequent updates back to the server, occasional polling, or Server-Sent Events, a simpler one-directional push over plain HTTP, can meet the need with far less operational complexity than managing sockets, reconnection, and room membership.`,`When debugging a WebSocket feature, confirm in the network panel that the 101 upgrade response actually happened, check the close code and reason on unexpected disconnects rather than guessing at the cause, and verify that reconnection logic backs off correctly instead of spinning tightly against a struggling server.`,`Real-time features shift responsibility away from the comfortable assumption that the next ordinary request will simply fetch fresh data. Instead, the application must actively track connection state, handle reconnection and resynchronization, and decide its own ordering and delivery guarantees, which is a genuinely different design problem from typical request and response work.`]}],exercise:['Explain what changes about the HTTP request during a successful WebSocket upgrade.','Design a backoff schedule for reconnecting a dropped chat connection.','Describe how a client can detect and recover messages missed while disconnected.'],answer:'The initial HTTP request carries Upgrade and Connection headers, and a 101 response switches the same TCP connection to WebSocket framing instead of HTTP. A reasonable backoff doubles the wait after each failed attempt up to a cap and adds random jitter so clients do not retry in lockstep. On reconnect, the client compares its last known message sequence number against the server current one and requests anything in between rather than assuming nothing was missed.',glossary:[['Upgrade handshake','The initial HTTP exchange that switches a TCP connection to the WebSocket protocol.'],['Persistent connection','A connection that stays open so either side can send a message at any time.'],['Exponential backoff','A retry strategy that waits progressively longer between successive attempts.'],['Delivery guarantee','An explicit promise, built by the application, about whether a message is received at most once, at least once, or exactly once.']],sources:[{title:'MDN: WebSockets API',url:'https://developer.mozilla.org/en-US/docs/Web/API/WebSockets_API'},{title:'RFC 6455: The WebSocket Protocol',url:'https://datatracker.ietf.org/doc/html/rfc6455'}]});
guides.push({slug:'cicd-pipelines-in-depth',title:'CI/CD pipelines: build a release process you can trust',category:'DevOps & cloud',summary:'Turn install, test, build, and deploy into a sequence that fails loudly and gives you a rollback plan before you need one.',goals:['Name each pipeline stage and its job','Make failures stop the pipeline instead of hiding','Design a rollback plan before the first incident'],sections:[
{id:'stages',title:'1. See the pipeline as one accountable sequence',paragraphs:[`Picture a small team shipping a course-catalog web app. Early on, someone builds the project on their laptop, copies files to a server by hand, and hopes nothing was missed. This works until it does not: a forgotten environment variable, a dependency installed locally but not on the server, or a change nobody remembers making. A pipeline replaces that hope with a fixed sequence of stages that runs the same way every time, for every change.`,`The usual stages are install, lint and test, build, and deploy. Install brings in exact dependencies. Lint and test check that the code still behaves as expected. Build produces a runnable artifact. Deploy places that artifact where users can reach it. Each stage depends on the one before it succeeding, and each stage should do exactly one job so a failure points at a specific cause.`,`Treat the pipeline definition itself as part of the codebase, reviewed the same way as application code. A pipeline that only one person understands is a single point of failure. Write down what each stage assumes, what it produces, and what should happen when it fails, before wiring the stages together.`]},
{id:'install',title:'2. Install exact dependencies, not approximate ones',paragraphs:[`The install stage should reproduce the same dependency versions every time, not whatever happens to satisfy a version range on a given day. A lockfile records the exact resolved versions used the last time dependencies were installed successfully. Installing from the lockfile in CI means the pipeline tests the same dependency tree a developer tested locally, instead of a slightly different one resolved fresh on the runner.`,`This matters most when a transitive dependency ships a breaking patch release. Without a lockfile, that patch can silently enter a build the moment CI runs, even though nobody touched the project's own code. With a lockfile, the same patch only arrives when someone deliberately updates it and commits the new lockfile, which puts the change through review like anything else.`,`Caching the install step can speed up a pipeline considerably, but the cache key should include the lockfile hash so a changed lockfile always triggers a fresh install. A stale cache that skips installing a newly added dependency produces a confusing failure much later in the build stage, far from its real cause.`],language:'YAML',code:`# .github/workflows/ci.yml (excerpt)
jobs:
  install:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: 'npm'
      - run: npm ci   # installs exactly what package-lock.json records`},
{id:'test',title:'3. Make lint and test stages fail loudly and stop the pipeline',paragraphs:[`A pipeline that logs a test failure but still proceeds to build and deploy has not really tested anything; it has just printed a warning nobody will read in time. Each stage should return a nonzero exit code on failure, and the pipeline configuration should stop rather than continue to the next stage when that happens. This is usually the default behavior, but it is worth verifying explicitly, since a misconfigured "continue on error" flag defeats the entire purpose of the gate.`,`Linting and testing belong before the build stage, not after. Catching a broken function before spending minutes producing a build artifact saves time and keeps the failure close to its cause. It also means a failed pipeline run never produces an artifact that could be accidentally deployed by a later manual step.`,`Treat a flaky test as a bug in the test, not a nuisance to route around with retries or ignoring it. A test that fails intermittently for no code reason erodes trust in the whole pipeline; once a team starts re-running failed pipelines out of habit, a genuine failure will eventually be re-run past unnoticed.`],language:'YAML',code:`  test:
    needs: install
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm ci
      - run: npm run lint
      - run: npm test -- --ci
      # A nonzero exit from any step here stops downstream jobs.`},
{id:'build',title:'4. Build one artifact and promote the same one everywhere',paragraphs:[`Build the deployable artifact once per change, tag it with an identifier such as the commit hash, and promote that exact artifact through staging and production rather than rebuilding at each stage. Rebuilding separately for each environment risks a different dependency resolving slightly differently between builds, which means staging and production are no longer running the same code even though both "passed the pipeline."`,`Tagging the artifact with the commit hash, rather than a mutable label like latest, makes it possible to say precisely which source produced what is running in production at any moment. When a user reports a bug, the deployed tag tells you exactly which commit to inspect, without guessing which of several recent merges might be responsible.`,`Store build artifacts somewhere retrievable, such as a container registry or an artifact repository, with a retention policy. A pipeline that discards its artifact immediately after deploying makes a later rollback dependent on rebuilding from source, which may not even be possible if the toolchain has since changed.`]},
{id:'deploy',title:'5. Deploy through gates, not through a person\'s judgment',paragraphs:[`The deploy stage should require the exact conditions that make a release safe: passing tests, an approved artifact, and often a manual approval step for production even when everything upstream is automated. A gate here is not distrust of the team; it is an acknowledgment that some releases carry more risk than others, such as a schema change or a pricing update, and deserve a deliberate human decision at that specific point.`,`Deploying to a staging environment automatically on every merge to the main branch, while requiring an explicit approval for production, is a common middle ground. It gives the team fast feedback on staging without meaning that every commit reaches real users immediately. Decide this policy in advance, rather than improvising it during an already stressful release.`,`After deployment, run a small smoke check, such as requesting a health endpoint or loading the catalog page, before considering the release complete. A deploy step that only confirms the artifact was copied to a server has not confirmed the application actually starts and serves traffic there.`]},
{id:'rollback',title:'6. Design the rollback before the incident, not during it',paragraphs:[`Every deploy plan needs a matching rollback plan, decided while everyone is calm. The simplest rollback re-deploys the previous known-good artifact tag, which is exactly why keeping tagged artifacts around from the previous section matters. Deciding "we will figure out rollback if we ever need it" during an actual outage adds delay and mistakes at the worst possible moment.`,`A rollback is not only about code. If a deploy included a database migration, rolling back the application without considering the schema change can leave old code running against a new schema it does not expect. Migrations that add a column with a default value are usually safe to leave in place temporarily; migrations that rename or drop a column are not, and need a plan that keeps both versions compatible for a transition window.`,`Practice the rollback procedure occasionally when nothing is on fire, the same way a fire drill is more useful before a real fire. A rollback command that has only ever been read, never run, is likely to reveal a missing permission or an outdated script exactly when there is no time to debug it.`],language:'Terminal',code:`# Roll back to the previous known-good artifact tag
kubectl set image deployment/catalog-api api=registry.example.com/catalog-api:c3f1a90
kubectl rollout status deployment/catalog-api
# If the rollout itself misbehaves, undo it directly:
kubectl rollout undo deployment/catalog-api`}],exercise:['List the four pipeline stages for a project you know and name what each one verifies.','Explain why lint and test should run before the build stage rather than after.','Write the two-command rollback you would run if a deploy caused an error spike.'],answer:'Install brings in exact dependencies, lint/test verifies behavior, build produces one tagged artifact, and deploy places it with a gate and a smoke check. Lint and test run before build so a broken change is caught before time is spent producing an artifact. A rollback typically re-points the deployment at the previous artifact tag and confirms the rollout completed, for example kubectl set image followed by kubectl rollout status.',glossary:[['Pipeline','An automated sequence of stages that turns a code change into a running release.'],['Artifact','The built, versioned output of the build stage that gets deployed.'],['Gate','A required condition, automated or manual, that a release must satisfy before proceeding.'],['Rollback','Returning a service to a previous known-good release after a bad deploy.']],sources:[{title:'GitHub Actions: Understanding GitHub Actions',url:'https://docs.github.com/en/actions/learn-github-actions/understanding-github-actions'},{title:'Kubernetes: kubectl rollout',url:'https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/'}]});
guides.push({slug:'docker-kubernetes-fundamentals',title:'Docker and Kubernetes fundamentals: from one container to a managed fleet',category:'DevOps & cloud',summary:'Understand what a container really is compared with a virtual machine, then learn the Kubernetes vocabulary that lets you manage many of them.',goals:['Explain how a container differs from a virtual machine','Name pod, deployment, service, and replica correctly','Explain why an orchestrator replaces running containers by hand'],sections:[
{id:'container-vs-vm',title:'1. A container is not a small virtual machine',paragraphs:[`A virtual machine virtualizes hardware: a hypervisor presents each VM with its own virtual disk, network card, and memory, and each VM runs a complete operating system kernel on top of that virtual hardware. Starting a VM means booting an entire operating system, which can take tens of seconds to minutes and consumes memory for that whole OS even before your application starts.`,`A container instead virtualizes the operating system. It shares the host machine's kernel and uses OS features such as namespaces and control groups to give a process its own isolated view of the filesystem, processes, and network, while resource limits keep it from consuming more CPU or memory than allotted. Starting a container is closer to starting a regular process than booting a computer, which is why containers typically start in a fraction of a second.`,`This distinction explains why containers are so much lighter than VMs but also why they are not a stronger isolation boundary. A container escape that reaches the shared kernel affects the host and every other container on it, which is why running only trusted images and applying least-privilege settings still matters even though the workload is "just a container."`]},
{id:'image-and-container',title:'2. An image is the recipe, a container is the running dish',paragraphs:[`A Docker image is a read-only template built from a Dockerfile: a base layer, plus the files, dependencies, and startup command your application needs. Building an image packages "how to run this application" into something that can be stored, versioned by tag, and shared through a registry. A container is a running instance created from that image, the same way a running program is an instance of a compiled binary.`,`Because the image is fixed, starting several containers from the same image reliably produces the same starting state each time, which is the main promise containers make. This becomes especially valuable when a bug only reproduces "on the server" — if the server runs the exact image tested locally, that category of surprise mostly disappears.`,`A minimal Dockerfile for a small Node.js API shows the pattern: choose a base image, copy in dependency manifests first so Docker can cache the install step, install dependencies, copy the rest of the source, and declare the command that starts the process. Layer ordering matters for build speed, since Docker reuses cached layers until it reaches the first one that changed.`],language:'Dockerfile',code:`FROM node:20-slim
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --omit=dev
COPY . .
EXPOSE 3000
CMD ["node", "server.js"]`},
{id:'why-orchestrate',title:'3. Why you stop running containers by hand',paragraphs:[`Running one container with a plain docker run command works fine for a single service on a single machine. Problems appear once there are several services, several instances of each for redundancy, and a need to survive a crashed container or a failed machine. Manually restarting a crashed container, manually spreading instances across machines, and manually rewiring which instance receives traffic does not scale past a small number of services, and it does not happen fast enough when the person on call is asleep.`,`An orchestrator such as Kubernetes takes over that manual work. You describe the desired state — "run three instances of this image, restart any that crash, spread them across available machines" — and a set of controllers continuously works to make the actual state match it. If a machine goes down, Kubernetes reschedules the containers that were on it elsewhere, without a human needing to notice and intervene at 3 a.m.`,`This declarative approach is the main shift in thinking: you stop issuing individual commands and start describing an end state. The orchestrator's job is to keep reconciling reality toward that description, which is also why Kubernetes configuration is usually written as YAML files describing desired objects rather than as a sequence of shell commands.`]},
{id:'core-objects',title:'4. Pod, deployment, service: the vocabulary that matters first',paragraphs:[`A pod is the smallest deployable unit in Kubernetes: one or more containers that are scheduled together onto the same machine and share networking, so they can reach each other over localhost. Most pods run exactly one container; the multi-container case is for tightly coupled helper processes, not for grouping unrelated services. Pods are also disposable — Kubernetes expects to destroy and recreate them freely, so a pod should never be where you store data you care about keeping.`,`A deployment describes how many replicas — identical running copies — of a pod template should exist, and manages rolling out changes to them. If you set replicas to three, the deployment controller ensures three matching pods are running at all times, creating new ones if any are deleted or crash. Updating the image tag in a deployment triggers a rolling update, replacing old pods with new ones gradually rather than all at once.`,`A service gives a stable network address to a set of pods that come and go as replicas are created and destroyed. Pods get new internal addresses every time they are recreated, so nothing else should talk to a pod's address directly; a service watches for pods matching a label selector and load-balances requests across whichever ones currently exist. This is what lets a frontend reliably reach "the catalog API" without knowing or caring which specific pod answers.`],language:'YAML',code:`apiVersion: apps/v1
kind: Deployment
metadata:
  name: catalog-api
spec:
  replicas: 3
  selector:
    matchLabels: { app: catalog-api }
  template:
    metadata:
      labels: { app: catalog-api }
    spec:
      containers:
        - name: api
          image: registry.example.com/catalog-api:c3f1a90
          ports: [{ containerPort: 3000 }]
---
apiVersion: v1
kind: Service
metadata:
  name: catalog-api
spec:
  selector: { app: catalog-api }
  ports: [{ port: 80, targetPort: 3000 }]`},
{id:'scheduling',title:'5. What the scheduler and reconciliation loop actually do',paragraphs:[`When you submit a deployment, Kubernetes does not place pods arbitrarily. A scheduler considers each pending pod's resource requests against available capacity on each machine (called a node) and assigns the pod to a node that can satisfy them. Setting realistic CPU and memory requests matters here: requesting far more than the application needs wastes cluster capacity, while requesting too little risks the scheduler over-packing a node that then runs out of real resources under load.`,`After scheduling, Kubernetes continuously compares desired state against observed state through what is usually called a reconciliation loop. If a pod's container crashes, the same node restarts it locally; if an entire node disappears, the deployment controller notices the missing replica count and schedules a replacement pod elsewhere. This loop runs constantly and automatically, which is the practical payoff of describing state declaratively instead of issuing one-off commands.`,`This also means a healthy-looking deployment can still be quietly unhealthy if health checks are not configured. Kubernetes only knows a container is unhealthy if you tell it how to check, typically through a liveness probe that restarts a stuck container and a readiness probe that removes a not-yet-ready pod from receiving traffic through its service.`]},
{id:'when-not-to',title:'6. Recognizing when you do not need an orchestrator yet',paragraphs:[`Kubernetes solves real problems, but it also introduces real operational weight: cluster upgrades, networking concepts, and a steeper learning curve than a single server running a couple of containers. A small project with one or two services and modest traffic can often run comfortably on a single host with plain Docker or a simpler platform-as-a-service, and adding Kubernetes there mostly adds complexity without a matching benefit.`,`The signals that usually justify the move are multiple services that need independent scaling, a requirement to survive individual machine failures automatically, or a team large enough that a shared, declarative way of describing infrastructure prevents configuration drift between environments. If none of those pressures exist yet, it is reasonable to defer.`,`Whichever stage a project is at, the vocabulary transfers: understanding what an image, a container, a pod, a deployment, and a service each are is useful even on a single-container Docker deployment, because it clarifies which promises the current setup does and does not make, and what would change if it later needed to grow into a cluster.`]}],exercise:['Explain in one sentence why a container starts faster than a virtual machine.','Given a deployment with replicas set to 3, describe what happens to the count immediately after a pod crashes.','Explain what a service accomplishes that talking to a pod directly would not.'],answer:'A container shares the host kernel instead of booting its own operating system, so starting one is closer to starting a process than starting a computer. When a pod crashes, the deployment controller notices the replica count is below 3 and schedules a new pod to restore it. A service gives a stable address that keeps working as individual pods are replaced, since pods get new addresses every time they are recreated.',glossary:[['Image','A read-only template with an application, its dependencies, and its startup command.'],['Pod','The smallest deployable Kubernetes unit, one or more containers scheduled and networked together.'],['Deployment','A Kubernetes object that keeps a specified number of pod replicas running and manages rollouts.'],['Service','A stable network address that load-balances traffic across a changing set of matching pods.']],sources:[{title:'Docker overview',url:'https://docs.docker.com/get-started/docker-overview/'},{title:'Kubernetes: Concepts overview',url:'https://kubernetes.io/docs/concepts/overview/'}]});
guides.push({slug:'monitoring-and-observability',title:'Monitoring and observability: logs, metrics, and traces that answer questions',category:'DevOps & cloud',summary:'Build the three pillars of observability, design alerts that mean something, and use a trace to find the slow service in a request chain.',goals:['Explain what logs, metrics, and traces are each good for','Design an alert that signals a real problem, not noise','Use a trace to find which service in a chain is slow'],sections:[
{id:'why-observe',title:'1. You cannot fix what you cannot see',paragraphs:[`Imagine a checkout flow spread across a frontend, an order service, a payment service, and a notification service. A user reports that checkout "hangs." Without any visibility into the running system, diagnosing that report means guessing which of four services is responsible and reproducing the exact conditions locally, which may not even be possible if the failure depends on production load or a specific customer's data.`,`Observability is the ability to ask new questions about a running system's internal state using only the data it already emits, without shipping new code to add debugging output. Monitoring is closely related but narrower: watching known signals against known thresholds, such as "CPU usage above 90 percent." Observability is what lets you investigate an unanticipated failure mode that nobody wrote a specific check for in advance.`,`The three pillars — logs, metrics, and traces — each answer a different kind of question, and a mature system usually needs all three rather than treating one as a replacement for the others. Learning to reach for the right pillar first is often the difference between a five-minute diagnosis and an hour of guessing.`]},
{id:'three-pillars',title:'2. Logs, metrics, and traces answer different questions',paragraphs:[`Logs are discrete, timestamped events, usually text, describing something that happened: "order 4471 payment declined," "connection to database timed out after 5s." Logs are best for understanding exactly what happened for one specific event, but they are expensive to search across millions of lines and do not, by themselves, tell you about trends over time.`,`Metrics are numeric measurements sampled over time, such as requests per second, error rate, or memory usage. They are cheap to store and graph even at high volume, which makes them the right tool for spotting trends, setting thresholds, and building dashboards, but a metric like "error rate is 12 percent" does not explain which specific requests failed or why.`,`Traces follow one request as it moves through multiple services, recording how long each step, called a span, took. A trace answers "which of these four services made this particular checkout request slow," something no amount of aggregate metrics can pinpoint, because the slow request might be a small fraction of overall traffic that a system-wide average would hide.`],language:'Terminal',code:`# A structured log line carries enough detail to search and correlate later.
{"timestamp":"2026-03-02T14:03:11Z","level":"error","service":"payment",
 "order_id":"4471","event":"card_declined","reason":"insufficient_funds"}`},
{id:'good-alerts',title:'3. Design alerts around user impact, not raw noise',paragraphs:[`An alert that fires on every CPU spike, every restart, and every momentary blip trains the on-call person to ignore alerts, which is far more dangerous than having no alerts at all — a real incident then looks identical to the noise everyone has learned to dismiss. This is alert fatigue, and it is usually caused by alerting on a cause rather than an effect.`,`A more reliable approach alerts on symptoms that matter to users: elevated error rate, latency above an agreed threshold for a sustained window, or a queue that is growing rather than draining. "Error rate above 5 percent for 5 minutes" catches a real problem regardless of its underlying cause, whereas "CPU above 80 percent" fires for reasons that may not affect any user at all, such as a scheduled batch job.`,`Every alert that pages someone should have an associated action: something the on-call person can actually do in response. An alert nobody can act on, such as one for a metric with no known remediation, should become a dashboard entry instead of a page. Reviewing which alerts fired and whether each one led to a useful action is a good recurring habit for keeping the alert set trustworthy.`],language:'YAML',code:`# Example Prometheus alerting rule: symptom-based, not cause-based
groups:
  - name: checkout
    rules:
      - alert: HighCheckoutErrorRate
        expr: rate(http_requests_total{route="/checkout",status=~"5.."}[5m])
              / rate(http_requests_total{route="/checkout"}[5m]) > 0.05
        for: 5m
        labels: { severity: page }
        annotations:
          summary: "Checkout error rate above 5% for 5 minutes"`},
{id:'tracing-example',title:'4. Reading a trace to find the actual bottleneck',paragraphs:[`Distributed tracing assigns one trace ID to a request when it enters the system, and every service the request passes through records a span under that same trace ID with its own start time and duration. Reassembling those spans produces a timeline showing exactly how the total request time was spent across services, which is the only pillar built specifically to answer "where did the time go" for one request.`,`Suppose checkout takes 2100 milliseconds end to end. The trace might show the frontend request itself takes 40ms, the order service takes 60ms, the payment service takes 1900ms, and the notification service takes 100ms. Without a trace, "checkout is slow" implicates all four services equally; with a trace, the payment service is obviously where the investigation should focus, and everyone stops guessing about the other three.`,`It is worth then looking inside that one span: a slow payment service might itself be waiting on a downstream card-network call, which distributed tracing can also capture as a child span if the payment service propagates the trace context to its own outbound calls. Tracing only works end to end if every service in the chain participates in propagating the trace ID; a single service that drops it breaks the chain at that point.`]},
{id:'correlating',title:'5. Correlate the three pillars instead of picking one',paragraphs:[`In practice, an investigation moves between pillars rather than staying in one. A metrics dashboard first shows that checkout latency spiked at 14:03. A trace from around that time shows the payment service span ballooning to 1900ms. Logs from the payment service in that exact window, filtered by the trace ID, then show repeated "connection pool exhausted" messages, which explains why that specific span was slow.`,`This is why teams increasingly attach the same trace ID to log lines emitted during that request. A log line with no trace ID is disconnected from the request that produced it; a log line carrying the trace ID lets you jump directly from "this span was slow" to "here are the exact log lines from that span," instead of scrolling through unrelated log volume from other requests happening at the same time.`,`None of this requires exotic tooling to start. Even a small project benefits from emitting structured logs with consistent fields, a handful of request-rate and error-rate metrics, and a trace ID passed along in a request header, well before it has the traffic volume that would make a full observability platform worth the operational cost.`]},
{id:'building-habit',title:'6. Make observability part of building the feature, not an afterthought',paragraphs:[`It is tempting to treat logging and metrics as something to add after a feature works, but the most useful signals are usually the ones designed in alongside the feature itself, because the author knows at that point which failure modes actually matter. Retrofitting observability after an incident means guessing, after the fact, what data would have helped answer a question nobody anticipated.`,`A reasonable minimum for a new service endpoint is a log line for each request with its outcome, a request-count and error-count metric broken down by route, and trace propagation through any downstream calls it makes. This is a small addition at write time and a large time saver the first time that endpoint misbehaves in production.`,`Finally, treat dashboards and alerts as living artifacts that get revisited, not configured once and forgotten. As the checkout flow gains a new downstream service, the trace, the dashboard, and the alerting rules should be updated to reflect it, the same way tests are updated when behavior changes. An observability setup that reflects last year's architecture answers questions about a system that no longer exists.`]}],exercise:['Explain which of logs, metrics, or traces you would check first for "checkout is slow" and why.','Rewrite the alert "CPU above 80 percent" as a symptom-based alert for checkout.','Describe how a trace ID connects a slow span to the exact log lines that explain it.'],answer:'For "checkout is slow," check metrics first to confirm and quantify the trend, then a trace to find which service span is disproportionately slow. A symptom-based rewrite is something like "checkout error rate above 5 percent for 5 minutes" or "checkout p95 latency above 2 seconds for 5 minutes," since either directly reflects user impact. A trace ID attached to log lines emitted during that request lets you filter logs down to exactly the request whose span was slow.',glossary:[['Log','A discrete, timestamped record of a specific event.'],['Metric','A numeric measurement sampled over time, cheap to graph and threshold.'],['Trace','A reconstructed timeline of one request as it crosses multiple services, made of spans.'],['Alert fatigue','The effect of frequent, low-value alerts training responders to ignore alerts generally.']],sources:[{title:'OpenTelemetry: Observability primer',url:'https://opentelemetry.io/docs/concepts/observability-primer/'},{title:'Prometheus: Overview',url:'https://prometheus.io/docs/introduction/overview/'}]});
guides.push({slug:'infrastructure-as-code',title:'Infrastructure as code: describe your infrastructure instead of clicking it',category:'DevOps & cloud',summary:'Compare declarative configuration with manual console changes, learn the plan/apply workflow, and catch configuration drift before it surprises you.',goals:['Explain declarative infrastructure versus manual changes','Use a plan/apply workflow safely','Detect and handle configuration drift'],sections:[
{id:'manual-problem',title:'1. The problem with clicking buttons in a cloud console',paragraphs:[`Suppose a team provisions a database and a storage bucket by clicking through a cloud provider's web console. It works, and the app runs. Months later, someone needs to recreate the same setup in a second region for redundancy. The only record of what was actually configured is scattered across whoever remembers clicking which settings, since the console itself does not produce a reusable record of the choices made.`,`Manual changes also make audits and rollbacks difficult. If a security setting was quietly changed six weeks ago, nothing systematically recorded who changed it, when, or what it was before, unless the cloud provider's own audit log happens to have retained it and someone thinks to check. Infrastructure as code addresses this by making the configuration itself a reviewable, versioned artifact rather than a sequence of actions nobody wrote down.`,`Infrastructure as code means describing the desired infrastructure — this database, this bucket, these permissions — in a text file, checked into version control the same way application code is, and using a tool to make the real infrastructure match that description. The description becomes the source of truth, and the running infrastructure becomes something derived from it, rather than the other way around.`]},
{id:'declarative',title:'2. Declarative configuration: describe the end state, not the steps',paragraphs:[`Terraform, a widely used infrastructure-as-code tool, is declarative: you write what you want to exist, not a sequence of API calls to create it. A configuration block describing a storage bucket says, in effect, "there should be a bucket with this name and this region," and Terraform works out for itself whether that means creating a new bucket, changing an existing one, or doing nothing because it already matches.`,`This is a meaningfully different mental model from a deployment script that issues imperative commands like "create bucket, then set its region, then set its access policy." An imperative script has no way to know if some of those steps already happened; running it twice might fail on the second run, or might quietly redo work that did not need redoing. A declarative tool compares the description against the real current state and computes only the necessary changes.`,`A small Terraform configuration for one storage bucket shows the pattern: a resource block naming the resource type and a local name, followed by the arguments that describe its desired properties. Nothing here is a command to run; it is closer to a specification that a separate step will reconcile against reality.`],language:'Terraform',code:`resource "aws_s3_bucket" "uploads" {
  bucket = "course-catalog-uploads"
}

resource "aws_s3_bucket_versioning" "uploads" {
  bucket = aws_s3_bucket.uploads.id
  versioning_configuration {
    status = "Enabled"
  }
}`},
{id:'plan-apply',title:'3. Plan before you apply, every time',paragraphs:[`Terraform's core workflow has three steps: write configuration, run a plan, and then apply it. Terraform plan compares the configuration against the last known state and against the real infrastructure, and prints exactly what it intends to change — resources to create, resources to modify in place, and resources it would destroy and recreate — without changing anything yet.`,`Reading the plan output before applying is not optional busywork; it is the main safety check in the whole workflow. A plan that says it will destroy and recreate a database, when the intent was only to rename a tag, is a clear signal to stop and investigate before running apply, since some resource changes cannot be made in place and instead require Terraform to tear down and rebuild the resource, potentially losing its data.`,`Terraform apply then performs exactly the changes the plan described, and only those changes, assuming nothing about the underlying infrastructure changed in the meantime. In a team setting, plans are often reviewed the same way a pull request is reviewed, precisely because the plan output is the clearest available preview of what is about to happen to real infrastructure.`],language:'Terminal',code:`terraform init
terraform plan -out=tfplan
# Read the plan output: what will be created, changed, or destroyed.
terraform apply tfplan`},
{id:'state',title:'4. State is how Terraform knows what already exists',paragraphs:[`Terraform keeps a state file recording what it believes the real infrastructure looks like: which resources exist, and their current attribute values. Plan works by comparing three things — the configuration, the state file, and (for supported providers) the actual infrastructure — not just configuration against reality directly. This is why the state file needs to be treated carefully: if it is lost or corrupted, Terraform loses its record of what it manages, even though the real infrastructure is still there.`,`In a team, the state file should live somewhere shared and lockable, such as a remote backend, rather than on one person's laptop. Two people running apply against the same infrastructure from two different local state files can each make changes the other does not know about, leading to conflicting or duplicated resources.`,`It follows that infrastructure Terraform does not know about is invisible to it. A resource created by hand in the console, even one that matches what the configuration describes, is not automatically recognized as "already applied" — Terraform would try to create a duplicate unless that resource is deliberately imported into the state first.`]},
{id:'drift',title:'5. Configuration drift: when reality quietly diverges from the description',paragraphs:[`Configuration drift happens when the real infrastructure no longer matches what the configuration file says it should be, usually because someone made a manual change directly against the cloud provider rather than through the usual plan/apply workflow. A well-intentioned emergency fix — bumping a database's storage size by hand during an incident — is a common source of drift, especially when nobody goes back afterward to update the configuration to match.`,`Drift is dangerous because it undermines the entire premise of infrastructure as code: the configuration is supposed to be the authoritative description, but after a manual change it is now describing something that no longer exists. The next ordinary apply might then "fix" the manual emergency change by reverting the storage size back down, surprising whoever thought that change was permanent.`,`Running terraform plan on a regular schedule, even when no one intends to apply anything, is a practical way to detect drift early: any unexpected changes in the plan output are a signal that something was changed outside the normal workflow. When drift is found, the two ways to resolve it are updating the configuration to match the new reality if the manual change should stay, or applying the configuration to revert reality back to what was declared if it should not.`]},
{id:'workflow',title:'6. Build a workflow the whole team actually follows',paragraphs:[`Infrastructure as code only delivers its benefits if manual console changes stop being the default way to make infrastructure changes. This is as much a team habit as a tooling choice: agree that changes go through configuration and a reviewed plan, reserve manual console access for genuine emergencies, and treat any emergency manual change as something that must be reconciled back into configuration immediately afterward, not eventually.`,`Store the configuration in the same version control system as application code, and require the same review discipline: a change to a Terraform file goes through a pull request, a plan is generated and attached for reviewers to read, and only an approved plan is applied. This turns infrastructure changes into the same accountable, reviewable process that code changes already go through.`,`Finally, run drift detection regularly and pair it with alerting, so a manual change gets noticed within hours rather than being discovered by accident months later when an unrelated apply reverts it unexpectedly. The goal is not to forbid manual intervention entirely, but to make configuration files, not memory or screenshots, the durable record of what infrastructure is supposed to look like.`]}],exercise:['Explain the difference between an imperative deployment script and a declarative Terraform configuration.','Describe what terraform plan shows you and why you should read it before applying.','Give one example of configuration drift and how you would detect it.'],answer:'An imperative script issues a fixed sequence of commands regardless of current state; a declarative configuration describes the desired end state and lets the tool compute the needed changes. Terraform plan shows exactly what would be created, changed, or destroyed, letting you catch a destructive or unintended change before it happens. A manual storage size bump made during an incident is drift; running terraform plan afterward would show an unexpected diff between the configuration and real infrastructure, revealing it.',glossary:[['Declarative configuration','A description of the desired end state, as opposed to a sequence of steps to reach it.'],['State file','Terraform\'s record of what infrastructure it manages and its last known attributes.'],['Plan','A preview of the exact changes an apply would make, generated without changing anything.'],['Configuration drift','A mismatch between declared configuration and the real infrastructure, usually from a manual change.']],sources:[{title:'Terraform: What is Terraform?',url:'https://developer.hashicorp.com/terraform/intro'},{title:'Terraform: Plan and apply',url:'https://developer.hashicorp.com/terraform/tutorials/cli/plan'}]});
guides.push({slug:'rate-limiting-and-scaling',title:'Rate limiting and scaling APIs: protect a service under real load',category:'DevOps & cloud',summary:'Compare rate limiting algorithms, respond correctly with HTTP 429 and Retry-After, and choose between horizontal and vertical scaling behind a load balancer.',goals:['Compare token bucket and fixed window rate limiting','Respond to overload with 429 and a Retry-After header','Explain horizontal versus vertical scaling with a load balancer'],sections:[
{id:'why-limit',title:'1. Why an API needs to say no sometimes',paragraphs:[`Consider a public API serving course data to several client applications. Under normal use, a handful of requests per second per client keeps the service comfortable. One misbehaving client, perhaps a script stuck in a retry loop with no backoff, can send hundreds of requests per second, consuming resources that were meant to be shared and degrading the experience for every other client, even though none of them did anything wrong.`,`Rate limiting caps how many requests a given client can make in a given time window, and rejects the excess rather than letting the service degrade for everyone. This protects shared infrastructure the same way a queue at a counter protects the person being served: it is not a punishment, it is a way of keeping the system predictable when demand is uneven.`,`Deciding what counts as "one client" matters as much as the numeric limit. Rate limiting by API key or authenticated user identity is precise but only works for authenticated traffic; rate limiting by IP address covers anonymous traffic but can unfairly group many legitimate users behind a shared corporate or mobile carrier IP address into a single bucket.`]},
{id:'algorithms',title:'2. Fixed window versus token bucket',paragraphs:[`A fixed window limiter counts requests within a clock-aligned interval, such as "at most 100 requests between 14:00:00 and 14:01:00," and resets the count to zero at each boundary. It is simple to reason about and implement, but it has a known weakness at the boundary: a client could send 100 requests in the last second of one window and another 100 in the first second of the next, producing 200 requests in roughly two seconds even though the stated limit is 100 per minute.`,`A token bucket instead models a bucket that holds up to some maximum number of tokens, refilling at a steady rate, where each request consumes one token and is rejected only when the bucket is empty. This smooths out the boundary problem because there is no fixed reset instant; a burst is only allowed up to however many tokens have accumulated, and the refill rate governs the sustained average rate over time.`,`Token bucket is the more common choice in production systems because it naturally allows a reasonable short burst — useful for a client that legitimately needs to send a handful of requests at once — while still enforcing a strict sustained rate, whereas fixed window either has to be stricter than intended to avoid the boundary problem or accept the boundary burst as a known limitation.`],language:'Terminal',code:`# Token bucket, conceptually, per client key:
# tokens = min(capacity, tokens + elapsed_seconds * refill_rate)
# if tokens >= 1: tokens -= 1; allow request
# else: reject request`},
{id:'response',title:'3. Tell the client what happened and when to try again',paragraphs:[`When a request is rejected for exceeding a rate limit, the correct HTTP status is 429 Too Many Requests, not a generic 400 or 500. A 500 implies the server itself failed, which invites a client to treat it as a bug to report, while a 429 correctly tells the client and any automated retry logic that the request was understood but intentionally throttled.`,`A 429 response should include a Retry-After header indicating how long the client should wait before trying again, either as a number of seconds or an HTTP date. This turns a vague rejection into an actionable instruction: a well-behaved client reads that header and waits the specified time rather than immediately retrying and hitting the same limit again.`,`It is also good practice to expose the client's current limit status proactively, commonly through headers such as X-RateLimit-Remaining and X-RateLimit-Reset, so a client can throttle itself before ever receiving a 429. A client that only discovers the limit by being rejected has already wasted a request and possibly triggered unnecessary alarm in its own error handling.`],language:'HTTP',code:`HTTP/1.1 429 Too Many Requests
Retry-After: 30
X-RateLimit-Limit: 100
X-RateLimit-Remaining: 0
X-RateLimit-Reset: 1732550460
Content-Type: application/json

{"error":"rate_limited","message":"Too many requests, retry after 30 seconds"}`},
{id:'vertical',title:'4. Vertical scaling: a bigger machine has a ceiling',paragraphs:[`When a single server starts struggling under load, the most immediate fix is often vertical scaling: moving the same application to a machine with more CPU, memory, or faster disks. It requires no application changes and can be done quickly, which makes it a reasonable first response to a sudden, moderate increase in traffic.`,`Vertical scaling has two real limits. First, there is a hardware ceiling — eventually there is no bigger machine easily available, or the largest available machine is prohibitively expensive relative to the traffic it serves. Second, a single bigger machine is still a single point of failure: if that one machine crashes or needs maintenance, the entire service goes down, regardless of how much capacity it has.`,`Vertical scaling is best treated as a stopgap or a fit for genuinely small, low-risk workloads, not as a long-term strategy for a service that needs to stay available and handle continued growth. It buys time; it does not remove the eventual need to think about running more than one instance.`]},
{id:'horizontal',title:'5. Horizontal scaling behind a load balancer',paragraphs:[`Horizontal scaling runs multiple instances of the same service, on separate machines, and relies on a load balancer in front of them to distribute incoming requests across the instances. If one instance fails, the load balancer stops sending it traffic and the remaining instances absorb the load, so a single machine failure no longer takes the whole service down. Adding capacity means adding another instance, which has no hard ceiling the way a single machine's hardware does.`,`Horizontal scaling comes with a real requirement: the application must be able to run as multiple simultaneous, interchangeable instances, which usually means it cannot keep important state only in the memory of one process. A rate limiter counting requests in a single instance's local memory, for example, would let a client get a separate quota per instance simply by having requests routed to different instances, defeating the limit; the counters need to live in a shared store such as Redis that every instance reads and writes.`,`This is also where the load balancer's own health checks matter: it should periodically verify each instance is actually healthy, not just reachable, and stop routing to an instance that is up but broken, the same way a deploy pipeline's own smoke check verifies a release actually works rather than just having started.`],language:'Terminal',code:`# Conceptual load balancer health check
# GET http://instance:3000/healthz every 10s
# 3 consecutive failures -> remove instance from rotation
# 2 consecutive successes -> add instance back to rotation`},
{id:'choosing',title:'6. Choosing and combining both approaches deliberately',paragraphs:[`In practice, most growing services use both: vertical scaling to give each instance a reasonable amount of resources so it is not chronically starved, and horizontal scaling to add redundancy and handle traffic beyond what any single instance can serve. Neither is strictly better in isolation; they answer different questions, respectively "how much can one instance handle" and "how many instances do we need, and can we survive losing one."`,`Rate limiting and scaling also work together rather than substituting for each other. Rate limiting protects the service from a single misbehaving or malicious client regardless of how much capacity exists; scaling increases the capacity available to legitimate, well-behaved traffic. A service that scales generously but has no rate limiting can still be degraded for everyone by one client sending an unreasonable volume of requests.`,`A reasonable order of operations for a growing API is to add sensible rate limits and correct 429 handling early, since they are cheap and protect against a real and common failure mode, and to add horizontal scaling with a load balancer once traffic or reliability requirements genuinely exceed what a single well-sized instance can provide, moving shared state such as rate limit counters and sessions into a shared store at that same point.`]}],exercise:['Explain the boundary weakness of fixed window rate limiting that token bucket avoids.','Write the two HTTP headers a client needs to know when to retry after a 429.','Explain why a rate limit counter cannot safely live only in one instance\'s local memory once you scale horizontally.'],answer:'Fixed window can allow roughly double the intended rate across a window boundary, since a client can exhaust one window right at its end and the next window right at its start; token bucket has no fixed reset instant, so this burst does not occur. A 429 response should include Retry-After, and often X-RateLimit-Reset, to tell the client when to try again. A per-instance local counter gives each instance its own quota, so a client routed across instances by the load balancer effectively gets a multiple of the intended limit unless the counter is shared, for example in Redis.',glossary:[['Rate limiting','Restricting how many requests a client may make in a given time period.'],['Token bucket','A rate limiting algorithm that allows bursts up to an accumulated token count while enforcing a steady refill rate.'],['Retry-After','An HTTP header telling a client how long to wait before retrying a request.'],['Horizontal scaling','Adding more instances of a service behind a load balancer, rather than enlarging one instance.']],sources:[{title:'MDN: 429 Too Many Requests',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/429'},{title:'NGINX: Rate limiting with NGINX',url:'https://www.nginx.com/blog/rate-limiting-nginx/'}]});
guides.push({slug:'data-structures-essentials',title:'Data structures essentials: pick the right container for the job',category:'CS fundamentals & data',summary:'Match arrays, linked lists, stacks, queues, trees, and hash maps to the concrete task each one actually solves.',goals:['Explain what array, linked list, stack, queue, tree, and hash map each optimize for','Recognize which operation in a real feature should drive the choice of structure','Diagnose a slow feature as a structure mismatch rather than just needing more code'],sections:[
{id:'task-first',title:'1. Let the task choose the structure',paragraphs:[`Imagine a small course-registration app with three needs: show enrolled students in the order they signed up, undo the last edit an admin made, and instantly look up one student by ID when a support ticket comes in. A beginner reaches for one generic list for everything and is surprised later when the lookup feature is slow at scale, or when undo requires ugly workarounds. Each of those three needs is actually a different question about what a data structure must be good at.`,`A data structure is an agreement between your code and the machine about how values are laid out in memory and which operations are cheap as a result. Some structures make reading by position cheap, some make inserting at one end cheap, some make finding something by name cheap, and none make everything equally cheap at once. Picking one means accepting its trade-offs, not finding a structure with no trade-offs.`,`This guide walks through arrays, linked lists, stacks, queues, trees, and hash maps using that course-registration app as the running example. By the end, you should be able to map "show in enrollment order," "undo last edit," and "find by ID" each to a specific structure, and explain why the other structures would be a worse fit for that particular job.`]},
{id:'array-vs-linked',title:'2. Arrays and linked lists: contiguous memory versus scattered nodes',paragraphs:[`An array stores its elements in one contiguous block of memory, so the computer can jump straight to element k by computing an offset from the start; that is why reading by index is fast regardless of array size. Adding an element at the end is usually cheap too. But inserting or removing in the middle means physically shifting every element after that position, which gets more expensive as the array grows.`,`A linked list stores each value in its own node, alongside a pointer to the next node. Inserting or removing at a position you already have a reference to is cheap, because only a couple of pointers change and nothing needs to shift. The cost moves elsewhere: to reach the tenth node you must walk from the first node counting as you go, so reading by position is slow compared to an array.`,`For the enrollment list, students are displayed in signup order and rarely inserted into the middle, so a plain array (or a language's dynamic array, like a Python list or a JavaScript array) is the right default. A feature that constantly inserts and removes items from one end, such as a message queue buffer, leans toward a linked-list-style structure, though in many languages a deque built for that purpose is the more practical choice than a hand-rolled linked list.`]},
{id:'stacks-queues',title:'3. Stacks and queues: the order you take items out encodes meaning',paragraphs:[`A stack removes the most recently added item first, known as last-in-first-out. This is exactly the shape of an undo feature: every edit an admin makes gets pushed onto a stack, and pressing undo pops the most recent one off and reverses it. The moment you need "reverse the last action taken," a stack is almost always the correct structure, because the order it enforces matches the order the feature needs.`,`A queue removes the earliest added item first, known as first-in-first-out. A notification queue or a print queue fits this shape: the first ticket submitted should be the first one handled, not the most recent. Note that using a plain array as a queue by removing from the front is often slow, since removing the first element shifts everything else down; a structure purpose-built as a deque avoids that cost.`,`Choosing between them comes down to one question: which item should come out first, the one that just went in, or the one that has been waiting longest? For the registration app, undo is a stack because it reverses your most recent action; a waitlist for a full course is a queue because the student who has been waiting longest should get the next open seat.`],language:'Python 3',code:`edit_history = []          # stack: use append/pop from the end
edit_history.append("added Priya to CS101")
edit_history.append("removed Sam from CS101")
last_action = edit_history.pop()   # undoes "removed Sam" first

from collections import deque
waitlist = deque()        # queue: use append/popleft
waitlist.append("Priya")
waitlist.append("Sam")
next_seat = waitlist.popleft()     # offers the seat to Priya first`},
{id:'trees',title:'4. Trees: represent hierarchy directly instead of faking it in a flat list',paragraphs:[`A course catalog is naturally hierarchical: a department contains categories, categories contain courses, and some courses have prerequisite chains. Storing that in one flat list means every search has to check items that are obviously irrelevant, like scanning every course in the catalog to find one biology elective. A tree, where each node holds a value and pointers to its children, represents that hierarchy directly instead of reconstructing it from flags on flat records.`,`A binary search tree is a specific, useful case: each node's left subtree holds smaller values and its right subtree holds larger ones, so looking up a value means repeatedly choosing left or right and discarding half of the remaining nodes at each step. On a reasonably balanced tree that makes lookup, insert, and delete all proportional to the height of the tree rather than the number of items in it. A tree that grows lopsided, however, degrades toward the same worst case as walking a linked list, which is why balanced variants exist in real libraries.`,`Trees show up constantly outside search: a file system's folders and files, a webpage's DOM, and a comment section's replies-to-replies are all trees. Recursion is the natural way to process them, since "process this node, then process each of its children the same way" is a direct translation of the tree's own shape.`]},
{id:'hash-maps',title:'5. Hash maps: pay a small structural cost to buy near-instant lookup',paragraphs:[`A hash map (dictionary in Python, object or Map in JavaScript) associates a key with a value by running the key through a hash function that produces an index into an internal array, then storing the value at that index. For the registration app, mapping a student ID directly to that student's record means a support lookup does not need to scan every enrolled student; on average it goes straight to the record in constant time.`,`This speed depends on the hash function spreading keys out evenly and on collisions, cases where two different keys hash to the same slot, being handled and staying rare. That is why hash map keys are normally required to be immutable and hashable: a key that could change after being stored would corrupt the structure's own bookkeeping. The average-case constant-time lookup is a strong guarantee in practice, but the worst case, many keys colliding, is slower, so a hash map is not a substitute for a data model that actually prevents duplicate or malformed keys.`,`Compare this to the array and tree options above: a hash map gives up any meaningful order among its keys in exchange for fast lookup by key. If the registration app needs both "list students in signup order" and "find one student instantly by ID," those are two different needs and can justify keeping two structures, an ordered array and a hash map index, referring to the same underlying student records.`],language:'Python 3',code:`students_by_id = {}
def enroll(student_id, name):
    students_by_id[student_id] = {"name": name, "courses": []}

enroll("S1042", "Priya Nair")
record = students_by_id.get("S1042")   # O(1) average lookup, no scan needed`},
{id:'choose',title:'6. Choose deliberately, then let the symptom confirm the choice',paragraphs:[`Back to the three original needs: enrollment order is an array, undo is a stack, and lookup-by-ID is a hash map; a nested course catalog would add a tree on top. Nothing prevents the same underlying data from being represented by more than one structure at once, such as an ordered array of students plus a hash map that indexes into it by ID, as long as you keep both in sync when a student is added or removed.`,`This groundwork also sets up how to reason about performance formally, which the next guide on algorithms and Big-O builds on directly: the structure you choose here determines whether a given operation is fast or slow before you have written a single loop.`,`Use this as a debugging heuristic going forward: if you catch yourself scanning an entire list just to check whether something exists, that is a signal you probably want a hash map alongside it. If you catch yourself repeatedly inserting into the middle of a large array and feeling the slowdown, that is a signal to reconsider whether the data actually needs that ordering, or whether a different structure fits the real access pattern better.`]}],exercise:['Name the structure best suited to each: enrollment order, undo history, lookup by student ID.','Explain why inserting into the middle of an array costs more than inserting into the middle of a linked list.','Describe one feature in an app you use that behaves like a queue rather than a stack.'],answer:'Enrollment order fits an array, undo history fits a stack, and lookup by ID fits a hash map. An array insert in the middle must shift every following element to keep the block contiguous, while a linked list only rewires two pointers at the insertion point. A support ticket queue, where the oldest ticket is handled first, behaves like a queue rather than a stack.',glossary:[['Array','A structure storing elements contiguously in memory, giving fast lookup by index.'],['Linked list','A structure of nodes each pointing to the next, giving fast insertion at a known position.'],['Stack','A last-in-first-out structure, useful for reversing the most recent action.'],['Hash map','A structure mapping keys to values through a hash function, giving fast average-case lookup by key.']],sources:[{title:'Python: Data structures',url:'https://docs.python.org/3/tutorial/datastructures.html'},{title:'MDN: Indexed collections',url:'https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Indexed_collections'}]});
guides.push({slug:'algorithms-and-big-o',title:'Algorithms and Big-O: reason about performance before you measure it',category:'CS fundamentals & data',summary:'Read time and space complexity directly off code, catch a hidden quadratic loop, and compare two honest solutions to the same search problem.',goals:['Explain what Big-O actually describes and what it deliberately ignores','Read a loop and its nesting to predict how cost grows with input size','Compare a linear scan against binary search and know when each is justified'],sections:[
{id:'what-big-o-answers',title:'1. Big-O answers "how does cost grow", not "how many seconds"',paragraphs:[`A common misunderstanding is treating Big-O as a stopwatch reading. It is not: it describes how the running time or memory use of an operation scales as the input size, usually called n, grows, while deliberately ignoring constant factors, the specific hardware, and the programming language. A function classified as O(n) does not tell you it takes any particular number of seconds; it tells you that doubling the input roughly doubles the work.`,`Concretely, a function that takes 2 seconds on a fast laptop and 20 seconds on an old phone for the exact same input still has the exact same Big-O classification, because the classification describes the shape of the growth curve as n increases, not a specific measured duration on one machine. This is precisely why Big-O is useful before you can even run the code: it is a property of the algorithm's structure, not of any single measurement.`,`Three growth shapes are worth memorizing first because they cover most everyday code: constant, where cost does not grow with n at all, such as reading students_by_id["S1042"] from a hash map; linear, where cost grows proportionally to n, such as scanning every name in an unsorted class list once; and quadratic, where cost grows proportionally to n squared, which the next two sections focus on.`]},
{id:'reading-complexity',title:'2. Read complexity directly off the code',paragraphs:[`A simple counting rule gets you most of the way there: statements that run once regardless of input count as constant. A loop that runs n times multiplies whatever is inside it by n. A loop nested inside another loop, where the inner one also runs roughly n times, multiplies again, giving n times n, or n squared.`,`Apply that rule to a function that checks whether any two students in a class share the same name by comparing every pair: the outer loop runs n times, and for each outer iteration the inner loop also runs roughly n times, so the total number of comparisons grows like n squared, which is quadratic.`,`Space complexity uses the same counting idea applied to memory instead of time: count how much additional memory a function allocates relative to its input, not the input itself. Sorting a list in place and returning it uses O(1) extra space; building and returning a brand-new sorted copy of that same list uses O(n) extra space, because the copy itself grows with the input.`],language:'Python 3',code:`def has_duplicate_name(names):
    for i in range(len(names)):
        for j in range(len(names)):
            if i != j and names[i] == names[j]:
                return True
    return False
# Outer loop: n iterations. Inner loop: n iterations each time. Total: O(n^2).`},
{id:'hidden-quadratic',title:'3. Spot the quadratic hiding inside a helpful-looking function',paragraphs:[`A function that removes duplicate student IDs from a list often looks perfectly reasonable at first glance: for each ID, check whether it is already in the results list, and only append it if it is not. On a roster of 20 students this feels instant. On an export job processing 20,000 IDs, the same function noticeably slows the whole pipeline down, and it is not obvious why from reading the code casually.`,`The reason is that the "in results" check itself has to scan the results list from the start, and results can hold up to n items by the time you are near the end of the input; so the loop runs n times, and each of those n iterations can do up to n work checking membership, giving O(n^2) overall even though there is only one loop written in the source.`,`The fix is not "write less code," it is changing which structure the membership check consults: swap the results list for a set used purely to test membership. Checking membership in a set is O(1) on average, so the same loop over n items now does O(1) work per iteration instead of up to O(n), making the whole function O(n) instead of O(n^2). This is the previous guide's lesson about hash maps and sets applied directly to a performance problem.`],language:'Python 3',code:`def dedupe_slow(ids):
    results = []
    for student_id in ids:
        if student_id not in results:   # scans up to len(results) each call
            results.append(student_id)
    return results

def dedupe_fast(ids):
    seen = set()
    results = []
    for student_id in ids:
        if student_id not in seen:      # O(1) average check
            seen.add(student_id)
            results.append(student_id)
    return results`},
{id:'compare-search',title:'4. Compare two honest solutions to the same search problem',paragraphs:[`Suppose the task is finding one student by name in a list of exam scores. If the list is in no particular order, the only correct approach is checking names one at a time until you find a match or reach the end, which in the worst case touches every element: a linear scan, O(n).`,`If the list is already sorted by name, binary search can do much better: compare the target to the middle element, and depending on whether it is smaller or larger, discard the half of the list that cannot contain it, repeating on the remaining half. Each comparison eliminates roughly half of what is left, so the number of comparisons needed grows like log base two of n rather than n itself, which is dramatically slower-growing as n gets large.`,`The catch is the precondition: binary search only works because the list is already sorted, and sorting an unsorted list costs O(n log n) up front. A single one-off lookup on unsorted data does not justify sorting it first, since the sort itself costs more than the linear scan would have. Repeated lookups against the same, rarely-changing data is what actually justifies paying the sorting cost once to get the faster search on every later query.`],language:'Python 3',code:`def linear_search(names, target):
    for i, name in enumerate(names):
        if name == target:
            return i
    return -1

def binary_search(sorted_names, target):
    lo, hi = 0, len(sorted_names) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_names[mid] == target:
            return mid
        if sorted_names[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1`},
{id:'time-space-tradeoff',title:'5. Trade time for space, deliberately and with awareness of the cost',paragraphs:[`The two-sum problem, finding whether any pair of numbers in a list adds up to a target, has a naive nested-loop solution that checks every pair, costing O(n^2) time but only O(1) extra memory. A faster solution walks the list once, and for each number checks whether the complement it needs has already been seen in a hash set, adding the current number to that set as it goes; this costs O(n) time but now needs O(n) extra memory to hold the set.`,`That memory is not free, and on a constrained device or for a genuinely huge input, an algorithm that trades time for O(n) extra space can run into a memory ceiling that the slower O(1)-space version never would. Choosing the faster algorithm without checking what it costs in memory is itself a version of the same mistake as ignoring time complexity in the first place.`,`This is the same trade-off from the data-structures guide, made explicit: choosing a hash set for fast average lookup instead of scanning a list is literally choosing to spend memory in order to buy speed, and that choice should be made on purpose rather than by accident.`]},
{id:'verify',title:'6. Reason first, then verify with an actual measurement',paragraphs:[`Big-O predicts a trend, not a guarantee about any specific run. Measuring realistic input sizes afterward confirms the prediction and catches constant-factor surprises that the notation deliberately ignores, such as an O(n) function that touches a slow disk or network on every iteration turning out slower in practice than an O(n log n) function that does all of its work in memory.`,`A practical habit before optimizing anything: write down the input sizes the feature will actually see in production. An O(n^2) function might be completely fine if n never exceeds 50, and rewriting it anyway spends effort that would be better used somewhere the input size is actually large.`,`Recap the whole habit: identify what work happens inside each loop, count how loops nest, check whether a lookup you assumed was instant is secretly scanning a list, and only decide something needs to change once you can name which of those is actually the bottleneck.`]}],exercise:['Classify this loop: for i in range(n): for j in range(n): print(i, j).','Explain why checking "x in a_list" repeatedly inside a loop can silently create an O(n^2) function.','Say why sorting first is not worth it for a single one-off search on unsorted data.'],answer:'The nested loop is O(n^2), since the inner loop runs n times for each of the n outer iterations. Checking "x in a_list" scans up to n elements each call, so doing that inside a loop that also runs n times multiplies to O(n^2), even though only one explicit loop is visible. Sorting costs O(n log n) up front, which is more expensive than the O(n) linear scan it was meant to avoid for a single lookup.',glossary:[['Big-O notation','A description of how cost grows with input size, ignoring constant factors and hardware.'],['Quadratic time','Cost that grows proportionally to the square of the input size, often from nested loops.'],['Binary search','A search algorithm that halves the remaining search space each step, requiring sorted data.'],['Space complexity','How much additional memory an algorithm uses relative to its input size.']],sources:[{title:'Python Wiki: Time Complexity',url:'https://wiki.python.org/moin/TimeComplexity'},{title:'Wikipedia: Big O notation',url:'https://en.wikipedia.org/wiki/Big_O_notation'}]});
guides.push({slug:'regular-expressions-practical',title:'Regular expressions: pattern matching without the mystery',category:'CS fundamentals & data',summary:'Build a regex piece by piece, understand greedy versus lazy matching, and recognize when a regex is the wrong tool for the job.',goals:['Build a regex from literals up through character classes, quantifiers, and groups','Explain the difference between greedy and lazy matching with a concrete failure case','Recognize when a task like parsing nested HTML needs a real parser, not a regex'],sections:[
{id:'what-is-regex',title:'1. A regex is a tiny pattern language, not magic',paragraphs:[`A regular expression, or regex, is a compact way of describing a set of matching strings. It is used for two related jobs: validation, does this string look like a course code, and extraction, pull every hashtag out of this post. This guide uses a running example: a system that validates course codes like "CS101" and "MATH204".`,`A regex engine reads text left to right, trying to line the pattern up against the string. This makes regex excellent at flat, locally recognizable patterns, but it is deliberately not a full grammar or parser, a distinction that section six comes back to when a regex stops being the right tool.`,`Keep a small table of test cases as you build the pattern: valid strings "CS101" and "MATH204", and invalid strings "cs101" (wrong case), "CS10" (missing a digit), and "CS-101" (an extra dash). Checking the pattern against this table after every change is how you catch a rule that is too loose or too strict before it reaches real data.`]},
{id:'literals-classes',title:'2. Build up from literal characters to character classes',paragraphs:[`A literal character matches only itself: the pattern piece "CS" matches a capital C immediately followed by a capital S, nothing else. A character class, written in square brackets, matches any single character from a set or range: [A-Z] matches one uppercase letter, and [0-9] matches one digit. The course-code example needs two uppercase letters followed by three digits, so an early, verbose version could be written out one character position at a time.`,`Writing "CS101" fully spelled out as [A-Z][A-Z][0-9][0-9][0-9] (before introducing quantifiers in the next section) is intentionally repetitive here, just to make clear that each square-bracket group matches exactly one character position, no more.`,`Outside character classes, symbols like the dot, asterisk, and plus are special rather than literal, so matching an actual dot, such as in a version string like "v1.2", requires escaping it as \\.  A pattern like ^v[0-9]+\\.[0-9]+$ matches "v1.2" while treating the dot as a literal character rather than as "match any character," which the unescaped dot would do.`]},
{id:'quantifiers-groups',title:'3. Quantifiers repeat, groups organize',paragraphs:[`Quantifiers say how many times the preceding piece may repeat: * means zero or more, + means one or more, ? means zero or one, and {n,m} means between n and m repeats. Rewriting the course-code pattern with a quantifier gives ^[A-Z]{2,4}[0-9]{3}$, which now also accepts a four-letter department code like "MATH" alongside the two-letter "CS".`,`Parentheses create a group, which both organizes part of a pattern and, by default, captures the text it matched so calling code can pull it out afterward. Splitting the department from the number as ^([A-Z]{2,4})([0-9]{3})$ means a program can read group one as the department ("MATH") and group two as the number ("204") separately, instead of re-parsing the whole matched string.`,`A non-capturing group, written (?:...), groups pieces of a pattern together without producing an extra captured value, and alternation with | inside a group offers a choice between alternatives. Extending the course-code pattern to optionally allow a lab section suffix looks like ^([A-Z]{2,4})([0-9]{3})(?:L)?$, matching both "CS101" and "CS101L" while only capturing the department and number, not the optional L.`],language:'Python 3',code:`import re
pattern = r'^([A-Z]{2,4})([0-9]{3})(?:L)?$'
match = re.match(pattern, "MATH204L")
if match:
    dept, number = match.group(1), match.group(2)
    print(dept, number)   # MATH 204`},
{id:'greedy-lazy',title:'4. Greedy grabs as much as possible; lazy takes as little as possible',paragraphs:[`Quantifiers are greedy by default: * and + try to match as much text as they possibly can while still allowing the rest of the pattern to succeed. Matching ".*" against a line containing two separate quoted phrases, like "first" and "second" in one sentence, can accidentally span from the first opening quote all the way to the last closing quote, swallowing both phrases and everything between them into one match.`,`Adding a ? after a quantifier makes it lazy instead: .*? stops as soon as the rest of the pattern can succeed, matching each quoted phrase separately rather than gobbling up everything in between. On the same two-quotes-in-one-line example, ".*?" correctly produces two separate matches where ".*" incorrectly produces one oversized match spanning both.`,`This distinction matters most exactly where it is easy to miss: patterns like <.*> against a line of HTML-like markup with more than one tag will span from the first "<" to the very last ">", while <.*?> stops at the nearest ">". Whenever a pattern's correctness depends on greedy versus lazy, test it against the specific string that would expose the difference, rather than assuming the shorter-looking version is safe.`],language:'Python 3',code:`import re
text = '"first" and "second"'
print(re.findall(r'".*"', text))    # ['"first" and "second"']  (greedy: one big match)
print(re.findall(r'".*?"', text))   # ['"first"', '"second"']   (lazy: two separate matches)`},
{id:'test-iterate',title:'5. Test a regex the way you test any other code',paragraphs:[`Build a pattern incrementally against the table of valid and invalid examples introduced in section one, checking after every change that no valid string is rejected and no invalid string is accepted. When a bug turns up, such as a pattern that lets through "CS10" (only two digits), add that exact string to the table permanently so the same mistake cannot silently return later.`,`Use a regex tester or a language's interactive shell to iterate rather than editing a pattern buried inside a full application and re-running the whole program each time; in real code, named groups such as (?P<dept>[A-Z]{2,4}) make the extracted pieces self-documenting instead of relying on a caller remembering that group one means department.`,`Once a pattern is more than a few characters of alternation and quantifiers, keep it short, add a short comment explaining what it validates, and write an actual unit test for the validation function in the codebase, not just an ad hoc check in a scratch console that nobody will run again.`]},
{id:'when-not-regex',title:'6. Know when a regex is the wrong tool',paragraphs:[`Regex is built for flat, locally recognizable patterns; it has no built-in way to count how deep it currently is inside a nested structure. The classic failure case is nested HTML or XML: a document like a div containing a paragraph has tags nested inside other tags, and there is no fixed number of characters between an opening tag and its matching closing tag that a regex could rely on.`,`A pattern like <(\\w+)>.*</\\1> looks like it might match an opening tag and its corresponding closing tag, and it even works on a single flat example. It breaks down as soon as tags nest, such as <div><p>text</p></div>, because the regex has no memory of "how many tags deep am I right now" to know which closing tag actually matches which opening tag. A real HTML or XML parser solves this by tracking nesting explicitly with a stack as it reads, which is exactly the bookkeeping a regex engine does not perform.`,`The practical rule of thumb: reach for a regex for flat patterns like course codes, simple validation, or pulling short tokens out of a line of text, and reach for a real parser, an HTML parser library, a JSON parser, or a language's own parser, for structured or nested formats. Trying to stretch a regex to cover nesting usually produces a pattern that works on every example you tried and breaks on the first one you did not.`]}],exercise:['Write a character class matching a single lowercase letter.','Explain, using a two-quotes example, why ".*" and ".*?" can produce different matches on the same line.','Explain in one sentence why a regex struggles to match nested HTML tags correctly.'],answer:'A single lowercase letter is matched by the character class [a-z]. On a line with two separate quoted phrases, the greedy ".*" spans from the first opening quote to the very last closing quote, swallowing both phrases, while the lazy ".*?" stops at the nearest closing quote, correctly matching each phrase separately. Regex struggles with nested HTML because it has no mechanism for tracking how deep the current position is inside nested tags, which a real parser tracks explicitly with a stack.',glossary:[['Character class','A bracketed set or range that matches any one character from it, like [A-Z].'],['Quantifier','A symbol like *, +, ?, or {n,m} controlling how many times the previous piece may repeat.'],['Capturing group','A parenthesized part of a pattern whose matched text can be extracted afterward.'],['Greedy versus lazy','Whether a quantifier matches as much text as possible or as little as possible.']],sources:[{title:'MDN: Regular expressions',url:'https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Regular_expressions'},{title:'Python: re module',url:'https://docs.python.org/3/library/re.html'}]});
guides.push({slug:'git-internals-and-plumbing',title:'Git internals: what a commit, tree, and blob actually are',category:'CS fundamentals & data',summary:'Open up the .git object model, see a branch as a movable pointer, and use plumbing commands to view the objects directly.',goals:['Explain what a blob, tree, and commit object each store','Explain why a branch is just a movable pointer to a commit hash','Use git cat-file and git hash-object to view real objects in a repository'],sections:[
{id:'object-database',title:'1. .git is a content-addressed database, not a diff log',paragraphs:[`A common assumption is that Git stores a chain of diffs between versions of a file. It does not: every commit refers to a complete snapshot of the project's directory structure at that point, and every object Git stores is keyed by the hash of its own content rather than by a filename or a position in history. This is a deeper, lower-level companion to the everyday workflow covered in the git-team-workflow lesson; here the goal is to see what staging, committing, and branching actually create underneath.`,`Because objects are addressed by the hash of their content, identical content anywhere in the project's history is stored exactly once. Two files with the same bytes, even in unrelated commits or unrelated paths, point at the very same stored object; this is why Git repositories often take up far less space than naively storing every version of every file would suggest.`,`Three object types matter for this guide: the blob, the tree, and the commit. The rest of this guide traces a small repository with a single tracked file through each of these object types, so the model stops being an abstract diagram and becomes something you can point at inside .git/objects.`]},
{id:'blobs',title:'2. A blob is a file content with no name attached',paragraphs:[`A blob object stores only the raw bytes of a file's content, compressed, with no filename, path, or permissions baked into it. That information is not the blob's job; it lives in a tree, covered next. This means two files named notes.txt and copy.txt containing identical text are, at the object level, the exact same blob referenced from two different tree entries.`,`Hashing is pure: git hash-object computes the identifying hash for content before that content is even added to a repository, since the hash depends only on the bytes themselves, not on any repository state. This is a useful thing to see directly, because it makes clear that a blob's identity is a property of its content alone.`,`This separation is also why renaming a file whose content is unchanged costs almost nothing internally: the underlying blob does not change at all, only the tree entry that pairs a name with that blob's hash needs to be rewritten.`],language:'Terminal',code:`echo "hello library" > notes.txt
git hash-object notes.txt
# prints a 40-character SHA-1 identifying that exact content,
# computed even though notes.txt is not yet tracked by any commit`},
{id:'trees',title:'3. A tree maps names and modes onto blobs (and other trees)',paragraphs:[`A tree object is a list of entries, and each entry pairs a name and a file mode with a pointer to either a blob (a file) or another tree (a subdirectory). This is literally Git's representation of a directory listing at one point in history: not a filesystem folder itself, but a small, hashable object describing what that folder contained.`,`Reading a tree object with git cat-file -p shows exactly this: a mode, a type (blob or tree), a hash, and a name, one line per entry, which is the same information ls -la shows about a real directory, just stored as a hashable Git object instead of live filesystem metadata.`,`A nested directory is simply a tree whose entries point at other tree objects, recursively, mirroring the folder structure on disk. Git does not need a separate concept for "directory" beyond one tree object referencing another; the recursive structure of trees pointing at trees is the whole mechanism.`],language:'Terminal',code:`git add notes.txt
git commit -m "add notes"
git cat-file -p HEAD^{tree}
# 100644 blob 3b18e512dba79e4c8300dd08aeb37f8e728b8dad  notes.txt`},
{id:'commits',title:'4. A commit points to one tree and remembers where it came from',paragraphs:[`A commit object records a single tree hash, the complete snapshot at that point, zero or more parent commit hashes, author and committer metadata with timestamps, and a message. A first commit in a repository has no parent at all, and a merge commit is distinguished by having two or more parents rather than one.`,`Because a commit points to a whole tree rather than a diff, answering "what did this file look like at commit X" means walking commit to tree to subtree to blob, following pointers down to the exact content, not replaying a chain of patches from the beginning of history. The differences shown by git diff or git log -p are computed on demand by comparing two snapshots against each other; they are convenient views, not what is actually stored.`,`Reading a commit object directly with git cat-file -p shows these fields plainly: the tree line, zero or more parent lines, the author and committer lines, and the message, in that order, confirming that a commit is really just a small, structured pointer plus metadata, not a container that holds every version of every file.`],language:'Terminal',code:`git cat-file -p HEAD
# tree 4b825dc642cb6eb9a060e54bf8d69288fbee4904
# author Ada <ada@example.com> 1690000000 +0000
# committer Ada <ada@example.com> 1690000000 +0000
#
# add notes`},
{id:'branches-are-pointers',title:'5. A branch is a movable label on a commit hash',paragraphs:[`A branch, stored under .git/refs/heads, is literally a small file containing one 40-character commit hash and nothing more. Running git commit while a branch is checked out creates a new commit object and then rewrites that one small file to point at the new commit's hash; that rewrite is what "the branch moved forward" actually means at the object level.`,`HEAD adds one more level of indirection: it is normally a file containing a line like "ref: refs/heads/main", meaning HEAD always refers to whatever commit main currently points at, whatever that happens to be. Checking out a different branch changes what HEAD points to; checking out a specific commit hash directly, rather than a branch name, points HEAD straight at that commit with no branch label attached, a state usually called detached HEAD.`,`This model explains two things that otherwise feel like magic: creating a branch is essentially instant because it copies no files, only writes a 40-character hash into one new small ref file, and deleting a branch never deletes the commits it pointed to, as long as some other reference, or your own memory of the hash, still points at them.`]},
{id:'plumbing',title:'6. See the objects yourself with plumbing commands',paragraphs:[`Everyday commands like git commit, git branch, and git log are called "porcelain," a convenient, user-facing layer. Underneath, "plumbing" commands manipulate the objects described above directly, and running a few of them once is worth far more than re-reading a diagram of the object model.`,`git hash-object -w writes a new blob and prints its hash; git cat-file -p prints the readable content of any object given its hash, whether that object is a blob, a tree, or a commit; git ls-tree lists a tree's entries directly; and git rev-parse HEAD prints the current commit's hash so you have something concrete to feed into the other commands.`,`The read-only commands, cat-file -p, ls-tree, and rev-parse, are safe to run against any repository you do not intend to change. The write commands, hash-object -w, mktree, and commit-tree, actually create new objects and can move refs if combined incorrectly, so practice those in a disposable repository created just for this exercise rather than a project you care about.`],language:'Terminal',code:`git rev-parse HEAD
git ls-tree HEAD
git cat-file -p $(git rev-parse HEAD)
git cat-file -p $(git rev-parse HEAD^{tree})`}],exercise:['Explain what changes in .git when you rename a file whose content is unchanged.','Run git cat-file -p on your current HEAD commit and identify its tree line.','Explain in one sentence why deleting a branch does not delete its commits.'],answer:'Renaming a file with unchanged content changes only the tree entry pairing a name with a blob hash; the blob itself, and its hash, stay exactly the same. git cat-file -p HEAD prints a tree line naming the hash of the complete snapshot that commit points to, among its parent, author, committer, and message lines. Deleting a branch only removes the small ref file holding its commit hash; the commit objects themselves remain in .git/objects until nothing references them and they are garbage collected.',glossary:[['Blob','A Git object storing raw file content with no filename attached.'],['Tree object','A Git object listing names, modes, and pointers to blobs or other trees.'],['Commit object','A Git object pointing to one tree, its parent commits, and metadata.'],['Ref','A named pointer, like a branch, stored as a file containing a commit hash.']],sources:[{title:'Git Book: Git Objects',url:'https://git-scm.com/book/en/v2/Git-Internals-Git-Objects'},{title:'Git: git-cat-file',url:'https://git-scm.com/docs/git-cat-file'}]});
guides.push({slug:'free-developer-resources-communities',title:'Free developer resources: learning platforms, open source, and communities worth your time',category:'CS fundamentals & data',summary:'Evaluate free learning platforms, make a safe first open-source contribution, and vet a community for signal versus noise.',goals:['Judge a free learning platform by output and currency, not just price','Prepare and scope a first open-source pull request safely','Tell a genuinely useful developer community apart from a noisy one'],sections:[
{id:'evaluate-platforms',title:'1. A free label does not mean equal quality - check before investing time',paragraphs:[`Plenty of free learning resources exist, including freeCodeCamp, The Odin Project, MDN, and university OpenCourseWare, but they solve different problems, and picking the wrong one for your actual goal can waste weeks. Before enrolling in anything, ask whether it produces something you can point to afterward, a working project or a portfolio piece, or whether it only produces completed reading with nothing to show for it.`,`Check three signals before committing time: how recently the material was updated, since a course written for an old language syntax teaches habits you will have to unlearn later; whether exercises are actually checked automatically or left entirely to self-assessment; and whether a visible community of other learners exists to ask when you get stuck.`,`This guide follows one concrete running example: a learner who has already finished the how-websites-work and python-problem-solving lessons on this site wants to go deeper into full-stack development and also start contributing to an open-source project. The rest of the guide sticks to that goal rather than trying to cover every possible learning path at once.`]},
{id:'match-platform-goal',title:'2. Match the platform type to what you are actually trying to learn',paragraphs:[`freeCodeCamp is best treated as a structured, project-checked curriculum: it sequences topics for you and requires working, automatically graded code to pass each section, which suits someone who wants a guided path and a portfolio of small certified projects without having to plan the sequence themselves.`,`The Odin Project leans harder on building real, ungraded projects and stitching together outside resources, including MDN, into one full-stack path; it suits a learner who can tolerate some ambiguity and wants practice that feels closer to real professional work than a fully graded course does.`,`MDN and university OpenCourseWare serve yet another role: MDN is a reference to look something up while you are building something else, not a start-to-finish course, while OpenCourseWare lecture and problem-set material suits learning the theory behind a topic, such as data structures or algorithms, in depth, rather than shipping a project quickly. Pick one primary path for structure, and treat the others as lookups rather than starting three curricula at once.`]},
{id:'first-contribution-safely',title:'3. Read before you touch anything: preparing a first open-source contribution',paragraphs:[`Before writing any code for someone else's project, read its CONTRIBUTING file and its code of conduct if one exists. These files state the expected workflow, coding style, how commit messages should read, and whether an issue or discussion is required before a pull request will even be reviewed. Skipping this step is the single most common reason a first-time pull request gets closed without a real review.`,`Look specifically for issues labeled "good first issue" or "help wanted." Maintainers use these labels to flag work scoped small enough for someone unfamiliar with the codebase, and picking one respects both your time and theirs. A documentation fix, a broken link, or one missing test case is a reasonable and welcome first contribution; a large refactor is not.`,`Comment on the issue before starting, stating plainly what you plan to do, and ask to be assigned if the project uses that convention. This avoids two people duplicating the same fix, and it gives a maintainer the chance to say the approach will not be accepted before you spend hours implementing it.`],language:'CONTRIBUTING.md excerpt',code:`## Before you open a pull request
- Search open issues before filing a new one.
- Comment on the issue and wait to be assigned before starting work.
- Keep pull requests small: one fix or one feature per PR.
- Run "npm test" locally; CI will re-run the same checks.`},
{id:'contribution-mechanics',title:'4. Keep the change small enough to review in one sitting',paragraphs:[`The mechanical steps are familiar from any Git workflow: fork the repository, create a focused branch, make the change, and open a pull request. The standard a first-time outside contributor should hold themselves to is stricter than for an internal teammate: one small, self-contained change per pull request, with no unrelated formatting or file reorganization mixed in alongside it.`,`After forking on the host's website, clone your fork locally and add the original project as a second remote, conventionally named upstream, so you can pull in its latest changes without disturbing your own fork's history.`,`Write a pull request description stating what changed and why, and link the issue it addresses. If automated checks such as tests or linters run on the pull request, read their output before asking a human to look; fixing a failing check yourself is faster for everyone than waiting for a reviewer to leave a comment asking you to fix it.`],language:'Terminal',code:`git clone https://github.com/your-username/project.git
cd project
git remote add upstream https://github.com/original-owner/project.git
git switch -c fix/typo-in-readme
# edit, then:
git add README.md
git commit -m "Fix typo in installation instructions"
git push origin fix/typo-in-readme`},
{id:'vet-community',title:'5. Vet a Discord or forum before treating its answers as reliable',paragraphs:[`A community can accelerate learning or waste it, depending on whether questions get real, checked answers or only quick guesses. Before relying on one, lurk for a few days: search its history for a question similar to one you might ask, and see whether it received a substantive reply or was left unanswered.`,`Signals worth looking for: pinned resources and a maintained FAQ suggest active moderation; separate channels for help versus general chat suggest the community values focused discussion; and replies that explain their reasoning, rather than only pasting a code snippet with no context, suggest experienced members are actually present and engaged.`,`Signals to avoid: a channel dominated by self-promotion or referral links, questions that scroll past unanswered for days at a time, or moderators who are effectively absent. A community that is mostly noise will not save you any time over just searching the official documentation yourself, no matter how large its member count looks on the surface.`]},
{id:'sustainable-routine',title:'6. Combine a platform, a contribution, and a community into one routine',paragraphs:[`Returning to the running example: the learner uses The Odin Project as the primary structured path, keeps MDN open as a reference while building, picks one small good-first-issue to contribute per month rather than restlessly searching for a new project every week, and joins one vetted community tied to the primary platform rather than five loosely related servers pulling attention in different directions.`,`Measure progress by output, not hours logged. A merged pull request, a finished project from the curriculum, or a clearly answered question you can point back to later are all better evidence of real progress than a streak counter or a completion percentage.`,`Revisit the evaluation criteria from section one every few months. A platform or community that was active and well-moderated a year ago can go quiet, and a routine built for a complete beginner should evolve once you are past your first few contributions and projects and are ready for more ambiguity.`]}],exercise:['List two questions to ask before committing time to a free learning platform.','Explain why reading CONTRIBUTING.md before coding matters for a first pull request.','Name one signal that a Discord or forum community is mostly noise.'],answer:'Ask whether the platform produces something concrete to show afterward, and whether its material is current enough not to teach outdated habits. Reading CONTRIBUTING.md first matters because it states the expected workflow and review process, and skipping it is the most common reason a first pull request gets closed without review. A community dominated by self-promotion links or with questions left unanswered for days is a strong sign it is mostly noise.',glossary:[['CONTRIBUTING.md','A file in a repository stating the expected workflow for outside contributions.'],['Good first issue','A label maintainers use to flag work scoped small enough for a newcomer.'],['OpenCourseWare (OCW)','Freely published university lecture and course material, such as MIT OCW.'],['Upstream remote','A second Git remote pointing at the original repository a fork was copied from.']],sources:[{title:'The Odin Project: About',url:'https://www.theodinproject.com/about'},{title:'Open Source Guides: How to Contribute',url:'https://opensource.guide/how-to-contribute/'}]});


